function generateRadicalMap() {
  // 1. Grouping Phase
  // We use a temporary map to accumulate the words.
  const tempMap: Record<string, { words: WordData[]; radical_number: number }> =
    // Hard-coded mapping of radicals to avoid breaking glyph mappings (pronouns are hard-coded...)
    {
      "bodily-action": { words: [], radical_number: -1 },
      "conceptual-relation": { words: [], radical_number: -1 },
      movement: { words: [], radical_number: -1 },
      earth: { words: [], radical_number: -1 },
      body: { words: [], radical_number: -1 },
      "spatial-relation": { words: [], radical_number: -1 },
      beast: { words: [], radical_number: -1 },
      "wood/plant": { words: [], radical_number: -1 },
      pronoun: { words: [], radical_number: -1 },
      water: { words: [], radical_number: -1 },
      location: { words: [], radical_number: -1 },
      "mental-action": { words: [], radical_number: -1 },
      negative: { words: [], radical_number: -1 },
      time: { words: [], radical_number: -1 },
      junction: { words: [], radical_number: -1 },
      sapient: { words: [], radical_number: -1 },
      communication: { words: [], radical_number: -1 },
      "physical-property": { words: [], radical_number: -1 },
      color: { words: [], radical_number: -1 },
      family: { words: [], radical_number: -1 },
      vehicle: { words: [], radical_number: -1 },
      geometric: { words: [], radical_number: -1 },
      number: { words: [], radical_number: -1 },
      fire: { words: [], radical_number: -1 },
    };

  for (const word of WORD_DATA) {
    // If the radical group doesn't exist yet, initialize it
    if (!tempMap[word.radical]) {
      // radical_number is a placeholder (-1) until the sorting phase
      tempMap[word.radical] = { words: [], radical_number: -1 };
    }
    tempMap[word.radical].words.push(word);
  }

  const entries = Object.entries(tempMap);

  const sortedRadicalMap: Record<
    string,
    { words: WordData[]; radical_number: number }
  > = {};

  entries.forEach(([key, value], index) => {
    // Assign the new sequential number (0, 1, 2...) based on sorted position
    value.radical_number = index;

    // Add to the new object (modern JS runtimes preserve insertion order)
    sortedRadicalMap[key] = value;
  });

  return sortedRadicalMap;
}

export const RADICAL_MAP = generateRadicalMap();
