import { createLevelBuilder } from "../../../levels/types";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import {
  BLUEPRINT_TILE_COUNT,
  type MysteryAvailableIndicators,
  type MysteryAvailableSlots,
  type MysteryAvailableTileGroups,
} from "./client";

export const BLUEPRINT_LEVEL_ID = "mystery-blueprint-level";

const blueprintLevelBuilder = createLevelBuilder<
  MysteryAvailableSlots,
  AllAvailableTiles,
  MysteryAvailableIndicators,
  MysteryAvailableTileGroups
>()
  .setTitle("Blueprint")
  .addSlot("17,-8", "mystery-empty-slot")
  .addSlot("18,-8", "mystery-empty-slot")
  .addSlot("19,-8", "mystery-empty-slot")
  .addSlot("17,-7", "mystery-empty-slot")
  .addSlot("18,-7", "mystery-empty-slot");

Array.from(
  { length: BLUEPRINT_TILE_COUNT },
  (_, idx) => `mystery-blueprint-${idx}-tile` as AllAvailableTiles,
).forEach((tile) => {
  blueprintLevelBuilder.addTileToBank(
    tile,
    1,
    { renderer: tile, props: {} },
    "blueprint",
  );
});

const BLUEPRINT_SOLUTION: Record<string, string> = {
  "17,-8": "mystery-blueprint-1-tile",
  "18,-8": "mystery-blueprint-4-tile",
  "19,-8": "mystery-blueprint-2-tile",
  "17,-7": "mystery-blueprint-0-tile",
  "18,-7": "mystery-blueprint-3-tile",
};

blueprintLevelBuilder.setSolution(BLUEPRINT_SOLUTION);

export const blueprintLevel = blueprintLevelBuilder.build();
