export type ToolboxMode =
  | "tile"
  | "move"
  | "draw"
  | "erase"
  | "ping"
  | "disconnected";

export type SyncAvailability =
  | "force-offline"
  | "intermittent-offline"
  | "online-available";

export type SyncChoice = "online" | "offline";

export const TILE_TEXT_MAP_LOCAL_STORAGE_KEY = "tile-text-map";
const LEVEL_CHECKBOXES_LOCAL_STORAGE_KEY = "tileLevelCheckboxes";
export const SOLVED_LEVELS_LOCAL_STORAGE_KEY = "tile-round-solved-levels";

function persistLevelCheckboxes(checkboxes: Record<string, boolean>): void {
  if (typeof window === "undefined") {
    return;
  }
  try {
    localStorage.setItem(
      LEVEL_CHECKBOXES_LOCAL_STORAGE_KEY,
      JSON.stringify(checkboxes),
    );
  } catch (error) {
    console.warn(
      "[ClientState] Failed to save level checkboxes to localStorage:",
      error,
    );
  }
}

function persistSolvedLevels(solvedLevels: Set<string>): void {
  if (typeof window === "undefined") {
    return;
  }
  try {
    localStorage.setItem(
      SOLVED_LEVELS_LOCAL_STORAGE_KEY,
      JSON.stringify(Array.from(solvedLevels)),
    );
  } catch (error) {
    console.warn(
      "[ClientState] Failed to save solved levels to localStorage:",
      error,
    );
  }
}

function initializeSolvedLevels(): Set<string> {
  if (typeof window === "undefined") {
    return new Set();
  }
  try {
    const stored = localStorage.getItem(SOLVED_LEVELS_LOCAL_STORAGE_KEY);
    if (stored) {
      const parsed = JSON.parse(stored) as string[];
      return new Set(parsed);
    }
    return new Set();
  } catch (error) {
    console.warn(
      "[ClientState] Failed to load solved levels from localStorage:",
      error,
    );
    return new Set();
  }
}

function initializeLevelCheckboxes(): Record<string, boolean> {
  if (typeof window === "undefined") {
    return { "intro-crossword-level": true };
  }
  try {
    const stored = localStorage.getItem(LEVEL_CHECKBOXES_LOCAL_STORAGE_KEY);
    if (stored) {
      const parsed = JSON.parse(stored) as Record<string, boolean>;
      // If we have stored data, return it
      if (Object.keys(parsed).length > 0) {
        return parsed;
      }
    }
    // If no stored data or empty, default to checking intro-crossword-level
    const defaultCheckboxes = { "intro-crossword-level": true };
    persistLevelCheckboxes(defaultCheckboxes);
    return defaultCheckboxes;
  } catch (error) {
    console.warn(
      "[ClientState] Failed to load level checkboxes from localStorage:",
      error,
    );
    const defaultCheckboxes = { "intro-crossword-level": true };
    persistLevelCheckboxes(defaultCheckboxes);
    return defaultCheckboxes;
  }
}

function createCoordinateToLevelIdMap(
  availableLevels: Record<string, LevelDisplay>,
): Record<string, string> {
  const coordinateToLevelIdMap: Record<string, string> = {};
  for (const [levelId, level] of Object.entries(availableLevels)) {
    for (const hexId of Object.keys(level.level)) {
      coordinateToLevelIdMap[hexId] = levelId;
    }
  }
  return coordinateToLevelIdMap;
}

function createFrozenLevelSolutions(
  levels: Record<string, LevelDisplay>,
): Map<string, Record<HexId, string>> {
  const solutions = new Map<string, Record<HexId, string>>();
  for (const [levelId, level] of Object.entries(levels)) {
    solutions.set(levelId, level.solution);
  }
  return solutions;
}

/**
 * Finds submission level IDs by puzzle slug.
 * Returns a map from puzzle slug to submission level ID.
 */
function createPuzzleSlugToSubmissionLevelMap(): Map<string, string> {
  const map = new Map<string, string>();
  for (const [levelId, levelData] of Object.entries(allLevels)) {
    const level = levelData as LevelData;
    if (level.submission?.puzzleSlug) {
      map.set(level.submission.puzzleSlug, levelId);
    }
  }
  return map;
}

/**
 * Creates LevelDisplay objects from allLevels based on checkbox state.
 * Only includes levels that are checked in the checkboxes.
 * Applies locked tile transform for submission levels that don't meet unlock requirements.
 */
function createLevelsFromCheckboxes(
  checkboxes: Record<string, boolean>,
  solvedLevels: Set<string>,
): Record<string, LevelDisplay> {
  const levels: Record<string, LevelDisplay> = {};

  for (const [levelId, levelData] of Object.entries(allLevels)) {
    // Only include levels that are checked
    if (checkboxes[levelId]) {
      const level = levelData as LevelData;
      const fogOfWarData = levelFogOfWarMap[levelId];
      const backgroundImageUrl = levelBackgroundImageMap[levelId];

      // Check if this is a submission level that should be locked
      let shouldBeLocked = false;
      let ratioText = "";
      let lockedGivenTiles: Partial<
        Record<string, { renderer: string; props: Record<string, unknown> }>
      > = {};

      if (level.submission?.puzzleSlug) {
        // Find the unlock definition for this puzzle slug
        const definition =
          FINAL_LEVEL_UNLOCK_DEFINITIONS[level.submission.puzzleSlug];
        if (definition) {
          // Count how many required levels are solved
          const solvedCount = definition.levelIds.filter((requiredLevelId) =>
            solvedLevels.has(requiredLevelId),
          ).length;

          // In client-only mode, we assume puzzles are unlocked, so we only check level requirements
          // If not enough levels are solved, lock the submission level
          if (solvedCount < definition.requiredCount) {
            shouldBeLocked = true;
            ratioText = `${solvedCount}/${definition.requiredCount}`;

            // Apply locked tile transform: set givenTiles with locked-tile renderer
            const lockedTiles: Partial<
              Record<
                string,
                { renderer: string; props: Record<string, unknown> }
              >
            > = {};
            for (const hexId of Object.keys(level.level)) {
              lockedTiles[hexId] = {
                renderer: "locked-tile",
                props: { ratioText },
              };
            }
            lockedGivenTiles = lockedTiles;
          }
        }
      }

      levels[levelId] = {
        id: levelId,
        state: solvedLevels.has(levelId)
          ? "solved"
          : shouldBeLocked
            ? "locked"
            : "unlocked",
        level: shouldBeLocked
          ? Object.fromEntries(
              Object.entries(level.level).map(([hexId, _slotData]) => [
                hexId,
                {
                  slot: "empty-glyph-slot", // Default slot for locked levels
                  slotProps: {},
                },
              ]),
            )
          : level.level,
        tileBank: shouldBeLocked ? [] : level.tileBank,
        clues: shouldBeLocked ? {} : level.clues,
        indicators: shouldBeLocked ? {} : level.indicators,
        givenTiles: shouldBeLocked
          ? lockedGivenTiles
          : ((level.givenTiles ?? {}) as Partial<
              Record<
                string,
                { renderer: string; props: Record<string, unknown> }
              >
            >),
        submission: level.submission,
        regionTitle: level.regionTitle,
        flavorText: shouldBeLocked ? "" : level.flavorText,
        levelFlavorText: shouldBeLocked ? "" : level.levelFlavorText,
        levelTitle: shouldBeLocked ? "" : level.levelTitle,
        solvedDocumentChangeHash: undefined,
        solution: shouldBeLocked ? {} : level.solution,
        fogOfWarHexes: fogOfWarData ? Object.keys(fogOfWarData) : [],
        backgroundImageUrl,
      };
    }
  }

  return levels;
}

export type ConnectionMode = "connecting" | "connected" | "disconnected";

export type LevelOutline = {
  origin: HexId;
  svgString: string;
  offsetX: number;
  offsetY: number;
};

export type LevelInnerLine = {
  origin: HexId;
  svgString: string;
  offsetX: number;
  offsetY: number;
};

export type LevelHatching = {
  svgString: string;
  origin: HexId;
  offsetX: number;
  offsetY: number;
};

export type LevelTitle = {
  regionTitle: string;
  levelTitle: string;
  flavorText: string | string[];
  levelFlavorText: string | string[];
  levelId: string;
};

type ClientState = {
  documentIdMap: Record<string, string>;
  offlineDocumentIdMap: Record<string, string>;
  syncAvailability: SyncAvailability;
  syncChoice: SyncChoice;
  setSyncAvailability: (syncAvailability: SyncAvailability) => void;
  setSyncChoice: (syncChoice: SyncChoice) => void;
  focusedHex: HexId | null;
  setFocusedHex: (hexId: HexId) => void;
  clearFocusedHex: () => void;
  allLevels: Record<string, LevelDisplay>;
  coordinateToLevelIdMap: Record<string, string>;
  hexToSlotMap: Map<
    HexId,
    { slot: AllLevelsAvailableSlots; slotProps: Record<string, unknown> }
  >;
  hexToGivenTileMap: Map<HexId, TileVariantDefinition<AllLevelsAvailableTiles>>;
  hexToLockedTileMap: Map<
    HexId,
    TileVariantDefinition<AllLevelsAvailableTiles>
  >;
  hexToIndicatorMap: Map<HexId, IndicatorData[]>;
  hexToSubmissionMap: Map<HexId, SubmissionData>;
  focusedLevelTitle: LevelTitle | null;
  levelOutlines: Map<string, LevelOutline>;
  levelInnerLines: Map<string, LevelInnerLine>;
  levelHatching: Map<string, LevelHatching>;
  levelToTileIdToDefinitionMap: Map<
    string,
    Map<string, TileVariantDefinition<AllLevelsAvailableTiles>>
  >;
  frozenLevelSolutions: Map<string, Record<HexId, string>>;
  setLevels: (levels: Record<string, LevelDisplay>) => void;
  bankWidth: 1 | 3 | 5;
  setBankWidth: (width: 1 | 3 | 5) => void;
  hexSize: number;
  setHexSize: (hexSize: number) => void;
  tileBankHexSize: number;
  setTileBankHexSize: (tileBankHexSize: number) => void;

  peerFoci: Record<string, { hexId: HexId; timestamp: number }>;
  setPeerFoci: (clientId: string, focus: HexId, timestamp: number) => void;
  clearStalePeerFoci: (staleThresholdMs: number) => void;
  peerPings: Record<string, { hexId: HexId; timestamp: number }>;
  setPeerPings: (clientId: string, hexId: HexId, timestamp: number) => void;
  clearStalePeerPings: (staleThresholdMs: number) => void;
  ownPing: { hexId: HexId; timestamp: number } | null;
  setOwnPing: (hexId: HexId, timestamp: number) => void;
  clearOwnPing: () => void;
  clearStaleOwnPing: (staleThresholdMs: number) => void;

  connectionMode: ConnectionMode;
  setConnectionMode: (connectionMode: ConnectionMode) => void;
  toolboxMode: ToolboxMode;
  setToolboxMode: (toolboxMode: ToolboxMode) => void;
  tileIdToTileTextMap: Map<string, string>;
  setTileText: (tileId: string, tileText: string) => void;
  setTileTextMap: (tileTextMap: Map<string, string>) => void;
  setDocumentId: (purpose: string, documentId: string) => void;
  setOfflineDocumentId: (purpose: string, documentId: string) => void;
  levelCheckboxes: Record<string, boolean>;
  setLevelCheckbox: (levelId: string, checked: boolean) => void;
  setLevelCheckboxes: (updates: Record<string, boolean>) => void;
  toggleLevelCheckbox: (levelId: string) => void;
  solvedLevels: Set<string>;
  markLevelSolved: (levelId: string) => void;
  onLevelSolvedCallback?: (levelId: string, levelTitle: string) => void;
  markLevelUnsolved: (levelId: string) => void;
};

export const useClientState = create<ClientState>((set, get) => {
  // Initialize levels from checkboxes on store creation
  const initialCheckboxes = initializeLevelCheckboxes();
  const initialSolvedLevels = initializeSolvedLevels();
  const initialLevels = createLevelsFromCheckboxes(
    initialCheckboxes,
    initialSolvedLevels,
  );

  return {
    documentIdMap: {},
    offlineDocumentIdMap: {},
    focusedHex: null,
    focusedLevelTitle: null,
    connectionMode: "disconnected",
    onLevelSolvedCallback: undefined,
    setConnectionMode: (connectionMode: ConnectionMode) => {
      set({ connectionMode });
    },
    syncAvailability: "online-available",
    setSyncAvailability: (syncAvailability: SyncAvailability) => {
      set({ syncAvailability });
    },
    syncChoice: "offline",
    setSyncChoice: (syncChoice: SyncChoice) => {
      set({ syncChoice });
    },
    setDocumentId: (purpose: string, documentId: string) => {
      set((state) => ({
        ...state,
        documentIdMap: {
          ...state.documentIdMap,
          [purpose]: documentId,
        },
      }));
    },
    setOfflineDocumentId: (purpose: string, documentId: string) => {
      set((state) => ({
        ...state,
        offlineDocumentIdMap: {
          ...state.offlineDocumentIdMap,
          [purpose]: documentId,
        },
      }));
    },
    levelCheckboxes: initializeLevelCheckboxes(),
    setLevelCheckbox: (levelId: string, checked: boolean) => {
      const state = get();
      const newCheckboxes = {
        ...state.levelCheckboxes,
        [levelId]: checked,
      };
      persistLevelCheckboxes(newCheckboxes);
      set({ levelCheckboxes: newCheckboxes });
      // Update levels after state update completes
      const newLevels = createLevelsFromCheckboxes(
        newCheckboxes,
        state.solvedLevels,
      );
      get().setLevels(newLevels);
    },
    setLevelCheckboxes: (updates: Record<string, boolean>) => {
      const state = get();
      const newCheckboxes = {
        ...state.levelCheckboxes,
        ...updates,
      };
      persistLevelCheckboxes(newCheckboxes);
      set({ levelCheckboxes: newCheckboxes });
      // Update levels after state update completes
      const newLevels = createLevelsFromCheckboxes(
        newCheckboxes,
        state.solvedLevels,
      );
      get().setLevels(newLevels);
    },
    toggleLevelCheckbox: (levelId: string) => {
      const state = get();
      const current = state.levelCheckboxes[levelId] ?? false;
      const newCheckboxes = {
        ...state.levelCheckboxes,
        [levelId]: !current,
      };
      persistLevelCheckboxes(newCheckboxes);
      set({ levelCheckboxes: newCheckboxes });
      // Update levels after state update completes
      const newLevels = createLevelsFromCheckboxes(
        newCheckboxes,
        state.solvedLevels,
      );
      get().setLevels(newLevels);
    },
    solvedLevels: initialSolvedLevels,
    markLevelSolved: (levelId: string) => {
      const state = get();
      const newSolvedLevels = new Set(state.solvedLevels);
      newSolvedLevels.add(levelId);
      persistSolvedLevels(newSolvedLevels);
      set({ solvedLevels: newSolvedLevels });

      const newCheckboxes = { ...state.levelCheckboxes };
      let hasNewUnlocks = false;

      // Unlock adjacent levels by adding them to checkboxes
      const adjacentLevels =
        levelAdjacencyMap[levelId as keyof typeof levelAdjacencyMap] ?? [];

      for (const adjacentLevelId of adjacentLevels) {
        // Only unlock if not already checked
        if (!newCheckboxes[adjacentLevelId]) {
          newCheckboxes[adjacentLevelId] = true;
          hasNewUnlocks = true;
        }
      }

      // Check for submission level unlocks based on FINAL_LEVEL_UNLOCK_DEFINITIONS
      const puzzleSlugToSubmissionLevel =
        createPuzzleSlugToSubmissionLevelMap();

      for (const [puzzleSlug, definition] of Object.entries(
        FINAL_LEVEL_UNLOCK_DEFINITIONS,
      )) {
        // Check if this solved level is part of the unlock requirements
        if (!definition.levelIds.includes(levelId)) {
          continue;
        }

        // Count how many required levels are now solved
        const solvedCount = definition.levelIds.filter((requiredLevelId) =>
          newSolvedLevels.has(requiredLevelId),
        ).length;

        // If enough levels are solved, unlock the submission level
        if (solvedCount >= definition.requiredCount) {
          const submissionLevelId = puzzleSlugToSubmissionLevel.get(puzzleSlug);
          if (submissionLevelId && !newCheckboxes[submissionLevelId]) {
            newCheckboxes[submissionLevelId] = true;
            hasNewUnlocks = true;
          }
        }
      }

      // If we unlocked any levels, persist the updated checkboxes
      if (hasNewUnlocks) {
        persistLevelCheckboxes(newCheckboxes);
        set({ levelCheckboxes: newCheckboxes });
      }

      // Update levels to reflect solved state and any newly unlocked levels
      const newLevels = createLevelsFromCheckboxes(
        hasNewUnlocks ? newCheckboxes : state.levelCheckboxes,
        newSolvedLevels,
      );
      get().setLevels(newLevels);

      // Call the callback if provided
      const stateAfterUpdate = get();
      const callback = stateAfterUpdate.onLevelSolvedCallback;
      if (typeof callback === "function") {
        const level = allLevels[levelId as keyof typeof allLevels];
        if (level) {
          callback(levelId, level.levelTitle);
        }
      }
    },
    markLevelUnsolved: (levelId: string) => {
      const state = get();
      if (!state.solvedLevels.has(levelId)) {
        return;
      }

      const newSolvedLevels = new Set(state.solvedLevels);
      newSolvedLevels.delete(levelId);
      persistSolvedLevels(newSolvedLevels);
      set({ solvedLevels: newSolvedLevels });

      const newLevels = createLevelsFromCheckboxes(
        state.levelCheckboxes,
        newSolvedLevels,
      );
      get().setLevels(newLevels);
    },
    setFocusedHex: (hexId: HexId) => {
      set({ focusedHex: null });
      set({ focusedLevelTitle: null });

      const state = get();
      const levelId = state.coordinateToLevelIdMap[hexId];
      if (levelId) {
        const level = state.allLevels[levelId];
        const isSubmission = level.submission?.hexId === hexId;
        // Check if level is unlocked: either checked in checkboxes or state is unlocked/solved
        const isUnlocked =
          state.levelCheckboxes[levelId] ||
          level.state === "unlocked" ||
          level.state === "solved";
        if (!isSubmission && isUnlocked) {
          set({
            focusedLevelTitle: {
              regionTitle: level.regionTitle,
              levelTitle: level.levelTitle,
              flavorText: level.flavorText,
              levelFlavorText: level.levelFlavorText,
              levelId,
            },
          });
          set({ focusedHex: hexId });
        }
      }
    },
    clearFocusedHex: () => {
      set({ focusedHex: null });
      set({ focusedLevelTitle: null });
    },
    allLevels: initialLevels,
    coordinateToLevelIdMap: createCoordinateToLevelIdMap(initialLevels),
    hexToSlotMap: createHexToSlotMap(initialLevels),
    hexToIndicatorMap: createHexToIndicatorMap(initialLevels),
    hexToGivenTileMap: createHexToGivenTileMap(initialLevels),
    hexToLockedTileMap: new Map(),
    hexToSubmissionMap: createHexToSubmissionMap(initialLevels),
    levelOutlines: createLevelOutlines(initialLevels, 120),
    levelInnerLines: createLevelInnerLines(initialLevels, 120),
    levelHatching: createLevelHatching(initialLevels, 120),
    levelToTileIdToDefinitionMap:
      createLevelToTileIdToDefinitionMap(initialLevels),
    frozenLevelSolutions: createFrozenLevelSolutions(initialLevels),
    tileIdToTileTextMap: initializeTileIdToTileTextMap(),

    setTileText: (tileId: string, tileText: string) => {
      const storageString = localStorage.getItem(
        TILE_TEXT_MAP_LOCAL_STORAGE_KEY,
      );
      const tileTextInfo = storageString ? JSON.parse(storageString) : {};
      tileTextInfo[tileId] = tileText;
      localStorage.setItem(
        TILE_TEXT_MAP_LOCAL_STORAGE_KEY,
        JSON.stringify(tileTextInfo),
      );
      set((state) => ({
        ...state,
        tileIdToTileTextMap: new Map(state.tileIdToTileTextMap).set(
          tileId,
          tileText,
        ),
      }));
    },
    setTileTextMap: (tileTextMap: Map<string, string>) => {
      const tileTextObject: Record<string, string> = {};
      for (const [key, gloss] of tileTextMap.entries()) {
        tileTextObject[key] = gloss;
      }
      localStorage.setItem(
        TILE_TEXT_MAP_LOCAL_STORAGE_KEY,
        JSON.stringify(tileTextObject),
      );

      set((state) => ({
        ...state,
        tileIdToTileTextMap: tileTextMap,
      }));
    },
    toolboxMode: "tile",
    setToolboxMode: (toolboxMode: ToolboxMode) => {
      set({ toolboxMode });
    },
    peerFoci: {},
    setPeerFoci: (clientId: string, focus: HexId, timestamp: number) => {
      set((state) => ({
        ...state,
        peerFoci: {
          ...state.peerFoci,
          [clientId]: { hexId: focus, timestamp },
        },
      }));
    },
    clearStalePeerFoci: (staleThresholdMs: number) => {
      set((state) => {
        const now = Date.now();
        const staleClientIds: string[] = [];

        for (const [clientId, focusData] of Object.entries(state.peerFoci)) {
          if (now - focusData.timestamp > staleThresholdMs) {
            staleClientIds.push(clientId);
          }
        }

        if (staleClientIds.length === 0) {
          return state;
        }

        const newPeerFoci = { ...state.peerFoci };

        for (const clientId of staleClientIds) {
          // eslint-disable-next-line @typescript-eslint/no-dynamic-delete -- we need to remove stale peer foci
          delete newPeerFoci[clientId];
        }

        return {
          ...state,
          peerFoci: newPeerFoci,
        };
      });
    },
    peerPings: {} satisfies Record<string, { hexId: HexId; timestamp: number }>,
    setPeerPings: (clientId: string, hexId: HexId, timestamp: number) => {
      set((state) => ({
        ...state,
        peerPings: {
          ...state.peerPings,
          [clientId]: { hexId, timestamp },
        },
      }));
    },
    clearStalePeerPings: (staleThresholdMs: number) => {
      set((state) => {
        const now = Date.now();
        const staleClientIds: string[] = [];

        for (const [clientId, pingData] of Object.entries(state.peerPings)) {
          if (now - pingData.timestamp > staleThresholdMs) {
            staleClientIds.push(clientId);
          }
        }

        if (staleClientIds.length === 0) {
          return state;
        }

        const newPeerPings = { ...state.peerPings };

        for (const clientId of staleClientIds) {
          // eslint-disable-next-line @typescript-eslint/no-dynamic-delete -- we need to remove stale peer pings
          delete newPeerPings[clientId];
        }

        return {
          ...state,
          peerPings: newPeerPings,
        };
      });
    },
    ownPing: null,
    setOwnPing: (hexId: HexId, timestamp: number) => {
      set({ ownPing: { hexId, timestamp } });
    },
    clearOwnPing: () => {
      set({ ownPing: null });
    },
    clearStaleOwnPing: (staleThresholdMs: number) => {
      set((state) => {
        if (!state.ownPing) {
          return state;
        }
        const now = Date.now();
        if (now - state.ownPing.timestamp > staleThresholdMs) {
          return { ...state, ownPing: null };
        }
        return state;
      });
    },
    setLevels: (levels) => {
      set({ allLevels: levels });
      set({ coordinateToLevelIdMap: createCoordinateToLevelIdMap(levels) });
      set({ hexToSlotMap: createHexToSlotMap(levels) });
      set({ hexToIndicatorMap: createHexToIndicatorMap(levels) });
      set({ hexToGivenTileMap: createHexToGivenTileMap(levels) });
      set({ hexToSubmissionMap: createHexToSubmissionMap(levels) });
      set({
        levelToTileIdToDefinitionMap:
          createLevelToTileIdToDefinitionMap(levels),
      });
      set({
        levelOutlines: createLevelOutlines(levels, get().hexSize),
      });
      set({
        levelInnerLines: createLevelInnerLines(levels, get().hexSize),
      });
      set({
        levelHatching: createLevelHatching(levels, get().hexSize),
      });
      set({
        frozenLevelSolutions: createFrozenLevelSolutions(levels),
      });
      // Clear locked tiles (infrastructure kept but disabled)
      set({ hexToLockedTileMap: new Map() });
    },
    bankWidth: 3,
    setBankWidth: (width) => {
      set({ bankWidth: width });
    },
    hexSize: 120,
    setHexSize: (size) => {
      set({ hexSize: size });
    },
    tileBankHexSize: 60,
    setTileBankHexSize: (tileBankHexSize) => {
      set({ tileBankHexSize });
    },
  };
});

// Custom hooks for derived state with automatic subscriptions

/**
 * Hook that returns whether a hex is bright (not dimmed)
 * Automatically subscribes to focusedHex and coordinateToLevelIdMap
 */
export function useIsBrightTile(hexId: HexId): boolean {
  return useClientState((state) => {
    if (!state.focusedHex) {
      return true; // Everything is bright when nothing is focused
    }
    const focusedLevelId = state.coordinateToLevelIdMap[state.focusedHex];
    const hexLevelId = state.coordinateToLevelIdMap[hexId];
    return focusedLevelId === hexLevelId;
  });
}

/**
 * Hook that returns whether a hex is in the currently active/focused level
 * Automatically subscribes to focusedHex and coordinateToLevelIdMap
 */
export function useIsInActiveLevel(hexId: HexId): boolean {
  return useClientState((state) => {
    if (!state.focusedHex) {
      return false;
    }
    const focusedLevelId = state.coordinateToLevelIdMap[state.focusedHex];
    const hexLevelId = state.coordinateToLevelIdMap[hexId];
    return focusedLevelId === hexLevelId;
  });
}

export function useIsInSolvedLevel(hexId: HexId): boolean {
  return useClientState((state) => {
    const hexLevelId = state.coordinateToLevelIdMap[hexId];
    const level = state.allLevels[hexLevelId];
    return level?.state === "solved";
  });
}
/**
 * Hook that returns the current level based on focusedHex
 * Automatically subscribes to focusedHex, coordinateToLevelIdMap, and allLevels
 */
export function useCurrentLevel(): LevelDisplay | null {
  return useClientState((state) => {
    if (!state.focusedHex) {
      return null;
    }
    const levelId = state.coordinateToLevelIdMap[state.focusedHex];
    return state.allLevels[levelId] ?? null;
  });
}

/**
 * Hook that returns the current level ID based on focusedHex
 * Automatically subscribes to focusedHex and coordinateToLevelIdMap
 */
export function useCurrentLevelId(): string | null {
  return useClientState((state) => {
    if (!state.focusedHex) {
      return null;
    }
    return state.coordinateToLevelIdMap[state.focusedHex] ?? null;
  });
}

/**
 * Hook that returns whether any level is currently focused
 * Automatically subscribes to focusedHex
 */
export function useIsFocusedOnLevel(): boolean {
  return useClientState((state) => state.focusedHex !== null);
}

// Standalone utility functions (non-reactive, read state directly)

/**
 * Check if any level is currently focused (non-reactive)
 */
export function isFocusedOnLevel(): boolean {
  return useClientState.getState().focusedHex !== null;
}

/**
 * Get the current level ID (non-reactive)
 */
export function getCurrentLevelId(): string | null {
  const state = useClientState.getState();
  if (!state.focusedHex) {
    return null;
  }
  return state.coordinateToLevelIdMap[state.focusedHex] ?? null;
}

/**
 * Check if a hex belongs to a specific level (non-reactive)
 */
export function belongsToLevel(hexId: HexId, levelId: string): boolean {
  return useClientState.getState().coordinateToLevelIdMap[hexId] === levelId;
}

export function initializeTileIdToTileTextMap(): Map<string, string> {
  let storageString: string | null = null;
  if (typeof window !== "undefined") {
    storageString = localStorage.getItem(TILE_TEXT_MAP_LOCAL_STORAGE_KEY);
  }
  if (storageString) {
    const info = JSON.parse(storageString);
    const map = new Map<string, string>();
    for (const [key, value] of Object.entries(info)) {
      map.set(key, value as string);
    }
    return map;
  } else {
    return new Map();
  }
}
