import { type Clue } from "@hunt/frontend-client";
import { type LevelTransform } from "../activitiy-log/reduce-log-entries";
import { type HexId } from "../basic-hexagons/bounding-box";
import { type Solution } from "./solution";

// Thank you gemini
type Disjoint<T1 extends string, T2 extends string> =
  Extract<T1, T2> extends never ? true : false;

// Artisan Small Batch Peter code from here down though.
type RegionBuilder<
  AvailableSlots extends string = never,
  AvailableTiles extends string = never,
  AvailableIndicators extends string = never,
  AvailableTileGroups extends string = never,
> = {
  addSlotType: <NewSlotType extends string>(
    id: NewSlotType extends AvailableSlots
      ? `${Extract<NewSlotType, AvailableSlots>} has already been defined`
      : NewSlotType,
    renderer: ((props: Record<string, unknown>) => React.ReactNode) | null,
  ) => RegionBuilder<
    AvailableSlots | NewSlotType,
    AvailableTiles,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addTileType: <NewTileType extends string>(
    id: NewTileType extends AvailableTiles
      ? `${Extract<NewTileType, AvailableTiles>} has already been defined`
      : NewTileType,
    renderer: (props: Record<string, unknown>) => React.ReactNode,
  ) => RegionBuilder<
    AvailableSlots,
    AvailableTiles | NewTileType,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addIndicatorType: <NewIndicatorType extends string>(
    id: NewIndicatorType extends AvailableIndicators
      ? `${Extract<NewIndicatorType, AvailableIndicators>} has already been defined`
      : NewIndicatorType,
    renderer: (props: Record<string, unknown>) => React.ReactNode,
    config?: { hideWhenInactive?: boolean },
  ) => RegionBuilder<
    AvailableSlots,
    AvailableTiles,
    AvailableIndicators | NewIndicatorType,
    AvailableTileGroups
  >;
  addTileGroup: <NewTileGroup extends string>(
    id: NewTileGroup extends AvailableTileGroups
      ? `${Extract<NewTileGroup, AvailableTileGroups>} has already been defined`
      : NewTileGroup,
    name: string,
  ) => RegionBuilder<
    AvailableSlots,
    AvailableTiles,
    AvailableIndicators,
    AvailableTileGroups | NewTileGroup
  >;

  build: () => RegionDefinition<
    AvailableSlots,
    AvailableTiles,
    AvailableIndicators,
    AvailableTileGroups
  >;
};

type SlotDefinition = {
  renderer: ((props: Record<string, unknown>) => React.ReactNode) | null;
};

type TileDefinition = {
  renderer: (props: Record<string, unknown>) => React.ReactNode;
};

type IndicatorDefinition = {
  renderer: (props: Record<string, unknown>) => React.ReactNode;
  hideWhenInactive?: boolean;
};

type TileGroup = {
  name: string;
};

type Submission = {
  hexId: HexId;
  puzzleSlug: string;
};

export type RegionDefinition<
  AvailableSlots extends string,
  AvailableTiles extends string = never,
  AvailableIndicators extends string = never,
  AvailableTileGroups extends string = never,
> = {
  slots: Record<AvailableSlots, SlotDefinition>;
  tiles: Record<AvailableTiles, TileDefinition>;
  indicators: Record<AvailableIndicators, IndicatorDefinition>;
  tileGroups: Record<AvailableTileGroups, TileGroup>;
};

// Variant definition: identifies a specific (tile, props) pairing for a bank entry
export type TileVariantDefinition<AvailableTiles extends string = never> = {
  renderer: AvailableTiles; // the tile renderer id (must be a defined tile)
  props: Record<string, unknown>;
};

export const createRegionBuilder = <
  AvailableSlots extends string = never,
  AvailableTiles extends string = never,
  AvailableIndicators extends string = never,
  AvailableTileGroups extends string = never,
>(
  args?: RegionDefinition<
    AvailableSlots,
    AvailableTiles,
    AvailableIndicators,
    AvailableTileGroups
  >,
): RegionBuilder<
  AvailableSlots,
  AvailableTiles,
  AvailableIndicators,
  AvailableTileGroups
> => {
  const slots: Record<string, SlotDefinition> =
    args?.slots ?? ({} as Record<AvailableSlots, SlotDefinition>);
  const tiles: Record<string, TileDefinition> =
    args?.tiles ?? ({} as Record<AvailableTiles, TileDefinition>);
  const indicators: Record<string, IndicatorDefinition> =
    args?.indicators ??
    ({} as Record<AvailableIndicators, IndicatorDefinition>);
  const tileGroups: Record<string, TileGroup> =
    args?.tileGroups ?? ({} as Record<AvailableTileGroups, TileGroup>);
  return {
    addSlotType: <NewSlotType extends string>(
      id: NewSlotType extends AvailableSlots
        ? `${Extract<NewSlotType, AvailableSlots>} has already been defined`
        : NewSlotType,
      renderer: ((props: Record<string, unknown>) => React.ReactNode) | null,
    ) => {
      slots[id] = { renderer };
      return createRegionBuilder<
        AvailableSlots | NewSlotType,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups
      >({
        slots,
        tiles,
        indicators,
        tileGroups,
      });
    },
    addTileType: <NewTileType extends string>(
      id: NewTileType extends AvailableTiles
        ? `${Extract<NewTileType, AvailableTiles>} has already been defined`
        : NewTileType,
      renderer: (props: Record<string, unknown>) => React.ReactNode,
    ) => {
      tiles[id] = { renderer };
      return createRegionBuilder<
        AvailableSlots,
        AvailableTiles | NewTileType,
        AvailableIndicators,
        AvailableTileGroups
      >({
        slots,
        tiles,
        indicators,
        tileGroups,
      });
    },
    addIndicatorType: <NewIndicatorType extends string>(
      id: NewIndicatorType extends AvailableIndicators
        ? `${Extract<NewIndicatorType, AvailableIndicators>} has already been defined`
        : NewIndicatorType,
      renderer: (props: Record<string, unknown>) => React.ReactNode,
      config?: { hideWhenInactive?: boolean },
    ) => {
      indicators[id] = {
        renderer,
        hideWhenInactive: config?.hideWhenInactive ?? false,
      };
      return createRegionBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators | NewIndicatorType,
        AvailableTileGroups
      >({
        slots,
        tiles,
        indicators,
        tileGroups,
      });
    },
    addTileGroup: <NewTileGroup extends string>(
      id: NewTileGroup extends AvailableTileGroups
        ? `${Extract<NewTileGroup, AvailableTileGroups>} has already been defined`
        : NewTileGroup,
      name: string,
    ) => {
      tileGroups[id] = { name };
      return createRegionBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups | NewTileGroup
      >({
        slots,
        tiles,
        indicators,
        tileGroups,
      });
    },
    build: () => ({
      slots: slots as Record<AvailableSlots, SlotDefinition>,
      tiles: tiles as Record<AvailableTiles, TileDefinition>,
      indicators: indicators as Record<
        AvailableIndicators,
        IndicatorDefinition
      >,
      tileGroups: tileGroups as Record<AvailableTileGroups, TileGroup>,
    }),
  };
};

export type Level<
  AvailableSlots extends string = never,
  AvailableTiles extends string = never,
  UsedSlots extends HexId = never,
  AvailableIndicators extends string = never,
  AvailableTileGroups extends string = never,
  CurrentTileBank extends string = never,
> = {
  level: Record<
    UsedSlots,
    { slot: AvailableSlots; slotProps: Record<string, unknown> }
  >;
  tileBank: TileBank<CurrentTileBank, AvailableTiles, AvailableTileGroups>;
  givenTiles: Partial<Record<UsedSlots, TileVariantDefinition<AvailableTiles>>>;
  clues: Record<UsedSlots, Clue[]>;
  indicators: Record<
    UsedSlots,
    { type: AvailableIndicators; indicatorProps: Record<string, unknown> }[]
  >;
  submission?: {
    hexId: HexId;
    puzzleSlug: string;
  };
  solution: Solution | undefined;
  transform: LevelTransform;
  levelTitle: string;
  regionTitle: string;
  flavorText: string | string[];
  levelFlavorText: string | string[];
};

export type TileBank<
  VariantId extends string = never,
  AvailableTiles extends string = never,
  AvailableTileGroups extends string = never,
> = {
  // variant identifier (authoritative key for bank entry)
  tile: VariantId;
  count: number;
  tileGroup?: AvailableTileGroups;
  definition: TileVariantDefinition<AvailableTiles>;
}[];

type TileBankBuilder<
  AvailableTiles extends string = never,
  AvailableTileGroups extends string = never,
  CurrentTileBank extends string = never,
> = {
  // First argument is the variantId (unique key for the (tile, props) pairing)
  addTileToBank: <ProposedTile extends string>(
    tile: ProposedTile extends CurrentTileBank
      ? `${ProposedTile} is already in tile bank`
      : ProposedTile,
    count: number,
    definition: TileVariantDefinition<AvailableTiles>,
    tileGroup?: AvailableTileGroups,
  ) => TileBankBuilder<
    AvailableTiles,
    AvailableTileGroups,
    CurrentTileBank | ProposedTile
  >;
  build: () => TileBank<CurrentTileBank, AvailableTiles, AvailableTileGroups>;
};

export const createTileBankBuilder = <
  AvailableTiles extends string,
  AvailableTileGroups extends string = never,
  CurrentTileBank extends string = never,
>(
  state?: TileBank<CurrentTileBank, AvailableTiles, AvailableTileGroups>,
) => {
  const bank: {
    tile: CurrentTileBank;
    count: number;
    definition: TileVariantDefinition<AvailableTiles>;
    tileGroup?: AvailableTileGroups;
  }[] = state ?? [];
  return {
    addTileToBank: <ProposedTile extends string>(
      tile: ProposedTile extends CurrentTileBank
        ? `${ProposedTile} is already in tile bank`
        : ProposedTile,
      count: number,
      definition: TileVariantDefinition<AvailableTiles>,
      tileGroup?: AvailableTileGroups,
    ): TileBankBuilder<
      AvailableTiles,
      AvailableTileGroups,
      CurrentTileBank | ProposedTile
    > => {
      bank.push({
        tile: tile as unknown as CurrentTileBank,
        count,
        tileGroup,
        definition,
      });
      return createTileBankBuilder<
        AvailableTiles,
        AvailableTileGroups,
        CurrentTileBank | ProposedTile
      >(bank);
    },
    build: () => bank,
  };
};

type LevelBuilder<
  AvailableSlots extends string = never,
  AvailableTiles extends string = never,
  UsedHexIds extends HexId = never,
  CurrentTileBank extends string = never,
  AvailableIndicators extends string = never,
  AvailableTileGroups extends string = never,
> = {
  setFlavorText: (
    flavorText: string | string[],
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  setLevelFlavorText: (
    levelFlavorText: string | string[],
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  setTitle: (
    levelTitle: string,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addSlot: <ProposedSlot extends string, ProposedHexId extends HexId>(
    location: ProposedHexId extends UsedHexIds
      ? `Hex coordinate ${ProposedHexId} has already been used as a slot`
      : ProposedHexId,
    slot: ProposedSlot extends AvailableSlots
      ? ProposedSlot
      : `${ProposedSlot} is not a defined slot type`,
    slotProps?: Record<string, unknown>,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds | ProposedHexId,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addSubmission: (
    submission: Submission,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  // First argument is the variantId (unique key for the (tile, props) pairing)
  addTileToBank: <ProposedTile extends string>(
    tile: ProposedTile extends CurrentTileBank
      ? `${ProposedTile} is already in tile bank`
      : ProposedTile,
    count: number,
    definition: TileVariantDefinition<AvailableTiles>,
    tileGroup?: AvailableTileGroups,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank | ProposedTile,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addIndicator: <ProposedIndicator extends string, ProposedHexId extends HexId>(
    location: ProposedHexId extends UsedHexIds
      ? ProposedHexId
      : `Hex coordinate ${ProposedHexId} is not a slot (can only add indicators to hexes with slots)`,
    indicatorType: ProposedIndicator extends AvailableIndicators
      ? ProposedIndicator
      : `${ProposedIndicator} is not a defined indicator type`,
    indicatorProps?: Record<string, unknown>,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addGivenTile: <ProposedHexId extends HexId>(
    location: ProposedHexId extends UsedHexIds
      ? ProposedHexId
      : `Hex coordinate ${ProposedHexId} is not a slot (can only add given tiles to hexes with slots)`,
    definition: TileVariantDefinition<AvailableTiles>,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addClues: (
    location: UsedHexIds,
    clueArray: Clue[],
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  setSolution: (
    solution: Solution,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  addUnlockTransform: (
    transform: LevelTransform,
  ) => LevelBuilder<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    CurrentTileBank,
    AvailableIndicators,
    AvailableTileGroups
  >;
  build: () => Level<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    AvailableIndicators,
    AvailableTileGroups,
    CurrentTileBank
  >;
};

/** This will go to the client, be aware */
export const createLevelBuilder = <
  AvailableSlots extends string = never,
  AvailableTiles extends string = never,
  AvailableIndicators extends string = never,
  AvailableTileGroups extends string = never,
  UsedHexIds extends HexId = never,
  CurrentTileBank extends string = never,
>(
  state?: Level<
    AvailableSlots,
    AvailableTiles,
    UsedHexIds,
    AvailableIndicators,
    AvailableTileGroups,
    CurrentTileBank
  >,
): LevelBuilder<
  AvailableSlots,
  AvailableTiles,
  UsedHexIds,
  CurrentTileBank,
  AvailableIndicators,
  AvailableTileGroups
> => {
  const level: Record<
    HexId,
    { slot: AvailableSlots; slotProps: Record<string, unknown> }
  > = state?.level ?? {};
  const tileBank: TileBank<
    CurrentTileBank,
    AvailableTiles,
    AvailableTileGroups
  > =
    state?.tileBank ??
    ([] as TileBank<CurrentTileBank, AvailableTiles, AvailableTileGroups>);
  const givenTiles: Partial<
    Record<HexId, TileVariantDefinition<AvailableTiles>>
  > = state?.givenTiles ?? {};
  const clues: Record<HexId, Clue[]> = state?.clues ?? {};
  const indicators: Record<
    HexId,
    { type: AvailableIndicators; indicatorProps: Record<string, unknown> }[]
  > = state?.indicators ?? {};
  let solution: Solution | undefined = state?.solution;
  // Default transform is identity function (just returns input)
  const currentTransform: LevelTransform =
    state?.transform ?? ((level) => level);
  const submission: Submission | undefined = state?.submission;
  const levelTitle = state?.levelTitle ?? "";
  const regionTitle = state?.regionTitle ?? "";
  const flavorText: string | string[] = state?.flavorText ?? "";
  const levelFlavorText: string | string[] = state?.levelFlavorText ?? "";
  return {
    setTitle: (
      levelTitle: string,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    setFlavorText: (
      flavorText: string | string[],
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    setLevelFlavorText: (
      levelFlavorText: string | string[],
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    addSlot: <ProposedSlot extends string, ProposedHexId extends HexId>(
      location: ProposedHexId extends UsedHexIds
        ? `Hex coordinate ${ProposedHexId} has already been used as a slot`
        : ProposedHexId,
      slot: ProposedSlot extends AvailableSlots
        ? ProposedSlot
        : `${ProposedSlot} is not a defined slot type`,
      slotProps?: Record<string, unknown>,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds | ProposedHexId,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      level[location as HexId] = {
        slot: slot as AvailableSlots,
        slotProps: slotProps ?? {},
      };
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds | ProposedHexId,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    addSubmission: (
      submission: Submission,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    addTileToBank: <ProposedTile extends string>(
      tile: ProposedTile extends CurrentTileBank
        ? `${ProposedTile} is already in tile bank`
        : ProposedTile,
      count: number,
      definition: TileVariantDefinition<AvailableTiles>,
      tileGroup?: AvailableTileGroups,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank | ProposedTile,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      tileBank.push({
        // store the variantId in tile
        tile: tile as unknown as CurrentTileBank,
        count,
        tileGroup,
        definition: definition,
      });
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank | ProposedTile
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    addIndicator: <
      ProposedIndicator extends string,
      ProposedHexId extends HexId,
    >(
      location: ProposedHexId extends UsedHexIds
        ? ProposedHexId
        : `Hex coordinate ${ProposedHexId} is not a slot (can only add indicators to hexes with slots)`,
      indicatorType: ProposedIndicator extends AvailableIndicators
        ? ProposedIndicator
        : `${ProposedIndicator} is not a defined indicator type`,
      indicatorProps?: Record<string, unknown>,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      const hexId = location as HexId;
      if (!indicators[hexId]) {
        indicators[hexId] = [];
      }
      indicators[hexId].push({
        type: indicatorType as AvailableIndicators,
        indicatorProps: indicatorProps ?? {},
      });
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    addGivenTile: <ProposedHexId extends HexId>(
      location: ProposedHexId extends UsedHexIds
        ? ProposedHexId
        : `Hex coordinate ${ProposedHexId} is not a slot (can only add given tiles to hexes with slots)`,
      definition: TileVariantDefinition<AvailableTiles>,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      givenTiles[location as HexId] = definition;
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    addClues: (
      location: UsedHexIds,
      clueArray: Clue[],
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      clues[location as HexId] = clueArray;
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    setSolution: (
      newSolution: Solution,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      solution = newSolution;
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: currentTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    addUnlockTransform: (
      newTransform: LevelTransform,
    ): LevelBuilder<
      AvailableSlots,
      AvailableTiles,
      UsedHexIds,
      CurrentTileBank,
      AvailableIndicators,
      AvailableTileGroups
    > => {
      return createLevelBuilder<
        AvailableSlots,
        AvailableTiles,
        AvailableIndicators,
        AvailableTileGroups,
        UsedHexIds,
        CurrentTileBank
      >({
        level,
        tileBank,
        givenTiles,
        clues,
        indicators,
        solution,
        transform: newTransform,
        submission,
        levelTitle,
        regionTitle,
        flavorText,
        levelFlavorText,
      });
    },
    build: () => ({
      level: level as Record<
        UsedHexIds,
        { slot: AvailableSlots; slotProps: Record<string, unknown> }
      >,
      tileBank: tileBank,
      givenTiles: givenTiles as Partial<
        Record<UsedHexIds, TileVariantDefinition<AvailableTiles>>
      >,
      clues: clues as Record<UsedHexIds, Clue[]>,
      indicators: indicators as Record<
        UsedHexIds,
        {
          type: AvailableIndicators;
          indicatorProps: Record<string, unknown>;
        }[]
      >,
      solution: solution,
      transform: currentTransform,
      submission: submission,
      levelTitle,
      regionTitle,
      flavorText,
      levelFlavorText,
    }),
  };
};

// Map Builder for managing multiple levels with slot collision detection
export type LevelId = string;

// Helper type to extract UsedSlots from a Level type
type ExtractUsedSlots<T> =
  T extends Level<string, string, infer U, string, string, string> ? U : never;

type MapBuilder<
  LevelsMap extends Record<
    LevelId,
    Level<string, string, HexId, string, string, string>
  > = Record<never, never>,
  AllUsedSlots extends HexId = never,
> = {
  setTitle: (regionTitle: string) => MapBuilder<LevelsMap, AllUsedSlots>;
  addLevel: <
    Id extends LevelId,
    NewLevel extends Level<string, string, HexId, string, string, string>,
  >(
    id: Id extends keyof LevelsMap
      ? `Level ${Id} has already been defined`
      : Id,
    level: Disjoint<ExtractUsedSlots<NewLevel>, AllUsedSlots> extends true
      ? NewLevel
      : `Level ${Id} contains slots that collide with existing levels: ${Extract<ExtractUsedSlots<NewLevel>, AllUsedSlots>}`,
  ) => MapBuilder<
    LevelsMap & Record<Id, NewLevel>,
    AllUsedSlots | ExtractUsedSlots<NewLevel>
  >;
  build: () => LevelsMap;
};

export const createMapBuilder = <
  LevelsMap extends Record<
    LevelId,
    Level<string, string, HexId, string, string>
  > = Record<never, never>,
  AllUsedSlots extends HexId = never,
>(state?: {
  levels: LevelsMap;
  regionTitle: string;
}): MapBuilder<LevelsMap, AllUsedSlots> => {
  const humanizeLevelId = (id: string): string => {
    const words = id.split(/[-_]/).filter((word) => word.trim() !== "");
    if (words.length === 0) {
      return "Untitled Level";
    }
    return words
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" ");
  };

  const levels: Record<
    LevelId,
    Level<string, string, HexId, string, string, string>
  > = state?.levels || ({} as LevelsMap);
  const regionTitle = state?.regionTitle || "";

  return {
    setTitle(regionTitle: string) {
      return createMapBuilder<LevelsMap, AllUsedSlots>({
        levels: levels as LevelsMap,
        regionTitle,
      });
    },
    addLevel: <
      Id extends LevelId,
      NewLevel extends Level<string, string, HexId, string, string, string>,
    >(
      id: Id extends keyof LevelsMap
        ? `Level ${Id} has already been defined`
        : Id,
      level: Disjoint<ExtractUsedSlots<NewLevel>, AllUsedSlots> extends true
        ? NewLevel
        : `Level ${Id} contains slots that collide with existing levels: ${Extract<ExtractUsedSlots<NewLevel>, AllUsedSlots>}`,
    ): MapBuilder<
      LevelsMap & Record<Id, NewLevel>,
      AllUsedSlots | ExtractUsedSlots<NewLevel>
    > => {
      // TypeScript runtime safety: only add valid levels
      if (typeof level === "object" && level !== null && "level" in level) {
        const resolvedLevelTitle =
          "levelTitle" in level && typeof level.levelTitle === "string"
            ? level.levelTitle.trim()
            : "";
        const isSubmissionLevel =
          "submission" in level && level.submission !== undefined;
        levels[id] = {
          ...level,
          regionTitle,
          levelTitle:
            resolvedLevelTitle !== ""
              ? resolvedLevelTitle
              : isSubmissionLevel
                ? "Submission"
                : humanizeLevelId(id),
        } as Level<string, string, HexId, string, string, string>;
      }
      return createMapBuilder<
        LevelsMap & Record<Id, NewLevel>,
        AllUsedSlots | ExtractUsedSlots<NewLevel>
      >({ levels, regionTitle } as {
        levels: LevelsMap & Record<Id, NewLevel>;
        regionTitle: string;
      });
    },
    build: () => levels as LevelsMap,
  };
};
