// In clockwise order, starting from the 0 degrees which is east.
const axialNeighborDifferences = [
  [1, 0],
  [0, 1],
  [-1, 1],
  [-1, 0],
  [0, -1],
  [1, -1],
];

export function axialToXY(
  q: number,
  r: number,
  hexSize: number,
): [number, number] {
  const radius = hexSize / 2;
  const x = Math.sqrt(3) * radius * q + (Math.sqrt(3) / 2) * r * radius;
  const y = radius * 1.5 * r;
  return [x, y];
}

// Given an axial hex id and a direction index, return the x, y, coordinates of the
// left vertex along the edge in the direction.
function axialAndDIdxToXY(
  hex: HexId,
  dIdx: number,
  hexSize: number,
): [number, number] {
  const { q, r } = parseId(hex);
  const [x, y] = axialToXY(q, r, hexSize);
  const angle = (Math.PI / 3) * (dIdx - 0.5);

  return [
    x + (Math.cos(angle) * hexSize) / 2,
    y + (Math.sin(angle) * hexSize) / 2,
  ];
}

// Idea is find border hexes and then walk clockwise to add them.
// For shapes with holes we'll end up with multiple outlines.
export function createLevelOutline(
  level: HexId[],
  origin: HexId,
  hexSize: number,
): { svgString: string; offsetX: number; offsetY: number } {
  const { q: originQ, r: originR } = parseId(oddrToAxial(origin));
  const [originX, originY] = axialToXY(originQ, originR, hexSize);

  let outline = "";
  const levelHexes = new Set<HexId>();
  for (const hexId of level) {
    // Work in the axial coordinate system since dx, dy don't depend on parity.
    const { q, r } = parseId(oddrToAxial(hexId));
    levelHexes.add(createId(q, r));
  }

  const borderHexes = new Set<HexId>();
  const usedBorderHexes = new Set<HexId>();
  // console.log("level length", levelHexes.size);
  for (const hexId of levelHexes) {
    const { q, r } = parseId(hexId);
    const neighbors = axialNeighborDifferences.map((diffs) => ({
      q: q + diffs[0],
      r: r + diffs[1],
    }));
    const isBorder = neighbors.some((n) => !levelHexes.has(createId(n.q, n.r)));
    if (isBorder) {
      borderHexes.add(hexId);
    }
  }

  let combinedPolygon: Polygon = [];

  while (usedBorderHexes.size < borderHexes.size) {
    const outlinePolygon: Polygon = [];
    let startingHexId = null;
    let startingDIdx = 0;
    for (const hexId of borderHexes) {
      if (usedBorderHexes.has(hexId)) {
        continue;
      }
      startingHexId = hexId;
      break;
    }
    if (!startingHexId) {
      break;
    }

    const { q, r } = parseId(startingHexId as HexId);
    while (
      levelHexes.has(
        createId(
          q + axialNeighborDifferences[startingDIdx][0],
          r + axialNeighborDifferences[startingDIdx][1],
        ),
      )
    ) {
      startingDIdx = (startingDIdx + 1) % 6;
    }
    let currentHexId = startingHexId;
    let currentDIdx = startingDIdx;

    do {
      // const { q: q_, r: r_ } = parseId(currentHexId as HexId);
      // const { q: q__, r: r__ } = parseId(axialToOddr(q_, r_));
      // console.log(`${q__},${r__}`, currentDIdx);

      usedBorderHexes.add(currentHexId);
      const [x, y] = axialAndDIdxToXY(currentHexId, currentDIdx, hexSize);
      outlinePolygon.push({ x: x - originX, y: y - originY });

      currentDIdx = (currentDIdx + 1) % 6;
      const { q, r } = parseId(currentHexId as HexId);
      const nextHexId = createId(
        q + axialNeighborDifferences[currentDIdx][0],
        r + axialNeighborDifferences[currentDIdx][1],
      );
      if (levelHexes.has(nextHexId)) {
        currentDIdx = (currentDIdx + 3 + 1) % 6;
        currentHexId = nextHexId;
      }
    } while (currentHexId !== startingHexId || currentDIdx !== startingDIdx);
    // console.log("Finished", startingHexId, startingDIdx);
    // console.log("Length of used sets", usedBorderHexes.size, borderHexes.size);
    combinedPolygon = combinedPolygon.concat(outlinePolygon);

    outline += dynamicStroke(outlinePolygon, 1 / 25, 0.1) + " ";
  }

  if (combinedPolygon.length === 0) {
    return { svgString: "<svg/>", offsetX: 0, offsetY: 0 };
  }

  const padding = 100;
  const minX = Math.min(...combinedPolygon.map((p) => p.x)) - padding;
  const minY = Math.min(...combinedPolygon.map((p) => p.y)) - padding;
  const maxX = Math.max(...combinedPolygon.map((p) => p.x)) + padding;
  const maxY = Math.max(...combinedPolygon.map((p) => p.y)) + padding;

  const svgString = `
  <svg viewBox="${minX} ${minY} ${maxX - minX} ${maxY - minY}" width="${maxX - minX}" height="${maxY - minY}" xmlns="http://www.w3.org/2000/svg">
  <path d="${outline}" fill="none" stroke="black" opacity="1" stroke-width="8" stroke-dasharray="32 8" />
  </svg>
  `;
  const offsetX = minX;
  const offsetY = minY;
  return { svgString, offsetX, offsetY };
}

export function createLevelInnerLines(
  levels: Record<string, LevelDisplay>,
  hexSize: number,
): Map<string, LevelInnerLine> {
  const levelInnerLines = new Map<string, LevelInnerLine>();
  for (const [id, level] of Object.entries(levels)) {
    const origin = Object.keys(level.level)[0] as HexId;
    levelInnerLines.set(id, {
      origin,
      ...createLevelInnerLine(
        Object.keys(level.level) as HexId[],
        origin,
        hexSize,
      ),
    });
  }
  return levelInnerLines;
}

export function createLevelInnerLine(
  level: HexId[],
  origin: HexId,
  hexSize: number,
): { svgString: string; offsetX: number; offsetY: number } {
  const hexes = new Set<HexId>();
  for (const hexId of level) {
    hexes.add(oddrToAxial(hexId));
  }
  const { q: originQ, r: originR } = parseId(oddrToAxial(origin));
  const [originX, originY] = axialToXY(originQ, originR, hexSize);

  let d = "";
  const polygon: Polygon = [];
  hexes.forEach((hexId) => {
    const { q, r } = parseId(hexId);
    for (let dIdx = 0; dIdx < 6; dIdx++) {
      const [dq, dr] = axialNeighborDifferences[dIdx];
      const neighborHexId = createId(q + dq, r + dr);
      if (hexes.has(neighborHexId)) {
        const [x1, y1] = axialAndDIdxToXY(hexId, dIdx, hexSize);
        const [x2, y2] = axialAndDIdxToXY(hexId, dIdx + 1, hexSize);
        d += `M ${x1 - originX} ${y1 - originY} L ${x2 - originX} ${y2 - originY}`;
        polygon.push({ x: x1 - originX, y: y1 - originY });
        polygon.push({ x: x2 - originX, y: y2 - originY });
      }
    }
  });

  if (polygon.length === 0) {
    return { svgString: "<svg/>", offsetX: 0, offsetY: 0 };
  }

  const padding = 100;
  const minX = Math.min(...polygon.map((p) => p.x)) - padding;
  const minY = Math.min(...polygon.map((p) => p.y)) - padding;
  const maxX = Math.max(...polygon.map((p) => p.x)) + padding;
  const maxY = Math.max(...polygon.map((p) => p.y)) + padding;

  const svgString = `
  <svg viewBox="${minX} ${minY} ${maxX - minX} ${maxY - minY}" width="${maxX - minX}" height="${maxY - minY}" xmlns="http://www.w3.org/2000/svg">
  <path d="${d}" fill="none" stroke="black" opacity="0.5" stroke-width="1" />
  </svg>
  `;
  const offsetX = minX;
  const offsetY = minY;
  return { svgString, offsetX, offsetY };
}
