type WorthwhileSuitChevronIndicatorProps = {
  upper?: "ur" | "r" | "dr" | "dl" | "l" | "ul";
  lower?: "ur" | "r" | "dr" | "dl" | "l" | "ul";
};

function WorthwhileSuitChevronIndicator(
  props: WorthwhileSuitChevronIndicatorProps,
) {
  return (
    <div
      className={cn("h-full w-full", {
        "indicator chevron": props.upper,
        "rot-1": props.upper === "dr",
        "rot-2": props.upper === "dl",
        "rot-3": props.upper === "l",
        "rot-4": props.upper === "ul",
        "rot-5": props.upper === "ur",
        "rot-6": props.upper === "r",
        "indicator lower-chevron": props.lower,
        "lower-rot-1": props.lower === "dr",
        "lower-rot-2": props.lower === "dl",
        "lower-rot-3": props.lower === "l",
        "lower-rot-4": props.lower === "ul",
        "lower-rot-5": props.lower === "ur",
        "lower-rot-6": props.lower === "r",
      })}
    />
  );
}

// A plus will appear near the top of the tile; a minus will appear near the bottom.
export const WorthwhileSuitPlusMinusIndicator = (
  props: Record<string, unknown>,
) => (
  <div className="w-full h-full flex flex-row items-center justify-center">
    <span
      className={cn(
        "text-black text-[36px]",
        props.character === "+" ? "pb-12" : "pt-12",
      )}
    >
      {props.character as string}
    </span>
  </div>
);

export const WorthwhileSuitAsteriskIndicator = () => (
  <div className="w-full h-full flex flex-row items-center justify-center">
    <span className="text-red-500 text-[72px] pt-6">*</span>
  </div>
);

type WorthwhileSuitLongTextTileProps = {
  text: string;
};

// Up to 3 characters doesn't overflow, but if we have more then font size needs to decrease.
export const WorthwhileSuitLongTextTile = (
  props: WorthwhileSuitLongTextTileProps,
) => (
  <div
    className="h-full w-full relative"
    style={{ backgroundColor: "#ffffff80" }}
  >
    <div className="absolute inset-0 z-10 flex items-center justify-center flex-col">
      <span
        className="text-center text-black"
        style={{
          fontSize:
            Math.floor(108 / Math.max(3, props.text.length)).toString() + "px",
        }}
      >
        {props.text}
      </span>
    </div>
  </div>
);

export const Border = ({ border }: { border: number }) => {
  const borders = [
    (border & 1) !== 0,
    (border & 2) !== 0,
    (border & 4) !== 0,
    (border & 8) !== 0,
    (border & 16) !== 0,
    (border & 32) !== 0,
  ];
  const width = 107.38715;
  const height = 124;
  const scale = height / 2;
  const borderThickness = 10;
  return (
    <svg
      className="absolute left-0 top-0"
      width="100%"
      height="100%"
      viewBox={`0 0 ${width} ${height}`}
    >
      {borders.map((border, i) => {
        if (!border) {
          return null;
        }
        const startAngle = (i * Math.PI) / 3 + Math.PI / 2;
        const endAngle = ((i + 1) * Math.PI) / 3 + Math.PI / 2;
        const sx = Math.cos(startAngle) * scale + width / 2;
        const sy = Math.sin(startAngle) * scale + height / 2;
        const ex = Math.cos(endAngle) * scale + width / 2;
        const ey = Math.sin(endAngle) * scale + height / 2;
        return (
          <path
            d={`M${sx} ${sy} L${ex} ${ey}`}
            stroke="black"
            strokeWidth={borderThickness}
            key={i}
          />
        );
      })}
    </svg>
  );
};

export const WorthwhileSuitBorderIndicator = (
  props: Record<string, unknown>,
) => {
  const border = { left: 2, right: 16 }[props.side as "left" | "right"];
  return (
    <div className="w-full h-full flex flex-row items-center justify-center">
      <span className="text-black text-sm pb-12">
        {border > 0 ? <Border border={border} /> : null}
      </span>
    </div>
  );
};

type WorthwhileSuitBTileProps = {
  topLeft?: string;
  topRight?: string;
  right?: string;
  bottomRight?: string;
  bottomLeft?: string;
  left?: string;
};

const R = 60;
const W = Math.sqrt(3) * R;
const H = 2 * R;
const I = 10;

function pctWidth(x: number): string {
  return `${Math.round((x / W) * 100)}%`;
}
function pctHeight(y: number): string {
  return `${Math.round((y / H) * 100)}%`;
}

type WorthwhileSuitATileProps = {
  image: string | undefined;
  backgroundColor: string | undefined;
  text: string | undefined;
};

export function WorthwhileSuitATile(props: WorthwhileSuitATileProps) {
  const backgroundColor = props.backgroundColor ?? "rgba(133,216,229,0.75)";
  return (
    <div
      className="h-full w-full relative"
      style={{ backgroundColor: backgroundColor }}
    >
      {props.image && (
        <img
          className="h-full w-full object-contain"
          src={props.image}
          alt={"A tile"}
          draggable={"false"}
        />
      )}
      {props.text && (
        <div className="absolute inset-0 z-10 flex items-center justify-center flex-col">
          <span className="text-center text-[36px] font-semibold text-black">
            {props.text}
          </span>
        </div>
      )}
    </div>
  );
}

function WorthwhileSuitBTileInner(props: WorthwhileSuitBTileProps) {
  const renderLabel = (
    text: string | undefined,
    style: React.CSSProperties,
  ) => {
    if (!text) return null;
    return (
      <div
        className="absolute flex items-center justify-center flex-col"
        style={style}
      >
        <span className="text-center text-[10px] font-semibold">{text}</span>
      </div>
    );
  };

  return (
    <div
      className="bg-white text-black relative"
      style={{ width: `${W}px`, height: `${H}px` }}
    >
      {renderLabel(props.bottomLeft, {
        width: pctWidth(0.8 * R),
        height: pctHeight(0.8 * R),
        left: pctWidth(W / 4 - (0.8 * R) / 2 + I / 2),
        top: pctHeight((7 / 8) * H - (0.8 * R) / 2 - (I * Math.sqrt(3)) / 2),
        transform: "rotate(30deg)",
      })}
      {renderLabel(props.left, {
        width: pctWidth(0.8 * R),
        height: pctHeight(0.8 * R),
        left: pctWidth(-(0.8 * R) / 2 + I),
        top: pctHeight(H / 2 - (0.8 * R) / 2),
        transform: "rotate(90deg)",
      })}
      {renderLabel(props.topLeft, {
        width: pctWidth(0.8 * R),
        height: pctHeight(0.8 * R),
        left: pctWidth(W / 4 - (0.8 * R) / 2 + I / 2),
        top: pctHeight((1 / 8) * H - (0.8 * R) / 2 + (I * Math.sqrt(3)) / 2),
        transform: "rotate(150deg)",
      })}
      {renderLabel(props.topRight, {
        width: pctWidth(0.8 * R),
        height: pctHeight(0.8 * R),
        left: pctWidth((3 * W) / 4 - (0.8 * R) / 2 - I / 2),
        top: pctHeight((1 / 8) * H - (0.8 * R) / 2 + (I * Math.sqrt(3)) / 2),
        transform: "rotate(210deg)",
      })}
      {renderLabel(props.right, {
        width: pctWidth(0.8 * R),
        height: pctHeight(0.8 * R),
        left: pctWidth(W - (0.8 * R) / 2 - I),
        top: pctHeight(H / 2 - (0.8 * R) / 2),
        transform: "rotate(270deg)",
      })}
      {renderLabel(props.bottomRight, {
        width: pctWidth(0.8 * R),
        height: pctHeight(0.8 * R),
        left: pctWidth((3 * W) / 4 - (0.8 * R) / 2 - I / 2),
        top: pctHeight((7 / 8) * H - (0.8 * R) / 2 - (I * Math.sqrt(3)) / 2),
        transform: "rotate(330deg)",
      })}
    </div>
  );
}

export function WorthwhileSuitBTile(props: WorthwhileSuitBTileProps) {
  const desiredWidth = 2 * W;
  const desiredHeight = 2 * H;
  const scale = desiredWidth / W;

  const scaledTooltip = (
    <div
      style={{
        position: "relative",
        width: `${desiredWidth}px`,
        height: `${desiredHeight}px`,
      }}
    >
      <div
        style={{
          width: `${desiredWidth}px`,
          height: `${desiredHeight}px`,
          visibility: "hidden",
        }}
      />
      <div
        className="hexagon"
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: `${W}px`,
          height: `${H}px`,
          transform: `scale(${scale})`,
          transformOrigin: "top left",
        }}
      >
        <WorthwhileSuitBTileInner {...props} />
      </div>
    </div>
  );

  return (
    <ConditionalTooltip tooltip={scaledTooltip}>
      <div className="h-full w-full relative">
        <WorthwhileSuitBTileInner {...props} />
      </div>
    </ConditionalTooltip>
  );
}

type WorthwhileSuitKTileProps = {
  letter: string;
};

export function WorthwhileSuitKTile(props: WorthwhileSuitKTileProps) {
  // Hexagon vertices (pointy-top hexagon)
  const hexPoints = [
    [50, 0], // top
    [99.5, 28.8675], // top right
    [99.5, 86.6025], // bottom right
    [50, 115.4701], // bottom
    [0, 86.6025], // bottom left
    [0, 28.8675], // top left
  ];

  return (
    <div className="h-full w-full relative">
      <svg
        className="absolute inset-0 block h-full w-full"
        viewBox="0 0 100 115.4701"
        preserveAspectRatio="xMidYMid meet"
        aria-hidden="true"
      >
        {/* Draw 6 line segments to form hexagon border */}
        {hexPoints.map((point, index) => {
          const nextIndex = (index + 1) % hexPoints.length;
          const nextPoint = hexPoints[nextIndex];
          return (
            <line
              key={index}
              x1={point[0]}
              y1={point[1]}
              x2={nextPoint[0]}
              y2={nextPoint[1]}
              stroke="#000000"
              strokeWidth={4}
            />
          );
        })}
      </svg>
      <span
        className="absolute inset-0 flex items-center justify-center text-3xl font-bold text-black"
        style={{
          textShadow: "0 0 8px #fff, 0 0 16px #fff, 0 0 24px #fff",
        }}
      >
        {props.letter}
      </span>
    </div>
  );
}

export const worthwhileSuitRegion = createRegionBuilder()
  .addSlotType("worthwhile-suit-empty-slot", (slotProps) => {
    const className = slotProps.className as string | undefined;
    return (
      <SimpleSlot
        className={className}
        style={slotProps.style as React.CSSProperties}
      />
    );
  })
  .addIndicatorType(
    "worthwhile-suit-chevron-indicator",
    WorthwhileSuitChevronIndicator as React.FC<Record<string, unknown>>,
  )
  .addIndicatorType(
    "worthwhile-suit-plus-minus-indicator",
    WorthwhileSuitPlusMinusIndicator as React.FC<Record<string, unknown>>,
  )
  .addIndicatorType(
    "worthwhile-suit-border-indicator",
    WorthwhileSuitBorderIndicator as React.FC<Record<string, unknown>>,
  )
  .addIndicatorType(
    "worthwhile-suit-asterisk-indicator",
    WorthwhileSuitAsteriskIndicator as React.FC<Record<string, unknown>>,
  )
  .addTileGroup("worthwhile-suit-E-image-group", "Image Tiles")
  .addTileGroup("worthwhile-suit-F-emoji-group", "Emoji Tiles")
  .addTileGroup("worthwhile-suit-F-letter-group", "Letter Tiles")
  .addTileGroup("worthwhile-suit-H-image-group", "Image Tiles")
  .addTileGroup("worthwhile-suit-J-image-group", "Image Tiles")
  .addTileGroup("worthwhile-suit-K-letter-group", "Letter Tiles")
  .addTileGroup("worthwhile-suit-L-image-group", "Image Tiles")
  .build();

export type worthwhileSuitAvailableSlots =
  keyof typeof worthwhileSuitRegion.slots;
export type worthwhileSuitAvailableTiles =
  keyof typeof worthwhileSuitRegion.tiles;
export type worthwhileSuitAvailableIndicators =
  keyof typeof worthwhileSuitRegion.indicators;
export type worthwhileSuitAvailableTileGroups =
  keyof typeof worthwhileSuitRegion.tileGroups;
