// Stuff in this file will pretty likely be sent to the client, be aware
import { ConditionalTooltip } from "@hunt/shadcn";
import { TileTwemojify } from "../../../levels/component-utilities";
import { createRegionBuilder } from "../../../levels/types";

type SnoopyShoeTileProps = {
  center: string;
  topLeft: string;
  topRight: string;
  right: string;
  bottomRight: string;
  bottomLeft: string;
  left: string;
};

const R = 60;
const W = Math.sqrt(3) * R;
const H = 2 * R;
const I = 10;
function pctWidth(x: number): string {
  return `${Math.round((x / W) * 100)}%`;
}
function pctHeight(y: number): string {
  return `${Math.round((y / H) * 100)}%`;
}

function SnoopyShoeTileInner(props: SnoopyShoeTileProps) {
  return (
    <div
      className="bg-white text-black"
      style={{ width: `${W}px`, height: `${H}px` }}
    >
      <div
        className="absolute flex items-center justify-center flex-col"
        style={{
          width: pctWidth(R),
          height: pctWidth(R),
          left: pctWidth(W / 2 - R / 2),
          top: pctHeight(H / 2 - R / 2),
        }}
      >
        <span className="text-center font-bold" style={{ fontSize: "10px" }}>
          {props.center}
        </span>
      </div>
      <div
        className="absolute flex items-center justify-center flex-col"
        style={{
          width: pctWidth(0.8 * R),
          height: pctHeight(0.8 * R),
          left: pctWidth(W / 4 - (0.8 * R) / 2 + I / 2),
          top: pctHeight((7 / 8) * H - (0.8 * R) / 2 - (I * Math.sqrt(3)) / 2),
          transform: "rotate(30deg)",
        }}
      >
        <span className="text-center" style={{ fontSize: "5px" }}>
          {TileTwemojify(props.bottomLeft, "inline-block h-2 w-2")}
        </span>
      </div>
      <div
        className="absolute flex items-center justify-center flex-col"
        style={{
          width: pctWidth(0.8 * R),
          height: pctHeight(0.8 * R),
          left: pctWidth(-(0.8 * R) / 2 + I),
          top: pctHeight(H / 2 - (0.8 * R) / 2),
          transform: "rotate(90deg)",
        }}
      >
        <span className="text-center" style={{ fontSize: "5px" }}>
          {TileTwemojify(props.left, "inline-block h-2 w-2")}
        </span>
      </div>
      <div
        className="absolute flex items-center justify-center flex-col"
        style={{
          width: pctWidth(0.8 * R),
          height: pctHeight(0.8 * R),
          left: pctWidth(W / 4 - (0.8 * R) / 2 + I / 2),
          top: pctHeight((1 / 8) * H - (0.8 * R) / 2 + (I * Math.sqrt(3)) / 2),
          transform: "rotate(150deg)",
        }}
      >
        <span className="text-center" style={{ fontSize: "5px" }}>
          {TileTwemojify(props.topLeft, "inline-block h-2 w-2")}
        </span>
      </div>
      <div
        className="absolute flex items-center justify-center flex-col"
        style={{
          width: pctWidth(0.8 * R),
          height: pctHeight(0.8 * R),
          left: pctWidth((3 * W) / 4 - (0.8 * R) / 2 - I / 2),
          top: pctHeight((1 / 8) * H - (0.8 * R) / 2 + (I * Math.sqrt(3)) / 2),
          transform: "rotate(210deg)",
        }}
      >
        <span className="text-center" style={{ fontSize: "5px" }}>
          {TileTwemojify(props.topRight, "inline-block h-2 w-2")}
        </span>
      </div>
      <div
        className="absolute flex items-center justify-center flex-col"
        style={{
          width: pctWidth(0.8 * R),
          height: pctHeight(0.8 * R),
          left: pctWidth(W - (0.8 * R) / 2 - I),
          top: pctHeight(H / 2 - (0.8 * R) / 2),
          transform: "rotate(270deg)",
        }}
      >
        <span className="text-center" style={{ fontSize: "5px" }}>
          {TileTwemojify(props.right, "inline-block h-2 w-2")}
        </span>
      </div>
      <div
        className="absolute flex items-center justify-center flex-col"
        style={{
          width: pctWidth(0.8 * R),
          height: pctHeight(0.8 * R),
          left: pctWidth((3 * W) / 4 - (0.8 * R) / 2 - I / 2),
          top: pctHeight((7 / 8) * H - (0.8 * R) / 2 - (I * Math.sqrt(3)) / 2),
          transform: "rotate(330deg)",
        }}
      >
        <span className="text-center" style={{ fontSize: "5px" }}>
          {TileTwemojify(props.bottomRight, "inline-block h-2 w-2")}
        </span>
      </div>
    </div>
  );
}

export function SnoopyShoeTile(props: SnoopyShoeTileProps) {
  const baseSize = W; // Using width as the base size dimension
  const desiredSize = 2 * baseSize;
  const scale = desiredSize / baseSize;
  const desiredWidth = 2 * W;
  const desiredHeight = 2 * H;

  const scaledTooltip = (
    <div
      style={{
        position: "relative",
        width: `${desiredWidth}px`,
        height: `${desiredHeight}px`,
      }}
    >
      {/* Sizing proxy - invisible but takes up space for layout */}
      <div
        style={{
          width: `${desiredWidth}px`,
          height: `${desiredHeight}px`,
          visibility: "hidden",
        }}
      />
      {/* Scaled tile - rendered at base size, scaled to desired size */}
      <div
        className="hexagon"
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: `${W}px`,
          height: `${H}px`,
          transform: `scale(${scale})`,
          transformOrigin: "top left",
        }}
      >
        <SnoopyShoeTileInner {...props} />
      </div>
    </div>
  );

  return (
    <ConditionalTooltip tooltip={scaledTooltip}>
      <div className="h-full w-full relative">
        <SnoopyShoeTileInner {...props} />
      </div>
    </ConditionalTooltip>
  );
}

export const snoopyShoeRegion = createRegionBuilder()
  .addSlotType("empty-slot-snoopy-shoe", null)
  .addTileType("snoopy-shoe-tile", (props: Record<string, unknown>) => {
    const center = props.center as string; // has type unknown
    const left = props.left as string; // has type unknown
    const right = props.right as string; // has type unknown
    const topLeft = props.topLeft as string; // has type unknown
    const topRight = props.topRight as string; // has type unknown
    const bottomLeft = props.bottomLeft as string; // has type unknown
    const bottomRight = props.bottomRight as string; // has type unknown
    return (
      <SnoopyShoeTile
        center={center}
        left={left}
        right={right}
        topLeft={topLeft}
        topRight={topRight}
        bottomLeft={bottomLeft}
        bottomRight={bottomRight}
      />
    );
  })
  .build();

export type SnoopyShoeAvailableSlots = keyof typeof snoopyShoeRegion.slots;
export type SnoopyShoeAvailableTiles = keyof typeof snoopyShoeRegion.tiles;
