import { SimpleSlot } from "../../../levels/component-utilities";
import { createRegionBuilder } from "../../../levels/types";

export const metaRegion = createRegionBuilder()
  .addSlotType("empty-slot-meta-1", () => <SimpleSlot className="bg-white" />)
  .build();

export type MetaAvailableSlots = keyof typeof metaRegion.slots;
export type MetaAvailableTiles = keyof typeof metaRegion.tiles;
export type MetaAvailableIndicators = keyof typeof metaRegion.indicators;
export type MetaAvailableTileGroups = keyof typeof metaRegion.tileGroups;
