import { createLevelBuilder } from "../../../levels/types";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import {
  ROOM1_TILE_COUNT,
  type MysteryAvailableSlots,
  type MysteryAvailableTileGroups,
} from "./client";

export const ROOM1_LEVEL_ID = "mystery-room-1-level";

const mysteryRoom1Tiles = Array.from(
  { length: ROOM1_TILE_COUNT },
  (_, idx) => `mystery-room-1-${idx}-tile` as AllAvailableTiles,
);

const mysteryRoom1LevelBuilder = createLevelBuilder<
  MysteryAvailableSlots,
  AllAvailableTiles,
  never,
  MysteryAvailableTileGroups
>()
  .setTitle("Dining & Living Room")
  .addSlot("22,-12", "mystery-empty-slot")
  .addSlot("23,-12", "mystery-empty-slot")
  .addSlot("24,-12", "mystery-empty-slot")
  .addSlot("25,-12", "mystery-empty-slot")
  .addSlot("26,-12", "mystery-empty-slot")
  .addSlot("21,-11", "mystery-empty-slot")
  .addSlot("22,-11", "mystery-empty-slot")
  .addSlot("23,-11", "mystery-empty-slot")
  .addSlot("24,-11", "mystery-empty-slot")
  .addSlot("25,-11", "mystery-empty-slot")
  .addSlot("26,-11", "mystery-empty-slot")
  .addClues("25,-12", [
    {
      type: "text",
      text: "A large present",
    },
  ])
  .addClues("23,-11", [
    {
      type: "text",
      text: "Where the body was found",
    },
  ])
  .addClues("24,-11", [
    {
      type: "text",
      text: "Where the body was found",
    },
  ]);

mysteryRoom1Tiles.forEach((t) => {
  mysteryRoom1LevelBuilder.addTileToBank(
    t,
    1,
    { renderer: t, props: {} },
    "mystery-room-1",
  );
});

const ROOM_1_SOLUTION: Record<string, string> = {
  "22,-12": "mystery-room-1-5-tile",
  "23,-12": "mystery-room-1-9-tile",
  "24,-12": "mystery-room-1-1-tile",
  "25,-12": "mystery-room-1-4-tile",
  "26,-12": "mystery-room-1-10-tile",
  "21,-11": "mystery-room-1-2-tile",
  "22,-11": "mystery-room-1-7-tile",
  "23,-11": "mystery-room-1-8-tile",
  "24,-11": "mystery-room-1-6-tile",
  "25,-11": "mystery-room-1-3-tile",
  "26,-11": "mystery-room-1-0-tile",
};

mysteryRoom1LevelBuilder.setSolution(ROOM_1_SOLUTION);

export const mysteryRoom1Level = mysteryRoom1LevelBuilder.build();
