export type Polygon = { x: number; y: number }[];

// Based on the cosine trick in shaders.
function random(p: number): number {
  return (
    Math.abs(
      Math.cos(p * (23.14069263277926 + 2.665144142690225)) * 12345.6789,
    ) % 1
  );
}

// Takes a polygon as input and returns an SVG path's d attribute for a dynamically stroked path.
export function dynamicStroke(
  polygon: Polygon,
  frequency: number,
  wiggle: number,
  randomSeed = 0,
): string {
  let d = `M ${polygon[0].x} ${polygon[0].y} `;
  let idx = 0;

  for (let i = 0; i < polygon.length; i++) {
    const { x: x1, y: y1 } = polygon[i];
    const { x: x2, y: y2 } = polygon[(i + 1) % polygon.length];
    const length = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
    const subdivisions = [[x1, y1]];
    for (let f = 1; f < frequency * length + 1; f++) {
      const t =
        f / (frequency * length + 1) +
        ((random(idx + f + randomSeed) - 0.5) * 0.5) / (frequency * length + 1);
      const x = t * x2 + (1 - t) * x1;
      const y = t * y2 + (1 - t) * y1;
      subdivisions.push([x, y]);
    }
    subdivisions.push([x2, y2]);
    for (let j = 0; j < subdivisions.length - 1; j++) {
      const x1 = subdivisions[j][0];
      const y1 = subdivisions[j][1];
      const x2 = subdivisions[j + 1][0];
      const y2 = subdivisions[j + 1][1];

      const dx = x2 - x1;
      const dy = y2 - y1;

      const sign = idx % 2 === 0 ? 1 : -1;
      const wiggleAmount = random(idx + randomSeed) * wiggle;
      const bx1 = x1 + 0.25 * dx + wiggleAmount * dy * sign;
      const by1 = y1 + 0.25 * dy - wiggleAmount * dx * sign;
      const bx2 = x2 - 0.25 * dx + wiggleAmount * dy * sign;
      const by2 = y2 - 0.25 * dy - wiggleAmount * dx * sign;

      if (idx === 0) {
        d += `C ${bx1} ${by1}, ${bx2} ${by2}, ${x2} ${y2} `;
      } else {
        d += `S ${bx2} ${by2}, ${x2} ${y2} `;
      }
      idx++;
    }
  }
  return d;
}
