export const SlitherlinkTile = ({ borderType }: { borderType: number }) => {
  return (
    <div
      style={{ width: "100%", height: "100%", backgroundColor: "#ffffffa0" }}
    >
      <img
        src={borders[borderType]}
        alt="slitherlink borders"
        draggable="false"
      />
    </div>
  );
};

type IndicatorContent = {
  content?: string;
};

function Indicator(props: IndicatorContent) {
  return (
    <CenteredContent className="text-3xl font-bold text-black">
      {props.content}
    </CenteredContent>
  );
}

export const slitherlinkRegion = createRegionBuilder()
  .addSlotType("empty-slot-bowed-key", null)
  .addTileGroup("slitherlink0", "0 Borders")
  .addTileGroup("slitherlink1", "1 Borders")
  .addTileGroup("slitherlink2", "2 Borders")
  .addTileGroup("slitherlink3", "3 Borders")
  .addTileGroup("slitherlink4", "4 Borders")
  .addTileGroup("slitherlink5", "5 Borders")
  .addIndicatorType(
    "slitherlink-indicator",
    Indicator as React.FC<Record<string, unknown>>,
  )
  .build();

export type SlitherlinkAvailableSlots = keyof typeof slitherlinkRegion.slots;
export type SlitherlinkAvailableTiles = keyof typeof slitherlinkRegion.tiles;
export type SlitherlinkAvailableIndicators =
  keyof typeof slitherlinkRegion.indicators;
export type SlitherlinkAvailableTileGroups =
  keyof typeof slitherlinkRegion.tileGroups;
