import { useMemo } from "react";
import { parseId, type HexId } from "../basic-hexagons/bounding-box";
import levelSolutions from "../levels/__generated__/level-solutions.json";
import {
  allRegionAvailableSlots,
  type AllLevelsAvailableSlots,
  allRegionAvailableIndicators,
  AnyIndicatorContentRenderer,
  type AllLevelsAvailableIndicators,
} from "./all-levels-client";
import { tileRegistry } from "./regions/all-regions-tile-renderer-registry";

// Export type for solution data structure
export type LevelSolution = Record<
  string,
  { renderer: string; props: Record<string, unknown> }
>;

export type LevelSlots = Record<
  string,
  { slot: string; slotProps: Record<string, unknown> }
>;

export type LevelIndicators = Record<
  string,
  { type: string; indicatorProps: Record<string, unknown> }[]
>;

export type LevelSolutionData = {
  solution?: LevelSolution;
  slots: LevelSlots;
  indicators?: LevelIndicators;
};

// Export the solutions data for programmatic access
export const levelSolutionsData = levelSolutions as Record<
  string,
  LevelSolutionData | undefined
>;

// Export a helper function to get solution for a specific level
export function getLevelSolution(levelId: string): LevelSolution | undefined {
  return levelSolutionsData[levelId]?.solution;
}

type SolutionDisplayProps = {
  levelIds: string[];
  hexSize?: number;
  gap?: number;
  className?: string;
  showSlots?: boolean;
};

export function SolutionDisplay({
  levelIds,
  hexSize = 40,
  gap = 2,
  className,
  showSlots = true,
}: SolutionDisplayProps) {
  const { hexes, solutionHexes, slotHexes, indicatorHexes, bounds } =
    useMemo(() => {
      if (levelIds.length === 0) {
        return {
          hexes: [],
          solutionHexes: [],
          slotHexes: [],
          indicatorHexes: [],
          bounds: { minQ: 0, maxQ: 0, minR: 0, maxR: 0 },
        };
      }

      // Collect all hexes from all specified levels (from solutions, slots, and indicators)
      const solutionHexCoordinates: {
        hexId: string;
        q: number;
        r: number;
        levelId: string;
      }[] = [];
      const slotHexCoordinates: {
        hexId: string;
        q: number;
        r: number;
        levelId: string;
      }[] = [];
      const indicatorHexCoordinates: {
        hexId: string;
        q: number;
        r: number;
        levelId: string;
        indicatorIndex: number;
        indicatorType: string;
        indicatorProps: Record<string, unknown>;
      }[] = [];
      const allCoordinatesSet = new Set<string>(); // For bounds calculation: "q,r"

      for (const id of levelIds) {
        const levelData = levelSolutionsData[id];
        if (!levelData) continue;

        // Collect solution hexes
        if (levelData.solution) {
          for (const hexId of Object.keys(levelData.solution)) {
            const coords = parseId(hexId as HexId);
            solutionHexCoordinates.push({ hexId, ...coords, levelId: id });
            allCoordinatesSet.add(`${coords.q},${coords.r}`);
          }
        }

        // Collect slot hexes (independent of solution hexes - a hex can have both)
        if (showSlots && levelData.slots) {
          for (const hexId of Object.keys(levelData.slots)) {
            const coords = parseId(hexId as HexId);
            slotHexCoordinates.push({ hexId, ...coords, levelId: id });
            allCoordinatesSet.add(`${coords.q},${coords.r}`);
          }
        }

        // Collect indicator hexes
        if (
          levelData.indicators &&
          Object.keys(levelData.indicators).length > 0
        ) {
          for (const [hexId, indicatorArray] of Object.entries(
            levelData.indicators,
          )) {
            const coords = parseId(hexId as HexId);
            allCoordinatesSet.add(`${coords.q},${coords.r}`);
            // Each hex can have multiple indicators
            indicatorArray.forEach((indicator, index) => {
              indicatorHexCoordinates.push({
                hexId,
                ...coords,
                levelId: id,
                indicatorIndex: index,
                indicatorType: indicator.type,
                indicatorProps: indicator.indicatorProps,
              });
            });
          }
        }
      }

      // Calculate bounds from all unique coordinates
      const allHexCoordinates = Array.from(allCoordinatesSet).map(
        (coordStr) => {
          const [q, r] = coordStr.split(",").map(Number);
          return { q, r };
        },
      );

      if (allHexCoordinates.length === 0) {
        return {
          hexes: [],
          solutionHexes: [],
          slotHexes: [],
          indicatorHexes: [],
          bounds: { minQ: 0, maxQ: 0, minR: 0, maxR: 0 },
        };
      }

      const minQ = Math.min(...allHexCoordinates.map((h) => h.q));
      const maxQ = Math.max(...allHexCoordinates.map((h) => h.q));
      const minR = Math.min(...allHexCoordinates.map((h) => h.r));
      const maxR = Math.max(...allHexCoordinates.map((h) => h.r));

      return {
        hexes: allHexCoordinates,
        solutionHexes: solutionHexCoordinates,
        slotHexes: slotHexCoordinates,
        indicatorHexes: indicatorHexCoordinates,
        bounds: {
          minQ,
          maxQ,
          minR,
          maxR,
        },
      };
    }, [levelIds, showSlots]);

  if (hexes.length === 0) {
    return null;
  }

  return (
    <div className={className}>
      <div
        className="offset-grid relative"
        style={
          {
            "--min-q": bounds.minQ,
            "--max-q": bounds.maxQ,
            "--min-r": bounds.minR,
            "--max-r": bounds.maxR,
            "--hex-size": `${hexSize}px`,
            "--gap": `${gap}px`,
          } as React.CSSProperties
        }
      >
        {/* Slot layer (background) */}
        {showSlots &&
          slotHexes.map(({ hexId, q, r, levelId: hexLevelId }) => {
            const levelData = levelSolutionsData[hexLevelId];
            if (!levelData?.slots) return null;

            const slotData = levelData.slots[hexId];
            if (!slotData) return null;

            const slotType = slotData.slot as AllLevelsAvailableSlots;
            const slotDef = allRegionAvailableSlots[slotType];
            if (!slotDef) return null;

            const SlotRenderer = slotDef.renderer;
            // Slots with null renderers are "empty slots" - they don't render content
            // but we still want to render the hexagon container for layout purposes
            // In solution displays, we'll skip rendering empty slots entirely

            return (
              <div
                key={`slot-${hexLevelId}-${hexId}`}
                className="hexagon placed-hex"
                style={
                  {
                    "--q": q,
                    "--r": r,
                    "--parity": Math.abs(r + 1) % 2,
                    backgroundColor: "#00000040",
                  } as React.CSSProperties
                }
              >
                {SlotRenderer ? <SlotRenderer {...slotData.slotProps} /> : null}
              </div>
            );
          })}
        {/* Solution tile layer (foreground) */}
        {solutionHexes.map(({ hexId, q, r, levelId: hexLevelId }) => {
          const levelData = levelSolutionsData[hexLevelId];
          if (!levelData?.solution) return null;

          const tileData = levelData.solution[hexId];
          if (!tileData) return null;

          const rendererName = tileData.renderer;
          const Renderer =
            typeof rendererName === "string" && rendererName in tileRegistry
              ? tileRegistry[rendererName as keyof typeof tileRegistry]
              : null;
          if (!Renderer) return null;

          return (
            <div
              key={`solution-${hexLevelId}-${hexId}`}
              className="hexagon placed-hex"
              style={
                {
                  "--q": q,
                  "--r": r,
                  "--parity": Math.abs(r + 1) % 2,
                } as React.CSSProperties
              }
            >
              <Renderer {...tileData.props} />
            </div>
          );
        })}
        {/* Indicator layer (overlay) */}
        {indicatorHexes.map(
          ({
            hexId,
            q,
            r,
            levelId: hexLevelId,
            indicatorIndex,
            indicatorType,
            indicatorProps,
          }) => {
            // Check if the indicator type exists in the registry
            const indicatorTypeKey =
              indicatorType in allRegionAvailableIndicators
                ? (indicatorType as AllLevelsAvailableIndicators)
                : null;
            if (!indicatorTypeKey) return null;

            return (
              <div
                key={`indicator-${hexLevelId}-${hexId}-${indicatorIndex}`}
                className="placed-hex hex-sized"
                style={
                  {
                    "--q": q,
                    "--r": r,
                    "--parity": Math.abs(r + 1) % 2,
                  } as React.CSSProperties
                }
              >
                <AnyIndicatorContentRenderer
                  id={indicatorTypeKey}
                  indicatorProps={indicatorProps}
                />
              </div>
            );
          },
        )}
      </div>
    </div>
  );
}
