// Client definitions for the Blueprint level
import blueprint0 from "./assets/blueprint/13_hex_0_1.png";
import blueprint1 from "./assets/blueprint/14_hex_1_0.png";
import blueprint2 from "./assets/blueprint/15_hex_1_2.png";
import blueprint3 from "./assets/blueprint/16_hex_0_2.png";
import blueprint4 from "./assets/blueprint/17_hex_1_1.png";
import type { MysteryTileEntry } from "./types";

const BLUEPRINT_TILES = [
  blueprint0,
  blueprint1,
  blueprint2,
  blueprint3,
  blueprint4,
];

export const BLUEPRINT_TILE_COUNT = BLUEPRINT_TILES.length;

const BlueprintTile = ({ idx }: { idx: number }) => (
  <div>
    <img
      src={BLUEPRINT_TILES[idx]}
      alt={`Blueprint tile ${idx + 1}`}
      draggable="false"
    />
  </div>
);

export const blueprintRegistryEntries = Array.from(
  { length: BLUEPRINT_TILE_COUNT },
  (_, idx) =>
    [
      `mystery-blueprint-${idx}-tile`,
      (_props: Record<string, unknown>) => <BlueprintTile idx={idx} />,
    ] as const,
) satisfies readonly MysteryTileEntry[];
