import { FINAL_LEVEL_UNLOCK_DEFINITIONS } from "../../../levels/final-level-unlock-definitions";
import { createLevelBuilder, createMapBuilder } from "../../../levels/types";
import { createFinalLevelUnlockTransform } from "../../../levels/utilities";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import { type worthwhileSuitAvailableSlots } from "./client";
import { levelA } from "./level-a";
import { levelB } from "./level-b";
import { levelC } from "./level-c";
import { levelD } from "./level-d";
import { levelE } from "./level-e";
import { levelF } from "./level-f";
import { levelG } from "./level-g";
import { levelH } from "./level-h";
import { levelI } from "./level-i";
import { levelJ } from "./level-j";
import { levelK } from "./level-k";
import { levelL } from "./level-l";

const finalLevelUnlockTransform = createFinalLevelUnlockTransform(
  "worthwhile-suit-empty-slot",
  "underwater_hunt",
  FINAL_LEVEL_UNLOCK_DEFINITIONS.underwater_hunt,
);

const submissionLevelBuilder = createLevelBuilder<
  worthwhileSuitAvailableSlots,
  AllAvailableTiles
>()
  .addSlot("-21,-23", "worthwhile-suit-empty-slot", {})
  .addSubmission({
    hexId: "-21,-23",
    puzzleSlug: "underwater_hunt",
  })
  .addUnlockTransform(finalLevelUnlockTransform);

export const worthwhileSuitLevels = createMapBuilder()
  .setTitle("Underwater Hunt")
  .addLevel("worthwhile-suit-level-a", levelA)
  .addLevel("worthwhile-suit-level-b", levelB)
  .addLevel("worthwhile-suit-level-c", levelC)
  .addLevel("worthwhile-suit-level-d", levelD)
  .addLevel("worthwhile-suit-level-e", levelE)
  .addLevel("worthwhile-suit-level-f", levelF)
  .addLevel("worthwhile-suit-level-g", levelG)
  .addLevel("worthwhile-suit-level-h", levelH)
  .addLevel("worthwhile-suit-level-i", levelI)
  .addLevel("worthwhile-suit-level-j", levelJ)
  .addLevel("worthwhile-suit-level-k", levelK)
  .addLevel("worthwhile-suit-level-l", levelL)
  .addLevel("submission-worthwhile-suit-level", submissionLevelBuilder.build())
  .build();
