export function getFontSizeClass(text: string): string {
  const maxLength = Math.max(...text.split(" ").map((word) => word.length));
  if (maxLength <= 3) return "text-3xl";
  if (maxLength <= 8) return "text-xl";
  if (maxLength <= 11) return "text-lg";
  if (maxLength <= 14) return "text-sm";
  return "text-xs";
}
