// Helpful constants.
const HEXAGON_RADIUS = 60;
const HEXAGON_SIDE_LENGTH = Math.sqrt(3) * HEXAGON_RADIUS;
const HEXAGON_HEIGHT = 2 * HEXAGON_RADIUS;

function ClueTooltip({
  word1,
  word2,
  value,
}: {
  word1: string;
  word2: string;
  value: number;
}) {
  return (
    <span className="text-black text-xl">
      <span className="text-[#0000FF] font-bold">{word1.slice(-1)}</span>
      &nbsp;...&nbsp;
      <span className="text-[#FF0000] font-bold">
        {word2.slice(0, 1)}
      </span> = {value}
    </span>
  );
}

type RottenBuckSlotProps = {
  color?: string;
};
export const RottenBuckSlot = ({ color }: RottenBuckSlotProps) => {
  return <div className="h-full w-full" style={{ backgroundColor: color }} />;
};

type RottenBuckWordProps = {
  word1: string;
  word2: string;
  value?: number;
  noBold?: boolean;
};
export function RottenBuckWord({
  word1,
  word2,
  value,
  noBold,
}: RottenBuckWordProps) {
  return (
    <ConditionalTooltip
      tooltip={
        value ? (
          <ClueTooltip word1={word1} word2={word2} value={value} />
        ) : undefined
      }
      className="bg-white border-2 border-black"
    >
      <div
        className="w-full h-full flex flex-col items-center justify-center text-base font-mono"
        style={{ backgroundColor: "#ffffff80" }}
      >
        <span className="text-[#0000FF]" aria-label={word1}>
          {word1.length > 1 ? word1.slice(0, -1) : ""}
          <span className={noBold ? undefined : "font-bold"}>
            {word1.slice(-1)}
          </span>
          {/* Add spaces in the end to offset the word. */}
          {[...Array(word2.length - 1).keys()].map((index) => (
            <span key={index} aria-hidden="true">
              &nbsp;
            </span>
          ))}
        </span>
        <span className="text-[#FF0000]" aria-label={word2}>
          {/* Add spaces in the beginning to offset the word. */}
          {[...Array(word1.length - 1).keys()].map((index) => (
            <span key={index} aria-hidden="true">
              &nbsp;
            </span>
          ))}
          <span className={noBold ? undefined : "font-bold"}>
            {word2.charAt(0)}
          </span>
          {word2.slice(1)}
        </span>
      </div>
    </ConditionalTooltip>
  );
}

type SideId = 0 | 1 | 2 | 3 | 4 | 5;
type Position = { top: string; left: string | number };

const calculatePosition = (sideId: SideId): Position | undefined => {
  const sideLength = HEXAGON_SIDE_LENGTH / 2;
  const angleOffset = Math.PI / 3;

  switch (sideId) {
    case 0: // Right side
      return {
        top: `${HEXAGON_HEIGHT / 2}px`,
        left: `${HEXAGON_SIDE_LENGTH}px`,
      };
    case 1: // Bottom-right side
      return {
        top: `${HEXAGON_HEIGHT / 2 + sideLength * Math.sin(angleOffset)}px`,
        left: `${HEXAGON_SIDE_LENGTH / 2 + sideLength * Math.cos(angleOffset)}px`,
      };
    case 2: // Bottom-left side
      return {
        top: `${HEXAGON_HEIGHT / 2 + sideLength * Math.sin(angleOffset)}px`,
        left: `${HEXAGON_SIDE_LENGTH / 2 - sideLength * Math.cos(angleOffset)}px`,
      };
    case 3: // Left side
      return {
        top: `${HEXAGON_HEIGHT / 2}px`,
        left: 0,
      };
    case 4: // Top-left side
      return {
        top: `${HEXAGON_HEIGHT / 2 - sideLength * Math.sin(angleOffset)}px`,
        left: `${HEXAGON_SIDE_LENGTH / 2 - sideLength * Math.cos(angleOffset)}px`,
      };
    case 5: // Top-right side
      return {
        top: `${HEXAGON_HEIGHT / 2 - sideLength * Math.sin(angleOffset)}px`,
        left: `${HEXAGON_SIDE_LENGTH / 2 + sideLength * Math.cos(angleOffset)}px`,
      };
    default:
      return undefined;
  }
};

const ColoredDot = ({
  color,
  position,
}: {
  color: string;
  position: Position;
}) => {
  return (
    <div
      className="absolute w-4 h-4 rounded-full -translate-x-1/2 -translate-y-1/2 z-10"
      style={{
        backgroundColor: color,
        ...position,
      }}
    />
  );
};

const ColoredDotsIndicator = ({
  redIndex,
  blueIndex,
}: {
  redIndex?: SideId;
  blueIndex?: SideId;
}) => {
  let redPosition;
  let bluePosition;
  if (redIndex !== undefined) {
    redPosition = calculatePosition(redIndex);
  }
  if (blueIndex !== undefined) {
    bluePosition = calculatePosition(blueIndex);
  }
  return (
    <>
      {redPosition && <ColoredDot color="red" position={redPosition} />}
      {bluePosition && <ColoredDot color="blue" position={bluePosition} />}
    </>
  );
};

