export const fireflyRegion = createRegionBuilder()
  .addSlotType(
    "submission-slot",
    SubmissionSlot as React.FC<Record<string, unknown>>,
  )
  .addSlotType(
    "empty-slot-rotten-buck",
    RottenBuckSlot as React.FC<Record<string, unknown>>,
  )
  .addIndicatorType(
    "colored-dots-indicator",
    ColoredDotsIndicator as React.FC<Record<string, unknown>>,
  )
  .addTileGroup("fire-blue", "Fire: Blue arrows")
  .addTileGroup("fly-red", "Fly: Red arrows")
  .addTileGroup("firefly-blue", "Firefly: Blue arrows")
  .addTileGroup("firefly-red", "Firefly: Red arrows")
  .addTileGroup("firefly-purple", "Firefly: Purple arrows")
  .addTileGroup("tomato-soup-blue", "Tomato Soup: Blue arrows")
  .build();

export type FireflyAvailableSlots = keyof typeof fireflyRegion.slots;
export type FireflyAvailableTiles = keyof typeof fireflyRegion.tiles;
export type FireflyAvailableIndicators = keyof typeof fireflyRegion.indicators;
