Object.entries(levelFEmojiTiles).forEach(([key, value]) => {
  levelFBuilder.addTileToBank(
    key.replace(/ /g, "-") + "-tile",
    1,
    {
      renderer: "emoji-tile",
      props: {
        emoji: value.emoji,
        tooltip: value.tooltip,
      },
    },
    emojiTileGroup,
  );
});

