type CoordinateKey = `${number},${number}`;
const devModePronounUsages = new Set<string>();

function replaceImageWithVarName(obj: unknown): unknown {
  // 1. Base case: If obj is not an object or is null, stop.
  if (typeof obj !== "object" || obj === null) {
    return obj;
  }
  const record = obj as Record<string, unknown>;

  // 2. Iterate over every key in the object/array
  if ("image" in record && "image_name" in record) {
    record.image = record.image_name;
    delete record.image_name;
    return record;
  }
  for (const key in record) {
    record[key] = replaceImageWithVarName(record[key]);
  }
  return record;
}

function stringifyObject(obj: unknown): string {
  obj = replaceImageWithVarName(obj);
  const stringifiedObject = JSON.stringify(obj);
  const regex = /"image"\s*:\s*"([^"]+)"/g;
  return stringifiedObject.replace(regex, '"image":$1');
}

// Avoid direct `process` references so accidental client bundling does not crash.
const isDevEnglishEnv = (): boolean => {
  const maybeEnv =
    typeof globalThis !== "undefined" &&
    typeof (globalThis as { process?: { env?: Record<string, string> } })
      .process !== "undefined"
      ? (globalThis as { process?: { env?: Record<string, string> } }).process
          ?.env
      : undefined;

  return (
    maybeEnv?.NODE_ENV === "development" && maybeEnv?.CONLANG_ENV === "english"
  );
};

function getNumberGlyph(shape: Shape, number: number): string {
  if (!(number in NUMBER_GLYPHS[shape])) {
    throw new Error(
      `Number glyph not found for number: "${number}", numberOfKeys "${Object.keys(NUMBER_GLYPHS[shape]).length}"`,
    );
  }
  return NUMBER_GLYPHS[shape]?.[number];
}

function getNumberGlyphImageName(shape: Shape, number: number): string {
  if (!(number in NUMBER_GLYPHS[shape])) {
    throw new Error(
      `Number glyph not found for number: "${number}", numberOfKeys "${Object.keys(NUMBER_GLYPHS[shape]).length}"`,
    );
  }
  return `${shape}_Number_${number.toString().padStart(2, "0")}`;
}

function getGlyphImage(props: GlyphTileProps): string {
  if (props.word_number === -1) {
    return MISSING_GLYPH;
  }
  if (props.radical_type === "Junction") {
    return JUNCTION_GLYPHS[props.word_number];
  }
  if (props.radical_type === "Word") {
    return WORD_GLYPHS[props.radical_number][props.word_number][props.shape];
  }
  return getNumberGlyph(props.shape, props.word_number);
}

function getGlyphImageName(props: GlyphTileProps): string {
  if (props.word_number === -1) {
    return "MISSING_GLYPH";
  }
  if (props.radical_type === "Junction") {
    return `Junction${props.word_number + 1}`;
  }
  if (props.radical_type === "Word") {
    return WORD_GLYPHS[props.radical_number][props.word_number][
      `${props.shape}ImageName`
    ];
  }
  return getNumberGlyphImageName(props.shape, props.word_number);
}

function getPronounGlyph(
  props: GlyphTileProps,
  gloss: string,
  pronounIndex: number,
): string {
  if (props.radical_type !== "Word") {
    throw new Error("Pronoun glyphs can only be for Word radical types");
  }
  const pronouns =
    WORD_GLYPHS[props.radical_number][props.word_number][
      `${props.shape}Pronouns`
    ];
  const wordId = WORD_IDS[props.radical_number][props.word_number];
  if (pronouns === undefined || pronouns.length <= pronounIndex) {
    throw new Error(
      `Pronoun glyph not found for word id: "${wordId}", pronounIndex: ${pronounIndex}, shape: ${props.shape}, gloss: "${gloss}"`,
    );
  }
  devModePronounUsages.add(`${props.shape}_${wordId}`);
  return pronouns[pronounIndex];
}

function getGlyph(gloss: string): GlyphTileProps {
  if (gloss === "X") {
    return { radical_type: "Junction", word_number: 2 };
  }
  if (gloss === "-\\-") {
    return { radical_type: "Junction", word_number: 0 };
  }
  if (gloss === "-/-") {
    return { radical_type: "Junction", word_number: 1 };
  }
  if (gloss === "-X-") {
    return { radical_type: "Junction", word_number: 3 };
  }
  for (const { words, radical_number } of Object.values(RADICAL_MAP)) {
    for (const [word_number, word] of words.entries()) {
      if (word.verbGlosses?.includes(gloss)) {
        if (word.isNumber) {
          return {
            radical_type: "Number",
            shape: "Circle",
            word_number: parseInt(gloss, 10),
          };
        }
        return {
          radical_type: "Word",
          shape: "Circle",
          radical_number,
          word_number,
        };
      }
      if (word.nounGlosses?.includes(gloss)) {
        if (word.isNumber) {
          // 4 is the length of the suffix " (n)"
          return {
            radical_type: "Number",
            shape: "Triangle",
            word_number: parseInt(gloss.slice(0, -4), 10),
          };
        }

        return {
          radical_type: "Word",
          shape: "Triangle",
          radical_number,
          word_number,
        };
      }
      if (word.connectiveGlosses?.includes(gloss)) {
        return {
          radical_type: "Word",
          shape: "Square",
          radical_number,
          word_number,
        };
      }
    }
  }
  if (gloss === "?") {
    return {
      radical_type: "Word",
      shape: "Circle",
      word_number: -1,
      radical_number: -1,
    };
  }
  throw new Error(`Glyph not found for gloss: "${gloss}"`);
}

function createTileId(props: GlyphTileProps) {
  if (props.radical_type === "Junction") {
    return `glyph-Junction-${props.word_number}`;
  }
  if (props.radical_type === "Number") {
    return `glyph-Number-${props.shape}-${props.word_number}`;
  }
  return `glyph-Word-${props.shape}-${props.radical_number}-${props.word_number}`;
}

function calculateSlotCoordinate(
  slot: HexData,
  qOffset: number,
  rOffset: number,
  slots: readonly HexData[],
): CoordinateKey {
  let modifiedQ = qOffset + slot.q;
  const modifiedR = rOffset + slot.r;
  if (slots.length < 1) {
    return `${modifiedQ},${modifiedR}`;
  }
  if (rOffset % 2 === 0 && slot.r % 2 !== slots[0]?.r % 2) {
    if (slots[0]?.r % 2 === 0) {
      modifiedQ--;
    } else {
      modifiedQ++;
    }
  }
  return `${modifiedQ},${modifiedR}`;
}

function getLeftmostRow(hexes: readonly HexData[]): number | undefined {
  if (hexes.length < 1) {
    return undefined;
  }
  let minQ = hexes[0].q;
  let leftmostRow = hexes[0].r;
  for (const hex of hexes) {
    if (hex.r % 2 !== 0) {
      if (hex.q <= minQ) {
        minQ = hex.q;
        leftmostRow = hex.r;
      }
    } else {
      if (hex.q < minQ) {
        minQ = hex.q;
        leftmostRow = hex.r;
      }
    }
  }
  return leftmostRow;
}

function getWordTile(
  glyph: GlyphTileProps,
  gloss: string,
): TileVariantDefinition<AllAvailableTiles> {
  if (isDevEnglishEnv()) {
    return getDevModeTile(glyph, gloss);
  }
  return {
    renderer: "glyph-tile",
    props: {
      ...glyph,
      image: getGlyphImage(glyph),
      image_name: getGlyphImageName(glyph),
    },
  };
}

function getDevModeTile(
  glyph: GlyphTileProps,
  gloss: string,
  pronoun?: number,
): TileVariantDefinition<AllAvailableTiles> {
  // Dev-only visualization to easily see what the tiles actually represent
  return {
    renderer: "snoopy-shoe-tile",
    props: {
      center: gloss,
      topLeft: "",
      topRight: "",
      right: "",
      bottomRight: getDevModeRadicalName(glyph),
      bottomLeft: getDevModePartOfSpeech(glyph),
      left: pronoun !== undefined ? `P${pronoun}` : "",
    },
  };
}

function getDevModePartOfSpeech(glyph: GlyphTileProps): string {
  if (glyph.radical_type !== "Word" && glyph.radical_type !== "Number") {
    return "";
  }
  const shape = glyph.shape;
  if (shape === "Circle") {
    return "Verb";
  }
  if (shape === "Triangle") {
    return "Noun";
  }
  if (shape === "Square") {
    return "Connective";
  }
  return "";
}

function getDevModeRadicalName(glyph: GlyphTileProps): string {
  if (glyph.radical_type !== "Word") {
    return "";
  }

  for (const [radicalName, radicalData] of Object.entries(RADICAL_MAP)) {
    if (radicalData.radical_number === glyph.radical_number) {
      return radicalName;
    }
  }
  return "";
}

function getPronounTile(
  glyph: GlyphTileProps,
  gloss: string,
  pronounIndex: number,
): TileVariantDefinition<AllAvailableTiles> {
  if (isDevEnglishEnv()) {
    return getDevModeTile(glyph, gloss, pronounIndex);
  }
  return {
    renderer: "glyph-tile",
    props: {
      ...glyph,
      image: getPronounGlyph(glyph, gloss, pronounIndex),
      isPronoun: true,
    },
  };
}

function buildLevel(level_data: LevelData, missingSlots: CoordinateKey[]) {
  const builder = createLevelBuilder<
    DanceOfTheBumblebeeAvailableSlots,
    AllAvailableTiles
  >().setTitle(level_data.name);

  const solution: Record<string, string> = {};

  // Tile bank is keyed on the unique tile ID and stores the props and count
  const tileBank = new Map<string, { count: number; props: GlyphTileProps }>();
  // For dev purposes only
  const devGlossMap = new Map<string, string>();
  for (const sublevel of level_data.sublevels) {
    const { slots, slotsOffset, clues, clueSlot } = sublevel;
    if (slotsOffset === undefined) {
      throw new Error("Missing slots offset");
    }
    const qOffset = slotsOffset.qOffset;
    const rOffset = slotsOffset.rOffset;
    for (const slot of slots) {
      const slotCoordinate: CoordinateKey = calculateSlotCoordinate(
        slot,
        qOffset,
        rOffset,
        slots,
      );
      builder.addSlot(slotCoordinate, "empty-glyph-slot");
      const glyph = getGlyph(slot.gloss);

      // If the slot is locked, add a given tile.
      // Otherwise, add the tile to the tile bank and add it to the solution.
      // The tile bank represents all available tiles across the entire level
      // so we accumulate all available tiles in the bank and then add them
      // to the level builder at the end.
      if (slot.isLocked) {
        if (slot.pronoun !== undefined) {
          builder.addGivenTile(
            // @ts-expect-error: Slots are generated dynamically
            slotCoordinate,
            getPronounTile(glyph, slot.gloss, slot.pronoun),
          );
        } else {
          // @ts-expect-error: Slots are generated dynamically
          builder.addGivenTile(slotCoordinate, getWordTile(glyph, slot.gloss));
        }
      } else {
        const id = createTileId(glyph);
        const entry = tileBank.get(id) ?? { count: 0, props: glyph };
        entry.count++;
        tileBank.set(id, entry);

        solution[slotCoordinate] = id;
        devGlossMap.set(id, slot.gloss);
      }
    }

    // Add the sublevel's clues.
    if (clues !== undefined && clueSlot !== undefined) {
      const safeClueSlot = clueSlot as HexData;
      // The clues are all stacked at one location.
      const clueCoordinate: CoordinateKey = calculateSlotCoordinate(
        safeClueSlot,
        qOffset,
        rOffset,
        slots,
      );
      builder.addSlot(clueCoordinate, "empty-glyph-slot");
      let clueIcon = "";
      if (safeClueSlot.gloss === ".") {
        clueIcon = "👁‍🗨";
      } else if (safeClueSlot.gloss === "?") {
        clueIcon = "💡";
      } else if (safeClueSlot.gloss === "*") {
        clueIcon = "📖";
      }
      // @ts-expect-error: Slots are generated dynamically
      builder.addGivenTile(clueCoordinate, {
        renderer: "emoji-tile",
        props: {
          emoji: clueIcon,
        },
      });
      const clueList = [];
      for (const clue of clues) {
        if ("image_url" in clue) {
          // Image clue
          clueList.push({
            type: "image",
            image_url: clue.image_url,
          });
        } else if ("sentence" in clue) {
          // Sentence clue with glyphs
          const clue_map: Record<string, unknown> = {};
          const leftmostRow = getLeftmostRow(clue.sentence);
          if (leftmostRow === undefined) {
            throw new Error("Missing leftmost row");
          }
          for (const word of clue.sentence) {
            const glyph = getGlyph(word.gloss);
            const sentenceCoordinate: CoordinateKey = calculateSlotCoordinate(
              word,
              0,
              leftmostRow % 2 === 0 ? 1 : 0,
              clue.sentence,
            );
            if (word.pronoun === undefined) {
              clue_map[sentenceCoordinate] = getWordTile(glyph, word.gloss);
            } else {
              clue_map[sentenceCoordinate] = getPronounTile(
                glyph,
                word.gloss,
                word.pronoun,
              );
            }
          }
          clueList.push({
            type: "hexes",
            size: 120,
            map: clue_map,
          });
        } else if ("type" in clue && clue.type === "lexicon") {
          clueList.push({
            type: "lexicon",
          });
        }
      }
      // @ts-expect-error: Slots are generated dynamically
      builder.addClues(clueCoordinate, clueList);
    }
  }

  // Add extra tiles to the tile bank to make the level more challenging.
  for (const unusedTile of level_data?.unusedTileBank ?? []) {
    const glyph = getGlyph(unusedTile);
    const id = createTileId(glyph);
    const entry = tileBank.get(id) ?? { count: 0, props: glyph };
    entry.count++;
    tileBank.set(id, entry);
    devGlossMap.set(id, unusedTile);
  }

  // Add empty filler tiles to the grid.
  if (level_data.emptyFill !== undefined) {
    for (const emptyTile of level_data.emptyFill) {
      const slotCoordinate: CoordinateKey = `${emptyTile.q},${emptyTile.r}`;
      builder.addSlot(slotCoordinate, "empty-glyph-slot");
      // @ts-expect-error: Slots are generated dynamically
      builder.addGivenTile(slotCoordinate, {
        renderer: "unused-tile",
        props: {},
      });
    }
  }
  for (const missingSlot of missingSlots) {
    builder.addSlot(missingSlot, "empty-glyph-slot");
    // @ts-expect-error: Slots are generated dynamically
    builder.addGivenTile(missingSlot, {
      renderer: "unused-tile",
      props: {},
    });
  }

  // Actually add the tiles to the tile bank
  const allTiles: { id: string; count: number; props: GlyphTileProps }[] = [];
  for (const [id, entry] of tileBank) {
    allTiles.push({ id, count: entry.count, props: entry.props });
  }
  allTiles.sort((a, b) => a.id.localeCompare(b.id));

  for (const { id, count, props } of allTiles) {
    const devGloss = devGlossMap.get(id) ?? "glossNotFound";
    builder.addTileToBank(id, count, getWordTile(props, devGloss));
  }
  builder.setSolution(solution);
  return builder;
}

const finalLevelUnlockTransform = createFinalLevelUnlockTransform(
  "empty-glyph-slot",
  "dance_of_the_bumblebee",
  FINAL_LEVEL_UNLOCK_DEFINITIONS.dance_of_the_bumblebee,
);

// Pruned down version of the general level builder because the
// submission region is simpler. However, this method is separate
// because we need to set a different solution function and we need
// to add an unlock criteria and submission tile. This method can be
// removed if we allow for an empty submission criteria.
function buildSubmissionLevel(level_data: LevelData) {
  let builder = createLevelBuilder<
    DanceOfTheBumblebeeAvailableSlots,
    AllAvailableTiles
  >().setTitle(level_data.name);

  for (const sublevel of level_data.sublevels) {
    const { slots, slotsOffset } = sublevel;
    if (slotsOffset === undefined) {
      throw new Error("Missing slots offset");
    }
    const qOffset = slotsOffset.qOffset;
    const rOffset = slotsOffset.rOffset;
    for (const slot of slots) {
      const slotCoordinate: CoordinateKey = calculateSlotCoordinate(
        slot,
        qOffset,
        rOffset,
        slots,
      );
      builder.addSlot(slotCoordinate, "empty-glyph-slot");
      const glyph = getGlyph(slot.gloss);
      if (slot.isLocked) {
        if (slot.pronoun !== undefined) {
          builder.addGivenTile(
            // @ts-expect-error: Slots are generated dynamically
            slotCoordinate,
            getPronounTile(glyph, slot.gloss, slot.pronoun),
          );
        } else {
          // @ts-expect-error: Slots are generated dynamically
          builder.addGivenTile(slotCoordinate, getWordTile(glyph, slot.gloss));
        }
      }
    }
  }

  // Add submission tile
  const submissionTileCoordinate: CoordinateKey = `${SUBMISSION_TILE.q},${SUBMISSION_TILE.r}`;
  builder.addSlot(submissionTileCoordinate, "empty-glyph-slot");
  builder.setSolution({});
  builder = builder.addUnlockTransform(finalLevelUnlockTransform);
  builder = builder.addSubmission({
    hexId: submissionTileCoordinate,
    puzzleSlug: "dance_of_the_bumblebee",
  });
  return builder;
}

type SlotStatus = {
  filled: boolean;
  filledBy: string;
  r: number;
  q: number;
  level: number;
};

/**
 * Validates that all levels correctly fill the required region slots.
 * Ensures each slot in FULL_REGION_AREA is filled exactly once across all levels.
 * Checks for duplicate slot assignments and verifies submission tile placement.
 *
 * FULL_REGION_AREA defines the set of all valid slot coordinates for the region.
 * The function throws an error if any required slot is missing, duplicated, or placed outside the valid region.
 *
 * @param levels - Array of level data to validate
 * @throws Error if slots are missing, duplicated, or placed outside the valid region
 */
function validateLevels(
  levels: LevelData[],
): Record<CoordinateKey, SlotStatus> {
  const requiredSlots: Record<CoordinateKey, SlotStatus> = {};
  for (const [row, tupleList] of Object.entries(FULL_REGION_AREA)) {
    for (const [qMin, qMax] of tupleList) {
      for (let q = qMin; q <= qMax; q++) {
        requiredSlots[`${q},${parseInt(row)}`] = {
          filled: false,
          filledBy: "",
          r: parseInt(row),
          q,
          level: -1,
        };
      }
    }
  }
  for (const [level_index, level] of levels.entries()) {
    for (const { slots, slotsOffset, clues, clueSlot } of level.sublevels) {
      if (slotsOffset === undefined) {
        throw new Error(`slotsOffset for level ${level.codename} is undefined`);
      }
      const qOffset = slotsOffset.qOffset;
      const rOffset = slotsOffset.rOffset;
      for (const slot of slots) {
        const slotCoordinate: CoordinateKey = calculateSlotCoordinate(
          slot,
          qOffset,
          rOffset,
          slots,
        );
        if (requiredSlots[slotCoordinate] === undefined) {
          throw new Error(
            `Slot ${slotCoordinate} is not in the required slots for this puzzle but is being filled by ${level.codename} @ (${slot.q},${slot.r})`,
          );
        }
        if (requiredSlots[slotCoordinate].filled) {
          throw new Error(
            `Slot ${slotCoordinate} is being filled twice: ${requiredSlots[slotCoordinate].filledBy} and ${level.codename} slots (${slot.q},${slot.r})`,
          );
        }
        requiredSlots[slotCoordinate] = {
          filled: true,
          filledBy: `Filled by ${level.codename} slots (${slot.q},${slot.r})`,
          level: level_index,
          r: requiredSlots[slotCoordinate].r,
          q: requiredSlots[slotCoordinate].q,
        };
      }

      if (clues !== undefined && clueSlot !== undefined) {
        const safeClueSlot = clueSlot as HexData;
        const clueCoordinate: CoordinateKey = calculateSlotCoordinate(
          safeClueSlot,
          qOffset,
          rOffset,
          slots,
        );
        if (requiredSlots[clueCoordinate] === undefined) {
          throw new Error(
            `Slot ${clueCoordinate} is not in the required slots for this puzzle but is being filled by ${level.codename} @ (${safeClueSlot.q},${safeClueSlot.r})`,
          );
        }
        if (requiredSlots[clueCoordinate].filled) {
          throw new Error(
            `Slot ${clueCoordinate} is being filled twice: ${requiredSlots[clueCoordinate].filledBy} and ${level.codename} clue slot (${safeClueSlot.q},${safeClueSlot.r})`,
          );
        }
        requiredSlots[clueCoordinate] = {
          filled: true,
          filledBy: `Filled by ${level.codename} clue slot (${safeClueSlot.q},${safeClueSlot.r})`,
          level: level_index,
          r: requiredSlots[clueCoordinate].r,
          q: requiredSlots[clueCoordinate].q,
        };
      }
    }
    for (const { q, r } of level?.emptyFill ?? []) {
      const emptyFillCoordinate: CoordinateKey = `${q},${r}`;
      if (requiredSlots[emptyFillCoordinate] === undefined) {
        throw new Error(
          `Slot ${emptyFillCoordinate} is not in the required slots for this puzzle but is being filled by ${level.codename} @ (${q},${r})`,
        );
      }
      if (requiredSlots[emptyFillCoordinate].filled) {
        throw new Error(
          `Slot ${emptyFillCoordinate} is being filled twice: ${requiredSlots[emptyFillCoordinate].filledBy} and ${level.codename} empty fill (${q},${r})`,
        );
      }
      requiredSlots[emptyFillCoordinate] = {
        filled: true,
        filledBy: `Filled by ${level.codename} empty fill (${q},${r})`,
        level: level_index,
        r: requiredSlots[emptyFillCoordinate].r,
        q: requiredSlots[emptyFillCoordinate].q,
      };
    }
  }

  // Add submission tile
  const submissionTileCoordinate: CoordinateKey = `${SUBMISSION_TILE.q},${SUBMISSION_TILE.r}`;
  if (requiredSlots[submissionTileCoordinate] === undefined) {
    throw new Error(
      `Slot ${submissionTileCoordinate} is not in the required slots for this puzzle but is being filled by submission tile @ (${SUBMISSION_TILE.q},${SUBMISSION_TILE.r})`,
    );
  }
  if (requiredSlots[submissionTileCoordinate].filled) {
    throw new Error(
      `Slot ${submissionTileCoordinate} is being filled twice: ${requiredSlots[submissionTileCoordinate].filledBy} and submission tile`,
    );
  }
  requiredSlots[submissionTileCoordinate] = {
    filled: true,
    filledBy: "Filled by submission tile",
    level: 10,
    r: requiredSlots[submissionTileCoordinate].r,
    q: requiredSlots[submissionTileCoordinate].q,
  };

  // TODO: add this back in after Sam gets his shit back together
  // const missingSlots = Object.entries(requiredSlots)
  //   .filter(([_, value]) => !value.filled)
  //   .map(([coord]) => coord);

  const missingSlotAssignments: Record<CoordinateKey, SlotStatus> = {};
  for (const missingSlotCoordinate of Object.keys(
    requiredSlots,
  ) as CoordinateKey[]) {
    let found = false;
    const missingSlotStatus = requiredSlots[missingSlotCoordinate];
    if (missingSlotStatus.filled) {
      continue;
    }
    for (let distance = 1; distance < 5; distance++) {
      for (const otherCoordinate of Object.keys(
        requiredSlots,
      ) as CoordinateKey[]) {
        const otherSlotStatus = requiredSlots[otherCoordinate];
        if (
          otherSlotStatus.filled &&
          otherSlotStatus.level !== 10 &&
          Math.abs(otherSlotStatus.q - missingSlotStatus.q) +
            Math.abs(otherSlotStatus.r - missingSlotStatus.r) <=
            distance
        ) {
          missingSlotAssignments[missingSlotCoordinate as CoordinateKey] = {
            filled: true,
            filledBy: `Filled by ${otherSlotStatus.filledBy}`,
            level: otherSlotStatus.level,
            r: missingSlotStatus.r,
            q: missingSlotStatus.q,
          };
          found = true;
          break;
        }
      }
      if (found) {
        break;
      }
    }

    if (!found) {
      throw new Error(
        `Dance of the Bumblebee levels missing nearest tiles at coordinates: ${missingSlotCoordinate}`,
      );
    }
  }
  return missingSlotAssignments;
  // if (missingSlots.length > 0) {
  //   throw new Error(
  //     `Dance of the Bumblebee levels are missing tiles at coordinates: ${missingSlots.join(", ")}`,
  //   );
  // }
}

function printLevelBuilder(
  level_data: LevelData,
  missingSlots: CoordinateKey[],
) {
  let output = "";
  output += `const level${level_data.codename}Builder = createLevelBuilder<
    DanceOfTheBumblebeeAvailableSlots,
    AllAvailableTiles
  >()\n`;
  output += `.setTitle("${level_data.name}")\n`;

  const solution: Record<string, string> = {};

  // Tile bank is keyed on the unique tile ID and stores the props and count
  const tileBank = new Map<string, { count: number; props: GlyphTileProps }>();
  // For dev purposes only
  const devGlossMap = new Map<string, string>();
  for (const sublevel of level_data.sublevels) {
    const { slots, slotsOffset, clues, clueSlot } = sublevel;
    if (slotsOffset === undefined) {
      throw new Error("Missing slots offset");
    }
    const qOffset = slotsOffset.qOffset;
    const rOffset = slotsOffset.rOffset;
    for (const slot of slots) {
      const slotCoordinate: CoordinateKey = calculateSlotCoordinate(
        slot,
        qOffset,
        rOffset,
        slots,
      );
      output += `.addSlot("${slotCoordinate}", "empty-glyph-slot")\n`;
      const glyph = getGlyph(slot.gloss);

      // If the slot is locked, add a given tile.
      // Otherwise, add the tile to the tile bank and add it to the solution.
      // The tile bank represents all available tiles across the entire level
      // so we accumulate all available tiles in the bank and then add them
      // to the level builder at the end.
      if (slot.isLocked) {
        if (slot.pronoun !== undefined) {
          const pronounTile = getPronounTile(glyph, slot.gloss, slot.pronoun);
          output += `.addGivenTile("${slotCoordinate}", ${stringifyObject(pronounTile)})\n`;
        } else {
          const wordTile = getWordTile(glyph, slot.gloss);
          output += `.addGivenTile("${slotCoordinate}", ${stringifyObject(wordTile)})\n`;
        }
      } else {
        const id = createTileId(glyph);
        const entry = tileBank.get(id) ?? { count: 0, props: glyph };
        entry.count++;
        tileBank.set(id, entry);

        solution[slotCoordinate] = id;
        devGlossMap.set(id, slot.gloss);
      }
    }

    // Add the sublevel's clues.
    if (clues !== undefined && clueSlot !== undefined) {
      const safeClueSlot = clueSlot as HexData;
      // The clues are all stacked at one location.
      const clueCoordinate: CoordinateKey = calculateSlotCoordinate(
        safeClueSlot,
        qOffset,
        rOffset,
        slots,
      );
      output += `.addSlot("${clueCoordinate}", "empty-glyph-slot")\n`;
      let clueIcon = "";
      if (safeClueSlot.gloss === ".") {
        clueIcon = "👁‍🗨";
      } else if (safeClueSlot.gloss === "?") {
        clueIcon = "💡";
      } else if (safeClueSlot.gloss === "*") {
        clueIcon = "📖";
      }
      const emojiTile = {
        renderer: "emoji-tile",
        props: {
          emoji: clueIcon,
        },
      };
      output += `.addGivenTile("${clueCoordinate}", ${stringifyObject(emojiTile)})\n`;
      const clueList = [];
      for (const clue of clues) {
        if ("image_url" in clue) {
          // Image clue
          clueList.push({
            type: "image",
            image_url: clue.image_url,
          });
        } else if ("sentence" in clue) {
          // Sentence clue with glyphs
          const clue_map: Record<string, unknown> = {};
          const leftmostRow = getLeftmostRow(clue.sentence);
          if (leftmostRow === undefined) {
            throw new Error("Missing leftmost row");
          }
          for (const word of clue.sentence) {
            const glyph = getGlyph(word.gloss);
            const sentenceCoordinate: CoordinateKey = calculateSlotCoordinate(
              word,
              0,
              leftmostRow % 2 === 0 ? 1 : 0,
              clue.sentence,
            );
            if (word.pronoun === undefined) {
              clue_map[sentenceCoordinate] = getWordTile(glyph, word.gloss);
            } else {
              clue_map[sentenceCoordinate] = getPronounTile(
                glyph,
                word.gloss,
                word.pronoun,
              );
            }
          }
          clueList.push({
            type: "hexes",
            size: 120,
            map: clue_map,
          });
        } else if ("type" in clue && clue.type === "lexicon") {
          clueList.push({
            type: "lexicon",
          });
        }
      }
      output += `.addClues("${clueCoordinate}", ${stringifyObject(clueList)})\n`;
    }
  }

  // Add extra tiles to the tile bank to make the level more challenging.
  for (const unusedTile of level_data?.unusedTileBank ?? []) {
    const glyph = getGlyph(unusedTile);
    const id = createTileId(glyph);
    const entry = tileBank.get(id) ?? { count: 0, props: glyph };
    entry.count++;
    tileBank.set(id, entry);
    devGlossMap.set(id, unusedTile);
  }

  // Add empty filler tiles to the grid.
  if (level_data.emptyFill !== undefined) {
    for (const emptyTile of level_data.emptyFill) {
      const slotCoordinate: CoordinateKey = `${emptyTile.q},${emptyTile.r}`;
      output += `.addSlot("${slotCoordinate}", "empty-glyph-slot")\n`;

      const unusedTile = {
        renderer: "unused-tile",
        props: {},
      };
      output += `.addGivenTile("${slotCoordinate}", ${stringifyObject(unusedTile)})\n`;
    }
  }
  for (const missingSlot of missingSlots) {
    output += `.addSlot("${missingSlot}", "empty-glyph-slot")\n`;

    const unusedTile = {
      renderer: "unused-tile",
      props: {},
    };
    output += `.addGivenTile("${missingSlot}", ${stringifyObject(unusedTile)})\n`;
  }

  // Actually add the tiles to the tile bank
  const allTiles: { id: string; count: number; props: GlyphTileProps }[] = [];
  for (const [id, entry] of tileBank) {
    allTiles.push({ id, count: entry.count, props: entry.props });
  }
  allTiles.sort((a, b) => a.id.localeCompare(b.id));

  for (const { id, count, props } of allTiles) {
    const devGloss = devGlossMap.get(id) ?? "glossNotFound";
    const wordTile = getWordTile(props, devGloss);
    output += `.addTileToBank("${id}", ${count}, ${stringifyObject(wordTile)})\n`;
  }
  output += `.setSolution(${stringifyObject(solution)});\n`;
  output += `const level${level_data.codename} = level${level_data.codename}Builder.build();\n`;
  console.log(output);
}

function printSubmissionLevelBuilder(level_data: LevelData) {
  let output = "";
  output += `const level${level_data.codename}Builder = createLevelBuilder<
    DanceOfTheBumblebeeAvailableSlots,
    AllAvailableTiles
  >()\n`;
  output += `.setTitle("${level_data.name}")\n`;

  for (const sublevel of level_data.sublevels) {
    const { slots, slotsOffset } = sublevel;
    if (slotsOffset === undefined) {
      throw new Error("Missing slots offset");
    }
    const qOffset = slotsOffset.qOffset;
    const rOffset = slotsOffset.rOffset;
    for (const slot of slots) {
      const slotCoordinate: CoordinateKey = calculateSlotCoordinate(
        slot,
        qOffset,
        rOffset,
        slots,
      );
      output += `.addSlot("${slotCoordinate}", "empty-glyph-slot")\n`;
      const glyph = getGlyph(slot.gloss);
      if (slot.isLocked) {
        if (slot.pronoun !== undefined) {
          const pronounTile = getPronounTile(glyph, slot.gloss, slot.pronoun);
          output += `.addGivenTile("${slotCoordinate}", ${stringifyObject(pronounTile)})\n`;
        } else {
          const wordTile = getWordTile(glyph, slot.gloss);
          output += `.addGivenTile("${slotCoordinate}", ${stringifyObject(wordTile)})\n`;
        }
      }
    }
  }

  // Add submission tile
  const submissionTileCoordinate: CoordinateKey = `${SUBMISSION_TILE.q},${SUBMISSION_TILE.r}`;
  output += `.addSlot("${submissionTileCoordinate}", "empty-glyph-slot")\n`;
  output += `.setSolution({})\n`;
  output += `.addUnlockTransform(finalLevelUnlockTransform)\n`;

  const submissionTile = {
    hexId: submissionTileCoordinate,
    puzzleSlug: "dance_of_the_bumblebee",
  };
  output += `.addSubmission(${stringifyObject(submissionTile)});\n`;
  output += `const level${level_data.codename} = level${level_data.codename}Builder.build();\n`;
  console.log(output);
}

