import { createLevelBuilder } from "../../../levels/types";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import {
  ROOM2_TILE_COUNT,
  type MysteryAvailableSlots,
  type MysteryAvailableTileGroups,
} from "./client";

export const ROOM2_LEVEL_ID = "mystery-room-2-level";

const mysteryRoom2Tiles = Array.from(
  { length: ROOM2_TILE_COUNT },
  (_, idx) => `mystery-room-2-${idx}-tile` as AllAvailableTiles,
);

const mysteryRoom2LevelBuilder = createLevelBuilder<
  MysteryAvailableSlots,
  AllAvailableTiles,
  never,
  MysteryAvailableTileGroups
>()
  .setTitle("Kitchen")
  .addSlot("21,-10", "mystery-empty-slot")
  .addSlot("22,-10", "mystery-empty-slot")
  .addSlot("23,-10", "mystery-empty-slot")
  .addSlot("24,-10", "mystery-empty-slot")
  .addSlot("20,-9", "mystery-empty-slot")
  .addSlot("21,-9", "mystery-empty-slot")
  .addSlot("22,-9", "mystery-empty-slot")
  .addSlot("23,-9", "mystery-empty-slot")
  .addClues("22,-10", [
    {
      type: "text",
      text: 'A group photo with "Superhero Association" below it.',
    },
  ])
  .addClues("23,-10", [
    {
      type: "text",
      text: "Note to self: the Cap is allergic to peanuts",
    },
  ])
  .addClues("20,-9", [
    {
      type: "text",
      text: "There is smoke coming from the trash can.",
    },
  ])
  .addClues("21,-9", [
    {
      type: "text",
      text: "A weird stove with no burner or igniter.",
    },
  ])
  .addClues("23,-9", [
    {
      type: "text",
      text: "Shopping list: cucumbers, chicken, peanuts, strawberries,...",
    },
  ]);

mysteryRoom2Tiles.forEach((t) => {
  mysteryRoom2LevelBuilder.addTileToBank(
    t,
    1,
    { renderer: t, props: {} },
    "mystery-room-2",
  );
});

const ROOM_2_SOLUTION: Record<string, string> = {
  "21,-10": "mystery-room-2-4-tile",
  "22,-10": "mystery-room-2-7-tile",
  "23,-10": "mystery-room-2-2-tile",
  "24,-10": "mystery-room-2-0-tile",
  "20,-9": "mystery-room-2-6-tile",
  "21,-9": "mystery-room-2-5-tile",
  "22,-9": "mystery-room-2-3-tile",
  "23,-9": "mystery-room-2-1-tile",
};

mysteryRoom2LevelBuilder.setSolution(ROOM_2_SOLUTION);

export const mysteryRoom2Level = mysteryRoom2LevelBuilder.build();
