const getPuzzles = () => {
  if (typeof process !== "undefined" && (process.env.SPOILER_FREE === "1" || process.env.SPOILER_FREE === "true")) {
    return {};
  }
  const puzzlesWithBlurb = Object.fromEntries(
    Object.entries(PUZZLES_RAW).map(([slug, puzzle2]) => {
      if (BLURB_DATA[slug]) {
        return [
          slug,
          {
            ...puzzle2,
            initial_description: BLURB_DATA[slug]
          }
        ];
      }
      return [slug, puzzle2];
    })
  );
  return puzzlesWithBlurb;
};
