import type React from "react";

export type WordTilePartOfSpeech =
  | "noun"
  | "verb"
  | "adj/adv"
  | "person"
  | "location"
  | "power";

const WORD_TYPE_CLASSNAME = {
  noun: "bg-blue-600 text-white text-base text-center px-2",
  verb: "bg-yellow-500 text-base text-center px-2",
  "adj/adv": "bg-orange-500 text-white text-lg text-center px-2",
  person: "bg-green-600 text-white text-lg text-center px-2",
  location: "bg-purple-600 text-white text-lg text-center px-2",
  power: "bg-pink-500 text-white text-sm text-center px-2",
};

const getTileProps = (
  letter: string,
  type: WordTilePartOfSpeech,
): {
  renderer: "text-tile";
  props: { letter: string; className: string; style: React.CSSProperties };
} => {
  return {
    renderer: "text-tile",
    props: { letter, className: WORD_TYPE_CLASSNAME[type], style: {} },
  };
};

