export type AnyLevel = Level<
  AllLevelsAvailableSlots,
  AllLevelsAvailableTiles,
  HexId
>;

type AnyTileRendererProps = {
  id: string;
  levelId: string;
  isInActiveLevel: boolean;
};

export type IndicatorData = {
  type: AllLevelsAvailableIndicators;
  indicatorProps: Record<string, unknown>;
};

export type SubmissionData = {
  puzzleSlug: string;
};

export function AnyTileContentRenderer(props: AnyTileRendererProps) {
  const levelToTileIdToDefinitionMap = useClientState(
    (state) => state.levelToTileIdToDefinitionMap,
  );

  const tileDefinition = levelToTileIdToDefinitionMap
    .get(props.levelId)
    ?.get(props.id);
  if (!tileDefinition) {
    return null;
  }
  const Renderer = tileRegistry[tileDefinition.renderer];
  if (!Renderer) {
    return null;
  }
  const rendererProps = {
    ...tileDefinition.props,
    isInActiveLevel: props.isInActiveLevel,
  };
  return <Renderer {...rendererProps} />;
}

type AnySlotRendererProps = {
  id: AllLevelsAvailableSlots;
  slotProps: Record<string, unknown>;
};

export function AnySlotContentRenderer(props: AnySlotRendererProps) {
  const Renderer = allRegionAvailableSlots[props.id].renderer;
  if (!Renderer) {
    return null;
  }
  return <Renderer {...props.slotProps} />;
}

type AnyIndicatorRendererProps = {
  id: AllLevelsAvailableIndicators | undefined;
  indicatorProps: Record<string, unknown>;
};

export function AnyIndicatorContentRenderer(props: AnyIndicatorRendererProps) {
  if (!props.id) {
    return null;
  }
  const Renderer = allRegionAvailableIndicators[props.id].renderer;
  if (!Renderer) {
    return null;
  }
  return <Renderer {...props.indicatorProps} />;
}
