import { type LevelDisplay } from "@hunt/frontend-client";
import { parseId, type HexId } from "../basic-hexagons/bounding-box";
import { type Polygon } from "../basic-hexagons/svg-effects";
import { axialToXY, oddrToAxial } from "../levels/utilities";
import { type LevelHatching } from "./client-state";

export function createDysonHatching(
  level: HexId[],
  hexCenters: HexId[],
  origin: HexId,
  hexSize: number,
): LevelHatching {
  if (hexCenters.length === 0) {
    return { svgString: "<svg/>", offsetX: 0, offsetY: 0, origin };
  }

  const axialHexes = hexCenters.map(oddrToAxial);
  // Toss out level hexes that are too far away from the region we're generating hatching in.
  const levelAxialHexes = new Set(
    level.map(oddrToAxial).filter((hexId) => {
      const { q, r } = parseId(hexId);
      for (const otherHexId of axialHexes) {
        const { q: q_, r: r_ } = parseId(otherHexId);
        if (Math.abs(q - q_) + Math.abs(r - r_) <= 2) {
          return true;
        }
      }
      return false;
    }),
  );

  let minX = 1e9;
  let maxX = -1e9;
  let minY = 1e9;
  let maxY = -1e9;

  const xyHexCenters = axialHexes.map((id) => {
    const { q, r } = parseId(id);
    const [x, y] = axialToXY(q, r, hexSize);
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y);
    return [x, y];
  });

  // Next do Poisson disc sampling to get the hatch centers.
  function isPointInHexes(x: number, y: number): boolean {
    for (const [cx, cy] of xyHexCenters) {
      const dx = x - cx;
      const dy = y - cy;
      const dist = Math.sqrt(dx * dx + dy * dy);
      // Check if point is within the hex radius
      if (dist <= hexSize / 2) {
        return true;
      }
    }
    return false;
  }

  const minDist = hexSize / 8;
  // Number of attempts without forward progress before we stop.
  const stopThreshold = 200;
  let noProgressIterations = 0; // Keeps track of how many iterations have passed without forward progress
  let maxNumberPoints = 0; // Use maxNumberPoints to keep track of the max length of sampledCenters so far. Each iterations that fails to increase this updates the number of iterations without forward progress.
  const spatialGridSize = 32;
  const sampledCenters: Record<string, [number, number][]> = {}; // sampledCenters split up as a spatial grid for efficiency.
  const activeList: [number, number][] = [];

  function gridKey(x: number, y: number) {
    return `${Math.floor(x / spatialGridSize)},${Math.floor(y / spatialGridSize)}`;
  }

  // Initialize centers as hex centers
  axialHexes.forEach((id) => {
    const { q, r } = parseId(id);
    const [x, y] = axialToXY(q, r, hexSize);
    const key = gridKey(x, y);
    if (sampledCenters[key] === undefined) {
      sampledCenters[key] = [];
    }
    sampledCenters[key].push([x, y]);
    activeList.push([x, y]);
    maxNumberPoints++;
  });

  minX -= hexSize;
  maxX += hexSize;
  minY -= hexSize;
  maxY += hexSize;

  while (noProgressIterations < stopThreshold) {
    // Pick a random point from the active list
    const randomIndex = Math.floor(Math.random() * activeList.length);
    const [px, py] = activeList[randomIndex];

    let foundNewPoint = false;

    // Try to generate k points around this point
    const k = 10;
    for (let i = 0; i < k; i++) {
      // Generate a point at random angle and distance between minDist and 2*minDist
      let angle = Math.random() * 2 * Math.PI;
      let radius = minDist + Math.random() * minDist;
      let newX = px + radius * Math.cos(angle);
      let newY = py + radius * Math.sin(angle);
      while (
        newX < minX ||
        newX > maxX ||
        newY < minY ||
        newY > maxY ||
        !isPointInHexes(newX, newY)
      ) {
        angle = Math.random() * 2 * Math.PI;
        radius = minDist + Math.random() * minDist;
        newX = px + radius * Math.cos(angle);
        newY = py + radius * Math.sin(angle);
      }
      const key = gridKey(newX, newY);

      // Check if the new point is far enough from all existing points
      const [kx, ky] = [
        Math.floor(newX / spatialGridSize),
        Math.floor(newY / spatialGridSize),
      ];
      if (sampledCenters[key] === undefined) {
        sampledCenters[key] = [];
      }
      let tooClose = false;
      for (let dkx = -1; dkx <= 1; dkx++) {
        for (let dky = -1; dky <= 1; dky++) {
          const testKey = `${kx + dkx},${ky + dky}`;
          if (sampledCenters[testKey] === undefined) {
            continue;
          }

          for (const [sx, sy] of sampledCenters[testKey]) {
            const dx = newX - sx;
            const dy = newY - sy;
            const dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < minDist) {
              // console.log(
              //   "Too close!",
              //   sx,
              //   sy,
              //   newX,
              //   newY,
              //   sampledCenters,
              //   testKey,
              //   noProgressIterations,
              // );
              tooClose = true;
              break;
            }
          }
        }
      }

      if (!tooClose) {
        // console.log("tooClose!", activeList.length);
        sampledCenters[key].push([newX, newY]);
        activeList.push([newX, newY]);
        foundNewPoint = true;
        break;
      }
    }

    if (!foundNewPoint && activeList.length > 1) {
      // Remove this point from the active list
      activeList.splice(randomIndex, 1);
      // Remove it from sampled centers also
      const otherKey = gridKey(px, py);
      sampledCenters[otherKey] = sampledCenters[otherKey].filter(
        ([x, y]) => !(x === px && y === py),
      );
    }

    // Track progress
    if (activeList.length > maxNumberPoints) {
      maxNumberPoints = activeList.length;
      noProgressIterations = 0;
    } else {
      noProgressIterations++;
    }
  }

  // Finally, for each center, randomize angle, length, and gap size. Generate 3 parallel lines with the parameters.
  const { q: originQ, r: originR } = parseId(oddrToAxial(origin));
  const [originX, originY] = axialToXY(originQ, originR, hexSize);

  // Helper function to calculate distance from a point to the nearest hex in levelAxialHexes
  const levelHexCenters = Array.from(levelAxialHexes).map((id) => {
    const { q, r } = parseId(id);
    return axialToXY(q, r, hexSize);
  });

  function getDistanceToNearestLevelHex(x: number, y: number): number {
    let minDist = Infinity;
    for (const [hx, hy] of levelHexCenters) {
      const dx = x - hx;
      const dy = y - hy;
      const dist = Math.sqrt(dx * dx + dy * dy) - hexSize / 2; // Distance from hex edge
      minDist = Math.min(minDist, dist);
    }
    return Math.max(0, minDist); // Clamp to 0 minimum
  }

  function calculateOpacity(x: number, y: number): number {
    const maxDist = (hexSize * Math.sqrt(3)) / 2;
    const dist = getDistanceToNearestLevelHex(x, y);
    if (dist <= 4) return 0.0; // Inside a level hex
    if (dist >= maxDist) return 0.0; // Too far away
    return 0.4 * Math.pow(1.0 - dist / maxDist, 2); // Quadratically decreasing
  }

  // Generate individual line elements with opacity based on distance
  let lineElements = "";
  for (const [cx, cy] of activeList) {
    // Randomize parameters for this hatch
    const angle = Math.random() * Math.PI; // 0 to 180 degrees
    const lineLength = minDist * (1.1 + 0.2 * (Math.random() - 0.5));
    const gapSize = minDist * (0.25 + 0.05 * Math.random());

    // Direction vector for the lines
    const dx = Math.cos(angle);
    const dy = Math.sin(angle);

    // Perpendicular direction for spacing lines
    const perpDx = -Math.sin(angle);
    const perpDy = Math.cos(angle);

    // Generate 3 parallel lines
    for (let i = -1; i <= 1; i++) {
      const offsetX = perpDx * gapSize * i;
      const offsetY = perpDy * gapSize * i;

      const x1 = cx + offsetX - (dx * lineLength) / 2;
      const y1 = cy + offsetY - (dy * lineLength) / 2;
      const x2 = cx + offsetX + (dx * lineLength) / 2;
      const y2 = cy + offsetY + (dy * lineLength) / 2;

      // Calculate opacity at the midpoint of the line
      const midX = (x1 + x2) / 2;
      const midY = (y1 + y2) / 2;
      const opacity = calculateOpacity(midX, midY);

      // Only add lines with non-zero opacity
      if (opacity > 0.01) {
        // Create a polygon with two points for the line
        const linePolygon: Polygon = [
          { x: x1 - originX, y: y1 - originY },
          { x: x2 - originX, y: y2 - originY },
        ];

        minX = Math.min(x1, x2, minX);
        maxX = Math.max(x1, x2, maxX);
        minY = Math.min(y1, y2, minY);
        maxY = Math.max(y1, y2, maxY);

        const pathData = `M ${linePolygon[0].x} ${linePolygon[0].y} L ${linePolygon[1].x} ${linePolygon[1].y}`;
        lineElements += `<path d="${pathData}" fill="none" stroke="black" stroke-width="1" stroke-opacity="${opacity.toFixed(3)}" />`;
      }
    }
  }

  const padding = 100;
  const viewMinX = minX - originX - padding;
  const viewMinY = minY - originY - padding;
  const viewMaxX = maxX - originX + padding;
  const viewMaxY = maxY - originY + padding;

  const svgString = `
  <svg viewBox="${viewMinX} ${viewMinY} ${viewMaxX - viewMinX} ${viewMaxY - viewMinY}" width="${viewMaxX - viewMinX}" height="${viewMaxY - viewMinY}" xmlns="http://www.w3.org/2000/svg">
  ${lineElements}
  </svg>
  `;

  const offsetX = viewMinX;
  const offsetY = viewMinY;
  return { svgString, offsetX, offsetY, origin };
}

export function createLevelHatching(
  levels: Record<string, LevelDisplay>,
  hexSize: number,
): Map<string, LevelHatching> {
  const hatchings = new Map<string, LevelHatching>();

  const unlockedSlots = new Set<HexId>();
  for (const levelDisplay of Object.values(levels)) {
    for (const slot of Object.keys(levelDisplay.level)) {
      unlockedSlots.add(slot as HexId);
    }
  }

  for (const [levelId, levelDisplay] of Object.entries(levels)) {
    const adjacentSlots = new Set<HexId>(
      levelDisplay.fogOfWarHexes as Iterable<HexId>,
    );

    const hatching = createDysonHatching(
      Array.from(unlockedSlots),
      Array.from(adjacentSlots.difference(unlockedSlots)),
      "0,0",
      hexSize,
    );
    hatchings.set(levelId, hatching);

    if (levelId.startsWith("imaginative")) {
      console.log(levelId, hatching);
    }
  }

  return hatchings;
}
