import { useEffect, useRef } from "react";
import { createRegionBuilder } from "../../../levels/types";
import FRAMES from "./assets/frames.json";
import ATLAS from "./assets/optimized_atlas.png";

const startTime = Date.now();
const FPS = 90;

export function AnimationContent({
  idx,
  isInActiveLevel,
}: {
  idx: number;
  isInActiveLevel: boolean;
}) {
  const divRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isInActiveLevel) {
      return;
    }

    let animationId: number;
    let frame = 0;

    const animate = () => {
      const time = Date.now();
      const nextFrame = Math.floor(((time - startTime) / 1000) * FPS) % 720;
      if (nextFrame !== frame) {
        frame = nextFrame;
        const atlasIdx = (FRAMES as number[][])[idx][frame];
        const left = atlasIdx % 53;
        const top = Math.floor(atlasIdx / 53);
        const backgroundPosition = `${-left * 120}px ${-top * 120}px`;
        if (divRef.current) {
          divRef.current.style.backgroundPosition = backgroundPosition;
        }
      }

      animationId = requestAnimationFrame(animate);
    };

    animationId = requestAnimationFrame(animate);

    return () => {
      cancelAnimationFrame(animationId);
    };
  }, [idx, isInActiveLevel]);

  return (
    <div
      ref={divRef}
      style={{
        backgroundImage: `url(${ATLAS})`,
        backgroundSize: "6360px 15000px",
        position: "relative",
        left: "-8.04px",
        top: "0px",
        width: "120px",
        height: "120px",
      }}
    />
  );
}

export const jigsawRegion = createRegionBuilder()
  .addSlotType("empty-slot-aromatic-stock", null)
  .build();

export type JigsawAvailableSlots = keyof typeof jigsawRegion.slots;
export type JigsawAvailableTiles = keyof typeof jigsawRegion.tiles;
