import { SimpleSlot } from "../../../levels/component-utilities";
import { createRegionBuilder } from "../../../levels/types";
import { useClientState } from "../../client-state";
import { type GlyphTileProps, COLORS } from "./glyphs";

export function getTileKey(props: GlyphTileProps) {
  if (props.radical_type === "Junction") {
    return `glyph-Junction-${props.word_number}`;
  }
  if (props.radical_type === "Number") {
    return `glyph-Number-${props.shape}-${props.word_number}`;
  }
  return `glyph-Word-${props.shape}-${props.radical_number}-${props.word_number}`;
}

const BaseGlyphTile = (props: {
  image: string | undefined;
  tileKey: string;
  className?: string;
}) => {
  const tileText = useClientState((state) =>
    state.tileIdToTileTextMap.has(props.tileKey)
      ? state.tileIdToTileTextMap.get(props.tileKey)
      : undefined,
  );
  const setTileText = useClientState((state) => state.setTileText);
  return (
    <div className={`relative bg-yellow-100 ${props.className ?? ""}`}>
      <img
        src={props.image}
        alt="Glyph"
        className="opacity-70"
        draggable="false"
      />
      <input
        type="text"
        value={tileText === undefined ? "" : tileText}
        onChange={(e) => {
          setTileText(props.tileKey, e.target.value);
        }}
        onKeyDownCapture={(e) => {
          e.stopPropagation();
        }}
        style={{
          backgroundColor: "transparent",
          position: "absolute",
          top: "80%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          color: tileText === undefined ? "#00000080" : "#000000",
          width: "80%",
          textAlign: "center",
          fontSize: "14px",
        }}
      ></input>
    </div>
  );
};

export const GlyphTile = (props: GlyphTileProps) => {
  const tileKey = getTileKey(props);
  return <BaseGlyphTile image={props.image} tileKey={tileKey} />;
};

export const GlyphPronounTile = (
  props: GlyphTileProps & { colorIndex: number },
) => {
  const tileKey = getTileKey(props);
  return (
    <BaseGlyphTile
      image={props.image}
      tileKey={tileKey}
      className={COLORS[props.colorIndex]}
    />
  );
};

const danceOfTheBumblebeeRegionBuilder = createRegionBuilder().addSlotType(
  "empty-glyph-slot",
  null,
);

for (let i = 0; i < COLORS.length; i++) {
  danceOfTheBumblebeeRegionBuilder.addSlotType(`pronoun-slot-${i}`, () => (
    <SimpleSlot className={COLORS[i]} />
  ));
}

export const danceOfTheBumblebeeRegion =
  danceOfTheBumblebeeRegionBuilder.build();
export type DanceOfTheBumblebeeAvailableSlots =
  keyof typeof danceOfTheBumblebeeRegion.slots;
export type DanceOfTheBumblebeeAvailableTiles =
  keyof typeof danceOfTheBumblebeeRegion.tiles;
export type DanceOfTheBumblebeeAvailableIndicators =
  keyof typeof danceOfTheBumblebeeRegion.indicators;
