import { createLevelBuilder } from "../../../levels/types";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import solutionK from "./assets/K/solution.json";
import {
  type worthwhileSuitAvailableIndicators,
  type worthwhileSuitAvailableSlots,
  type worthwhileSuitAvailableTileGroups,
} from "./client";
import { REGION_FLAVORTEXT } from "./constants";

const allCoords = [
  "-21,-21",
  "-20,-21",
  "-19,-21",
  "-18,-21",
  "-17,-21",
  "-16,-21",
  "-20,-20",
  "-19,-20",
  "-18,-20",
  "-17,-20",
  "-16,-20",
  "-15,-20",
  "-14,-20",
  "-20,-19",
  "-19,-19",
  "-18,-19",
  "-17,-19",
  "-16,-19",
  "-15,-19",
  "-19,-18",
  "-18,-18",
  "-15,-18",
  "-14,-18",
  "-15,-17",
] as const;

type LevelKCoord = (typeof allCoords)[number];

const slotConfigs: Record<LevelKCoord, { color: string; clues?: string[] }> = {
  "-21,-21": {
    color: "#F79015",
    clues: ['↘ Eldest "brother" in the "Foundation" series'],
  },
  "-20,-21": { color: "#67CD95" },
  "-19,-21": { color: "#6B4D82" },
  "-18,-21": { color: "#548CD0" },
  "-17,-21": {
    color: "#FFB2E7",
    clues: [
      "← Mistreat, as in some college rituals",
      "↙ Alpert who founded A&M Records",
    ],
  },
  "-16,-21": { color: "#8F482F" },
  "-20,-20": { color: "#DF9ACA" },
  "-19,-20": { color: "#FFFF65" },
  "-18,-20": { color: "#E74F00" },
  "-17,-20": { color: "#F3F3F3" },
  "-16,-20": { color: "#FF8021" },
  "-15,-20": { color: "#94DDCB" },
  "-14,-20": {
    color: "#BF3F3F",
    clues: [
      '← Devastating spell Sephiroth intends to unleash in "Final Fantasy VII"',
    ],
  },
  "-20,-19": { color: "#9F3434" },
  "-19,-19": { color: "#A43482" },
  "-18,-19": { color: "#5F7B4A" },
  "-17,-19": { color: "#9F9F9F" },
  "-16,-19": {
    color: "#62C9D3",
    clues: ["← Browses, as the internet, in 90's parlance"],
  },
  "-15,-19": { color: "#3A3A3A" },
  "-19,-18": { color: "#FF6137" },
  "-18,-18": { color: "#3C32CD" },
  "-15,-18": { color: "#FFD966" },
  "-14,-18": {
    color: "#4F2CD0",
    clues: ["↖ Binary ___ (basic data structure)"],
  },
  "-15,-17": { color: "#C4EA7F", clues: ["↖ Verve or enthusiasm"] },
} satisfies Record<LevelKCoord, { color: string; clues?: string[] }>;

const levelKLetterTiles: Record<string, string> = Object.fromEntries(
  "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map((letter) => [letter, letter]),
);

const slotPropsFor = (coord: LevelKCoord) => ({
  style: { backgroundColor: slotConfigs[coord].color },
});

const levelKBuilder = createLevelBuilder<
  worthwhileSuitAvailableSlots,
  AllAvailableTiles,
  worthwhileSuitAvailableIndicators,
  worthwhileSuitAvailableTileGroups
>()
  .setFlavorText(REGION_FLAVORTEXT)
  .setTitle("Collection of Pearls")
  .setLevelFlavorText(
    "To befriend cartoon characters, let's draw with wax pencils instead of watching diagnostic TV broadcasts.",
  )
  .addSlot("-21,-21", "worthwhile-suit-empty-slot", slotPropsFor("-21,-21"))
  .addSlot("-20,-21", "worthwhile-suit-empty-slot", slotPropsFor("-20,-21"))
  .addSlot("-19,-21", "worthwhile-suit-empty-slot", slotPropsFor("-19,-21"))
  .addSlot("-18,-21", "worthwhile-suit-empty-slot", slotPropsFor("-18,-21"))
  .addSlot("-17,-21", "worthwhile-suit-empty-slot", slotPropsFor("-17,-21"))
  .addSlot("-16,-21", "worthwhile-suit-empty-slot", slotPropsFor("-16,-21"))
  .addSlot("-20,-20", "worthwhile-suit-empty-slot", slotPropsFor("-20,-20"))
  .addSlot("-19,-20", "worthwhile-suit-empty-slot", slotPropsFor("-19,-20"))
  .addSlot("-18,-20", "worthwhile-suit-empty-slot", slotPropsFor("-18,-20"))
  .addSlot("-17,-20", "worthwhile-suit-empty-slot", slotPropsFor("-17,-20"))
  .addSlot("-16,-20", "worthwhile-suit-empty-slot", slotPropsFor("-16,-20"))
  .addSlot("-15,-20", "worthwhile-suit-empty-slot", slotPropsFor("-15,-20"))
  .addSlot("-14,-20", "worthwhile-suit-empty-slot", slotPropsFor("-14,-20"))
  .addSlot("-20,-19", "worthwhile-suit-empty-slot", slotPropsFor("-20,-19"))
  .addSlot("-19,-19", "worthwhile-suit-empty-slot", slotPropsFor("-19,-19"))
  .addSlot("-18,-19", "worthwhile-suit-empty-slot", slotPropsFor("-18,-19"))
  .addSlot("-17,-19", "worthwhile-suit-empty-slot", slotPropsFor("-17,-19"))
  .addSlot("-16,-19", "worthwhile-suit-empty-slot", slotPropsFor("-16,-19"))
  .addSlot("-15,-19", "worthwhile-suit-empty-slot", slotPropsFor("-15,-19"))
  .addSlot("-19,-18", "worthwhile-suit-empty-slot", slotPropsFor("-19,-18"))
  .addSlot("-18,-18", "worthwhile-suit-empty-slot", slotPropsFor("-18,-18"))
  .addSlot("-15,-18", "worthwhile-suit-empty-slot", slotPropsFor("-15,-18"))
  .addSlot("-14,-18", "worthwhile-suit-empty-slot", slotPropsFor("-14,-18"))
  .addSlot("-15,-17", "worthwhile-suit-empty-slot", slotPropsFor("-15,-17"))
  .addIndicator("-21,-21", "worthwhile-suit-chevron-indicator", {
    upper: "dr",
  })
  .addIndicator("-17,-21", "worthwhile-suit-chevron-indicator", {
    upper: "l",
    lower: "dl",
  })
  .addIndicator("-14,-20", "worthwhile-suit-chevron-indicator", {
    upper: "l",
  })
  .addIndicator("-16,-19", "worthwhile-suit-chevron-indicator", {
    upper: "l",
  })
  .addIndicator("-14,-18", "worthwhile-suit-chevron-indicator", {
    upper: "ul",
  })
  .addIndicator("-15,-17", "worthwhile-suit-chevron-indicator", {
    upper: "ul",
  });

allCoords.forEach((coord) => {
  const clues = slotConfigs[coord].clues;
  if (!clues?.length) return;
  levelKBuilder.addClues(
    coord,
    clues.map((clue) => ({ type: "text", text: clue })),
  );
});

levelKBuilder.setSolution(solutionK);

const letterTileGroup: worthwhileSuitAvailableTileGroups =
  "worthwhile-suit-K-letter-group";

Object.entries(levelKLetterTiles).forEach(([key, text]) => {
  levelKBuilder.addTileToBank(
    `${key}-tile`,
    3000,
    {
      renderer: "worthwhile-suit-K-tile",
      props: {
        letter: text,
      },
    },
    letterTileGroup,
  );
});

export const levelK = levelKBuilder.build();
