// Stuff in this file will pretty likely be sent to the client, be aware
import { cn } from "@hunt/styled-ui";
import {
  ColorContent,
  EmojiContent,
  LetterContent,
  SubmissionSlot,
} from "../../../levels/component-utilities";
import { createRegionBuilder } from "../../../levels/types";
import StarImage from "./assets/star.png";

type IndicatorContent = {
  upper?: "ur" | "r" | "dr" | "dl" | "l" | "ul";
  lower?: "ur" | "r" | "dr" | "dl" | "l" | "ul";
  star?: boolean;
  image?: string;
};

function Indicator(props: IndicatorContent) {
  return (
    <div
      className={cn("h-full w-full", {
        "indicator chevron": props.upper,
        "rot-1": props.upper === "dr",
        "rot-2": props.upper === "dl",
        "rot-3": props.upper === "l",
        "rot-4": props.upper === "ul",
        "rot-5": props.upper === "ur",
        "rot-6": props.upper === "r",
        "indicator lower-chevron": props.lower,
        "lower-rot-1": props.lower === "dr",
        "lower-rot-2": props.lower === "dl",
        "lower-rot-3": props.lower === "l",
        "lower-rot-4": props.lower === "ul",
        "lower-rot-5": props.lower === "ur",
        "lower-rot-6": props.lower === "r",
      })}
    >
      {props.star && (
        <img className="w-full" src={StarImage} alt="arrow with a bend in it" />
      )}
    </div>
  );
}

function ImageIndicator(props: { image: string }) {
  return (
    <div className={cn("h-full w-full")}>
      <img className="w-full" src={props.image} alt="" />
    </div>
  );
}

export const crosswordRegion = createRegionBuilder()
  .addSlotType("empty-slot-winding-snowman", null)
  .addSlotType("indicator-slot", Indicator as React.FC<Record<string, unknown>>)
  .addIndicatorType("indicator", Indicator as React.FC<Record<string, unknown>>)
  .addIndicatorType(
    "image-indicator",
    ImageIndicator as React.FC<Record<string, unknown>>,
  )
  .addSlotType(
    "submission-slot",
    SubmissionSlot as React.FC<Record<string, unknown>>,
  )
  .addTileType("text-tile", (props: Record<string, unknown>) => {
    const letter = props.letter as string; // has type unknown
    if (typeof letter === "string") {
      return <LetterContent letter={letter} />;
    }
    return null;
  })
  .addTileType("color-tile", (props: Record<string, unknown>) => {
    const color = props.color as string; // has type unknown
    const border = typeof props.border === "boolean" ? props.border : false; // has type unknown
    if (typeof color === "string") {
      return <ColorContent color={color} border={border} />;
    }
    return null;
  })
  .addTileType("card-tile", (props: Record<string, unknown>) => {
    const card = props.card as string; // has type unknown
    if (typeof card === "string") {
      return <LetterContent letter={card} />;
    }
    return null;
  })
  .addTileType("emoji-tile", (props: Record<string, unknown>) => {
    const emoji = props.emoji as string; // has type unknown
    if (typeof emoji === "string") {
      return <EmojiContent emoji={emoji} />;
    }
    return null;
  })
  .build();

export type CrosswordAvailableSlots = keyof typeof crosswordRegion.slots;
export type CrosswordAvailableTiles = keyof typeof crosswordRegion.tiles;
export type CrosswordAvailableIndicators =
  keyof typeof crosswordRegion.indicators;
