import { createLevelBuilder } from "../../../levels/types";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import solutionB from "./assets/B/solution.json";
import { type worthwhileSuitAvailableSlots } from "./client";
import { REGION_FLAVORTEXT } from "./constants";

type WorthwhileSuitBTileConfig = {
  topLeft?: string;
  topRight?: string;
  right?: string;
  bottomRight?: string;
  bottomLeft?: string;
  left?: string;
};

const levelBTiles: WorthwhileSuitBTileConfig[] = [
  { topRight: "AGENDA", left: "PALACE" },
  { left: "ANTERIOR", right: "OKAPI" },
  { topLeft: "BRIDLE", bottomRight: "DEVOUT" },
  { left: "ENTROPY", right: "ANNEX" },
  { topLeft: "FULCRUM", topRight: "CARDIFF" },
  { topLeft: "LETTER" },
  { right: "MOLLUSC", bottomLeft: "ERRATUM" },
  { left: "NETTLE", bottomRight: "FLASHY" },
  { left: "ONSIDE", bottomLeft: "INCLINE" },
  { topLeft: "ORANGE", bottomRight: "STRAW" },
  { left: "PATTERN", right: "BOTHER" },
  { right: "ROWBOAT", bottomRight: "ARTIFACT" },
  { left: "SPONSOR", right: "WORKSHOP" },
  { right: "SUBTEXT" },
];

const levelBBuilder = createLevelBuilder<
  worthwhileSuitAvailableSlots,
  AllAvailableTiles
>()
  .setFlavorText(REGION_FLAVORTEXT)
  .setTitle("The Poet in You")
  .setLevelFlavorText(
    "The next step in your taxonomic research requires advancing to a higher level of education. Dr. Tedd agrees progressing with these words may help.",
  )
  .addSlot("-26,-30", "worthwhile-suit-empty-slot")
  .addSlot("-25,-30", "worthwhile-suit-empty-slot")
  .addSlot("-24,-30", "worthwhile-suit-empty-slot")
  .addSlot("-23,-30", "worthwhile-suit-empty-slot")
  .addSlot("-26,-29", "worthwhile-suit-empty-slot")
  .addSlot("-24,-29", "worthwhile-suit-empty-slot")
  .addSlot("-25,-29", "worthwhile-suit-empty-slot")
  .addSlot("-25,-28", "worthwhile-suit-empty-slot")
  .addSlot("-24,-28", "worthwhile-suit-empty-slot")
  .addSlot("-23,-28", "worthwhile-suit-empty-slot")
  .addSlot("-22,-28", "worthwhile-suit-empty-slot")
  .addSlot("-25,-27", "worthwhile-suit-empty-slot")
  .addSlot("-22,-27", "worthwhile-suit-empty-slot")
  .addSlot("-21,-26", "worthwhile-suit-empty-slot")
  // Preplaced tiles
  .addGivenTile("-25,-27", {
    renderer: "worthwhile-suit-B-tile",
    props: levelBTiles[4],
  })
  .addGivenTile("-22,-27", {
    renderer: "worthwhile-suit-B-tile",
    props: levelBTiles[2],
  })
  .setSolution(solutionB);

levelBTiles.forEach((tileConfig, ind) => {
  if (ind === 2 || ind === 4) {
    return;
  }
  levelBBuilder.addTileToBank(`tile-${ind + 1}`, 1, {
    renderer: "worthwhile-suit-B-tile",
    props: tileConfig,
  });
});

export const levelB = levelBBuilder.build();
