export const TO_GACHA_UUID: Record<string, string> = dontLeakThis(
  Object.entries(HARDCODED_UUID_MAP).reduce<Record<string, string>>(
    (acc, [human_id, uuid]) => {
      // Default to UUIDs everywhere; only use HRIDs when explicitly requested.
      if (
        typeof process !== "undefined" &&
        process.env.USE_CLUE_HRIDS === "true"
      ) {
        acc[human_id] = human_id;
      } else {
        acc[human_id] = uuid;
      }
      return acc;
    },
    {},
  ),
);

export const FROM_GACHA_UUID: Record<string, string> = dontLeakThis(
  Object.entries(TO_GACHA_UUID).reduce<Record<string, string>>(
    (acc, [human_id, uuid]) => {
      acc[uuid] = human_id;
      return acc;
    },
    {},
  ),
);
