import { type LevelDisplay } from "@hunt/frontend-client";
import { useMemo } from "react";

export type Regions = Record<string, { bounds: BoundingBox[] }>;

export type HexCoordinates = {
  q: number;
  r: number;
};

export type HexId = `${number},${number}`;

export function createId(q: number, r: number): HexId {
  return `${q},${r}`;
}

export function parseId(id: HexId): HexCoordinates {
  const [q, r] = id.split(",");
  return { q: parseInt(q), r: parseInt(r) };
}

export type BoundingBox = {
  q: number;
  r: [number, number];
};

export type MapLimits = {
  minQ: number;
  maxQ: number;
  minR: number;
  maxR: number;
};

const MAP_LIMITS_PADDING = 6;

export const useMapLimits = (
  regions: Record<string, LevelDisplay>,
): MapLimits => {
  return useMemo(() => {
    const allCoordinates = Object.values(regions).flatMap((level) =>
      Object.keys(level.level).map((hexId) => parseId(hexId as HexId)),
    );

    if (allCoordinates.length === 0) {
      return { minQ: 0, maxQ: 0, minR: 0, maxR: 0 };
    }

    const minQ =
      Math.min(...allCoordinates.map((coord) => coord.q)) - MAP_LIMITS_PADDING;
    const maxQ =
      Math.max(...allCoordinates.map((coord) => coord.q)) + MAP_LIMITS_PADDING;
    const minR =
      Math.min(...allCoordinates.map((coord) => coord.r)) - MAP_LIMITS_PADDING;
    const maxR =
      Math.max(...allCoordinates.map((coord) => coord.r)) + MAP_LIMITS_PADDING;

    // To simplify parity issues in rendering, we **always** assume minR is even.
    return { minQ, maxQ, minR: minR - (Math.abs(minR) % 2), maxR };
  }, [regions]);
};

export function limitsToCoordinates(
  minQ: number,
  maxQ: number,
  minR: number,
  maxR: number,
): HexCoordinates[] {
  const coordinates: HexCoordinates[] = [];
  for (let q = minQ; q <= maxQ; q++) {
    for (let r = minR; r <= maxR; r++) {
      coordinates.push({ q, r });
    }
  }
  return coordinates;
}
