import { FINAL_LEVEL_UNLOCK_DEFINITIONS } from "../../../levels/final-level-unlock-definitions";
import { createLevelBuilder, createMapBuilder } from "../../../levels/types";
import { createFinalLevelUnlockTransform } from "../../../levels/utilities";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import { type imaginativeForceAvailableSlots } from "./client";
import { levelA } from "./level-a";
import { levelB } from "./level-b";
import { levelC } from "./level-c";
import { levelD } from "./level-d";
import { levelE } from "./level-e";

const finalLevelUnlockTransform = createFinalLevelUnlockTransform(
  "imaginative-force-B-empty-slot",
  "doubles_games",
  FINAL_LEVEL_UNLOCK_DEFINITIONS.doubles_games,
);
const submissionLevelBuilder = createLevelBuilder<
  imaginativeForceAvailableSlots,
  AllAvailableTiles
>()
  .addSlot("-20,-4", "imaginative-force-B-empty-slot", {})
  .addSubmission({
    hexId: "-20,-4",
    puzzleSlug: "doubles_games",
  })
  .addUnlockTransform(finalLevelUnlockTransform);

export const imaginativeForceLevels = createMapBuilder()
  .setTitle("Doubles Games")
  .addLevel("imaginative-force-level-a", levelA)
  .addLevel("imaginative-force-level-b", levelB)
  .addLevel("imaginative-force-level-c", levelC)
  .addLevel("imaginative-force-level-d", levelD)
  .addLevel("imaginative-force-level-e", levelE)
  .addLevel(
    "submission-imaginative-force-level",
    submissionLevelBuilder.build(),
  )
  .build();
