// Client definitions for the Heatmaps level
import hm1 from "./assets/heat_maps/hm1.png";
import hm10 from "./assets/heat_maps/hm10.png";
import hm11 from "./assets/heat_maps/hm11.png";
import hm12 from "./assets/heat_maps/hm12.png";
import hm13 from "./assets/heat_maps/hm13.png";
import hm14 from "./assets/heat_maps/hm14.png";
import hm15 from "./assets/heat_maps/hm15.png";
import hm16 from "./assets/heat_maps/hm16.png";
import hm2 from "./assets/heat_maps/hm2.png";
import hm3 from "./assets/heat_maps/hm3.png";
import hm4 from "./assets/heat_maps/hm4.png";
import hm5 from "./assets/heat_maps/hm5.png";
import hm6 from "./assets/heat_maps/hm6.png";
import hm7 from "./assets/heat_maps/hm7.png";
import hm8 from "./assets/heat_maps/hm8.png";
import hm9 from "./assets/heat_maps/hm9.png";
import type { MysteryTileEntry } from "./types";

const HEATMAP_TILES = [
  hm1,
  hm2,
  hm3,
  hm4,
  hm5,
  hm6,
  hm7,
  hm8,
  hm9,
  hm10,
  hm11,
  hm12,
  hm13,
  hm14,
  hm15,
  hm16,
];

export const HEATMAP_TILE_COUNT = HEATMAP_TILES.length;

const HeatmapTile = ({ idx }: { idx: number }) => (
  <div>
    <img
      src={HEATMAP_TILES[idx]}
      alt={`Heatmap tile ${idx + 1}`}
      draggable="false"
    />
  </div>
);

export const MysteryNumberIndicator = (props: Record<string, unknown>) => {
  const text = props.text as string | undefined;
  if (!text) {
    return null;
  }

  return (
    <div className="w-full h-full flex flex-row items-start justify-center pointer-events-none">
      <span className="text-red-500 text-sm font-bold mt-[10%]">{text}</span>
    </div>
  );
};

export const heatmapRegistryEntries = Array.from(
  { length: HEATMAP_TILE_COUNT },
  (_, idx) =>
    [
      `mystery-heatmap-${idx + 1}-tile`,
      (_props: Record<string, unknown>) => <HeatmapTile idx={idx} />,
    ] as const,
) satisfies readonly MysteryTileEntry[];
