export const Border = ({ border }: { border: number }) => {
  const borders = [
    (border & 1) !== 0,
    (border & 2) !== 0,
    (border & 4) !== 0,
    (border & 8) !== 0,
    (border & 16) !== 0,
    (border & 32) !== 0,
  ];
  const width = 107.38715;
  const height = 124;
  const scale = height / 2;
  const borderThickness = 10;
  return (
    <svg
      className="absolute left-0 top-0"
      width="100%"
      height="100%"
      viewBox={`0 0 ${width} ${height}`}
    >
      {borders.map((border, i) => {
        if (!border) {
          return null;
        }
        const startAngle = (i * Math.PI) / 3 + Math.PI / 2;
        const endAngle = ((i + 1) * Math.PI) / 3 + Math.PI / 2;
        const sx = Math.cos(startAngle) * scale + width / 2;
        const sy = Math.sin(startAngle) * scale + height / 2;
        const ex = Math.cos(endAngle) * scale + width / 2;
        const ey = Math.sin(endAngle) * scale + height / 2;
        return (
          <path
            d={`M${sx} ${sy} L${ex} ${ey}`}
            stroke="black"
            strokeWidth={borderThickness}
            key={i}
          />
        );
      })}
    </svg>
  );
};

type ConsiderateMoonSlotProps = {
  color: string;
  border?: number;
};
export const ConsiderateMoonSlot = ({
  color,
  border = 0,
}: ConsiderateMoonSlotProps) => {
  return (
    <div className={cn("h-full w-full")} style={{ backgroundColor: color }}>
      {border > 0 ? <Border border={border} /> : null}
    </div>
  );
};

export type CoffeeMilkCircleColor = "BLACK" | "WHITE" | "GRAY";
// This is a slot that a tile can be placed in.
type ConsiderateMoonCircleSlotProps = {
  color: string;
  border: number;
  circle: CoffeeMilkCircleColor | undefined;
};
export const ConsiderateMoonCircleSlot = ({
  color,
  border,
  circle,
}: ConsiderateMoonCircleSlotProps) => {
  return (
    <div className={cn("h-full w-full")} style={{ backgroundColor: color }}>
      {border > 0 ? <Border border={border} /> : null}
      {circle && <CoffeeMilkClue clue={circle} />}
    </div>
  );
};

