export const HamSandwichClue = ({
  directions,
  numbers,
}: HamSandwichClueProps) => {
  // Fixed radius for all hexagons - large enough to cover all arrow/number pairs
  const HEXAGON_RADIUS = 45;

  return (
    <div className="solution-clue text-3xl font-bold text-white relative">
      {directions.map((d, i) => {
        // Calculate hexagon vertices (6 points) relative to center
        const hexPoints = Array.from({ length: 6 }, (_, j) => {
          const angle = (j * Math.PI) / 3 + Math.PI / 2;
          const x = Math.cos(angle) * HEXAGON_RADIUS;
          const y = Math.sin(angle) * HEXAGON_RADIUS;
          return `${x + HEXAGON_RADIUS},${y + HEXAGON_RADIUS}`;
        }).join(" ");

        return (
          <div key={`solution-clue-${i}`}>
            <svg
              className={cn(
                "absolute",
                d === 1
                  ? "solution-clue-hexagon-left"
                  : d === 3
                    ? "solution-clue-hexagon-top"
                    : "solution-clue-hexagon-bottom",
              )}
              style={{
                left: HEXAGON_OFFSETS[d].left,
                top: HEXAGON_OFFSETS[d].top,
                width: `${HEXAGON_RADIUS * 2}px`,
                height: `${HEXAGON_RADIUS * 2}px`,
              }}
              viewBox={`0 0 ${HEXAGON_RADIUS * 2} ${HEXAGON_RADIUS * 2}`}
            >
              <polygon points={hexPoints} fill="black" />
            </svg>
            <span
              key={`arrow-${i}`}
              className={cn(
                "absolute block",
                d === 1
                  ? "solution-clue-arrow-left"
                  : d === 3
                    ? "solution-clue-arrow-top"
                    : "solution-clue-arrow-bottom",
              )}
              style={{
                ...ARROW_OFFSETS[d],
                transform: `rotate(${(d - 1) * 60}deg)`,
              }}
            >
              →
            </span>
            <span
              key={`number-${i}`}
              className={cn(
                "absolute block",
                d === 1
                  ? "solution-clue-number-left"
                  : d === 3
                    ? "solution-clue-number-top"
                    : "solution-clue-number-bottom",
              )}
              style={NUMBER_OFFSETS[d]}
            >
              {numbers[i]}
            </span>
          </div>
        );
      })}
    </div>
  );
};

