type BTileProps = {
  tooltip?: string | undefined;
  text?: string | undefined;
  underlined?: boolean;
  color?:
    | "green"
    | "teal"
    | "blue"
    | "gray"
    | "red"
    | "yellow"
    | "white"
    | "landmark"
    | "transparent";
};

export const BTileRenderer = ({
  tooltip,
  text,
  color,
  underlined,
}: BTileProps) => {
  let background_color = "";
  let text_color = "#ffffff";
  switch (color) {
    case "green":
      background_color = "#076C37";
      text_color = "#ffffff";
      break;
    case "teal":
      background_color = "#29398E";
      text_color = "#ffffff";
      break;
    case "gray":
      background_color = "#6E6F71 ";
      text_color = "#ffffff";
      break;
    case "white":
      background_color = "#ffffff";
      text_color = "#000000";
      break;
    case "landmark":
      background_color = "#F0ECE1";
      text_color = "#000000";
      break;
    case "transparent":
      background_color = "transparent";
      text_color = "#000000";
      break;
    case "blue":
      background_color = "#379BD0 ";
      text_color = "#ffffff";
      break;
    case "yellow":
      background_color = "#FFCE05 ";
      text_color = "#000000";
      break;
    case "red":
      background_color = "#C2414B";
      text_color = "#ffffff";
      break;
  }
  return (
    <ConditionalTooltip tooltip={tooltip ?? undefined}>
      <div
        className="h-full w-full flex items-center justify-center"
        style={{ backgroundColor: background_color, color: text_color }}
      >
        {text && (
          <div
            className={cn(
              "text-center whitespace-pre-line w-full text-base font-bold",
              underlined && "underline",
            )}
          >
            {text}
          </div>
        )}
      </div>
    </ConditionalTooltip>
  );
};

