type PlaintextIndicatorProps = {
  text: string;
};

const indicatorImageMap: Record<string, string | undefined> = {
  exit: ExitIndicator,
  curse: CurseIndicator,
  treasure: TreasureIndicator,
  amulet: AmuletIndicator,
};

function PlaintextIndicator(props: PlaintextIndicatorProps) {
  const normalized = props.text.toLowerCase().replace(/\[|\]/g, "").trim();
  const imageSrc = indicatorImageMap[normalized];

  if (!imageSrc) {
    return null;
  }

  return (
    <div className="flex items-center justify-center h-full w-full relative">
      <img
        src={imageSrc}
        alt={normalized}
        className="h-full w-full object-contain opacity-50 pointer-events-none"
        draggable="false"
        style={{
          clipPath:
            "polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%)",
        }}
      />
    </div>
  );
}

