type HexBorderIndicatorProps = {
  edges?: number[];
};

const hexBorderPoints: [number, number][] = [
  [60, -5],
  [120, 25],
  [120, 90],
  [60, 125],
  [-5, 90],
  [-5, 25],
];

function HexBorderIndicator(props: HexBorderIndicatorProps) {
  const rawEdges = Array.isArray(props.edges) ? props.edges : [];
  const edges = rawEdges
    .map((edge) => Math.trunc(edge))
    .filter((edge) => edge >= 1 && edge <= 6);

  if (edges.length === 0) {
    return null;
  }

  return (
    <div
      className="absolute inset-0 h-full w-full pointer-events-none"
      style={{ zIndex: 10 }}
    >
      <svg
        viewBox="0 0 120 120"
        className="absolute inset-0 h-full w-full"
        style={{ overflow: "visible" }}
        role="presentation"
      >
        {edges.map((edge) => {
          const start = hexBorderPoints[edge - 1];
          const end = hexBorderPoints[edge % hexBorderPoints.length];
          return (
            <line
              key={edge}
              x1={start[0]}
              y1={start[1]}
              x2={end[0]}
              y2={end[1]}
              stroke="#1218c9"
              strokeWidth="12"
            />
          );
        })}
      </svg>
    </div>
  );
}

