import { levelAdjacencyMap } from "./__generated__/adjacency";
import type { LevelId } from "./types";

// Mapping from meta level IDs to puzzle slugs
export const META_LEVEL_TO_PUZZLE: Record<string, string> = {
  "d3m01-level": "lines",
  "d3m02-level": "tree",
  "d3m03-level": "playlist",
  "d3m04-level": "diamonds",
  "d3m05-level": "nicknames",
  "d3m06-level": "twenty_twenty_six",
  "d3m07-level": "the_hexagon",
};

/**
 * Get the gate ID for a solved tile level.
 * Gates for solved tile levels follow the pattern: `${levelId}:tile-level-solved`
 */
export function getSolvedGateId(levelId: string): string {
  return `${levelId}:tile-level-solved`;
}

export function getGrantedGateId(levelId: string): string {
  return `${levelId}:tile-level-granted`;
}

/**
 * Count how many gates from a list are satisfied.
 * @param satisfiedGates - Set of satisfied gate IDs
 * @param gateIds - Array of gate IDs to check
 * @returns Number of gates from the list that are satisfied
 */
export function countSatisfiedGates(
  satisfiedGates: Set<string>,
  gateIds: string[],
): number {
  return gateIds.filter((gateId) => satisfiedGates.has(gateId)).length;
}

/**
 * Check if a level is a meta level
 */
function isMetaLevel(levelId: string): boolean {
  return levelId in META_LEVEL_TO_PUZZLE;
}

/**
 * Get the puzzle slug for a meta level
 */
function getMetaLevelPuzzleSlug(levelId: string): string | undefined {
  return META_LEVEL_TO_PUZZLE[levelId];
}

/**
 * Determines the state of a level based on satisfied gates and puzzle unlock status.
 * @param levelId - The level ID to check
 * @param satisfiedGates - Set of satisfied gate IDs
 * @param puzzleUnlockedMap - Map of puzzle slug to whether the puzzle is unlocked (for meta levels)
 * @returns "locked" | "unlocked" | "solved"
 */
export function getLevelStateFromGates(
  levelId: string,
  satisfiedGates: Set<string>,
  puzzleUnlockedMap?: Map<string, boolean>,
): "locked" | "unlocked" | "solved" {
  const solvedGateId = getSolvedGateId(levelId);
  const grantedGateId = getGrantedGateId(levelId);

  // If the level is solved, return "solved"
  if (satisfiedGates.has(solvedGateId)) {
    return "solved";
  }

  // If the level is granted, return "unlocked"
  if (satisfiedGates.has(grantedGateId)) {
    return "unlocked";
  }

  // For meta levels, check if the corresponding puzzle is unlocked
  if (isMetaLevel(levelId)) {
    const puzzleSlug = getMetaLevelPuzzleSlug(levelId);
    if (puzzleSlug && puzzleUnlockedMap) {
      const isPuzzleUnlocked = puzzleUnlockedMap.get(puzzleSlug) ?? false;
      // Meta levels are locked unless their puzzle is unlocked
      return isPuzzleUnlocked ? "unlocked" : "locked";
    }
    // If puzzle unlock info not provided, default to locked for meta levels
    return "locked";
  }

  // Check if the level is unlocked by checking if any adjacent level is solved
  const adjacentLevels = levelAdjacencyMap[levelId as LevelId] ?? [];
  const hasSolvedAdjacent = adjacentLevels.some((adjacentId) =>
    satisfiedGates.has(getSolvedGateId(adjacentId)),
  );

  // Check if any level that unlocks this level is solved
  // We need to check all levels to see if this one is adjacent to any solved level
  if (hasSolvedAdjacent) {
    return "unlocked";
  }

  // Default level (intro-crossword-level) is always unlocked
  if (levelId === "intro-crossword-level") {
    return "unlocked";
  }

  return "locked";
}
