import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { IconLock } from "@tabler/icons-react";
import { parse } from "@twemoji/parser";

export function SimpleSlot({
  children,
  style,
  className,
}: {
  style?: React.CSSProperties;
  children?: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("h-full w-full", className)} style={style}>
      {children}
    </div>
  );
}

export function CenteredContent({
  children,
  style,
  className,
}: {
  children: React.ReactNode;
  style?: React.CSSProperties;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "flex items-center justify-center h-full w-full",
        className,
      )}
      style={style}
    >
      {children}
    </div>
  );
}

export function LockedTile({ ratioText }: { ratioText: string }) {
  return (
    <CenteredContent className="flex-col font-bold text-white bg-black">
      <IconLock className="w-1/3 h-1/3 text-white" />
      <div className="text-white text-md">{ratioText}</div>
    </CenteredContent>
  );
}

export function LetterContent({
  letter,
  className,
  style,
}: {
  letter: string;
  className?: string;
  style?: React.CSSProperties;
}) {
  return (
    <CenteredContent
      className={cn("text-3xl font-bold text-black", className)}
      style={
        style || {
          backgroundColor: "#ffffffb0",
        }
      }
    >
      {letter}
    </CenteredContent>
  );
}

const rgbToHex = (rgb: string) =>
  "#" +
  (rgb.match(/\d+/g) || [])
    .map((x) => (+x).toString(16).padStart(2, "0"))
    .join("");

export function ColorContent({
  color,
  border = false,
}: {
  color: string;
  border?: boolean;
}) {
  const HEX_POINTS =
    "50,0 99.5,28.8675 99.5,86.6025 50,115.4701 0,86.6025 0,28.8675";
  const CENTER_X = 50;
  const CENTER_Y = 57.73505;

  return (
    <ConditionalTooltip tooltip={rgbToHex(color)}>
      <svg
        className="block h-full w-full"
        // Regular pointy-top hex: height = 2/sqrt(3) * width ≈ 1.1547 * width
        viewBox="0 0 100 115.4701"
        preserveAspectRatio="xMidYMid meet"
        aria-label={rgbToHex(color)}
        role="img"
      >
        <polygon points={HEX_POINTS} fill={border ? "#000000" : color} />
        {border && (
          <polygon
            points={HEX_POINTS}
            fill={color}
            transform={
              border
                ? `translate(${CENTER_X} ${CENTER_Y}) scale(0.985) translate(-${CENTER_X} -${CENTER_Y})`
                : undefined
            }
          />
        )}
      </svg>
    </ConditionalTooltip>
  );
}

export function EmojiContent({ emoji }: { emoji: string }) {
  const twemojified = parse(emoji);
  return (
    <CenteredContent className="text-3xl font-bold text-black mix-blend-darken bg-white">
      {twemojified.map((emoji) => (
        <img
          className="inline-block w-[1em]"
          src={emoji.url}
          alt={emoji.text}
          key={emoji.text}
          draggable="false"
        />
      ))}
    </CenteredContent>
  );
}

// Twemojify a string that may contain multiple emojis
export function TileTwemojify(text: string, imageClassName: string) {
  const twemojified: (string | React.ReactNode)[] = [];
  let lastEmojiIndex = 0;
  for (const emoji of parse(text)) {
    const [start, end] = emoji.indices;
    if (start - lastEmojiIndex > 0) {
      twemojified.push(text.substring(lastEmojiIndex, start));
    }
    twemojified.push(
      <img
        key={start}
        src={emoji.url}
        alt={emoji.text}
        draggable="false"
        className={cn("inline", imageClassName)}
      />,
    );
    lastEmojiIndex = end;
  }

  if (lastEmojiIndex < text.length) {
    twemojified.push(text.substring(lastEmojiIndex));
  }
  return twemojified;
}

export function SubmissionSlot() {
  return <LetterContent letter="!"></LetterContent>;
}

// We used to have a separate renderer but now it's done on the GivenTile level.
export function UnusedTile(_props: { className?: string }) {
  return (
    <div
      style={{ backgroundColor: "#00000080", width: "100%", height: "100%" }}
    />
  );
}
