/**
 * Centralized definitions for final level unlock conditions.
 * These define which levels need to be solved to unlock each region's final/submission level.
 * These definitions are used both by transform functions (for UI display) and by gate definitions (for unlock logic).
 */

import { levelAdjacencyMap } from "./__generated__/adjacency";
import type { LevelId } from "./types";

export type FinalLevelUnlockDefinition = {
  /** The puzzle slug associated with this final level */
  puzzleSlug: string;
  /** List of level IDs that need to be solved to unlock the final level */
  levelIds: string[];
  /** Number of levels from levelIds that must be solved (for ratio display) */
  requiredCount: number;
};

