// Stuff in this file will pretty likely be sent to the client, be aware
import { createRegionBuilder } from "../../../levels/types";

type IndicatorContent = {
  word?: string;
};

function Indicator(props: IndicatorContent) {
  const isTiny = props.word && props.word.length > 15;
  return (
    <div className="w-full h-full flex flex-row items-center justify-center">
      <span className="text-black pb-12" style={{ fontSize: isTiny ? 10 : 14 }}>
        {props.word}
      </span>
    </div>
  );
}

export const crypticRegion = createRegionBuilder()
  .addSlotType("empty-slot-eager-heart", null)
  .addIndicatorType(
    "cryptic-indicator",
    Indicator as React.FC<Record<string, unknown>>,
  )
  .build();

export type CrypticAvailableSlots = keyof typeof crypticRegion.slots;
export type CrypticAvailableTiles = keyof typeof crypticRegion.tiles;
export type CrypticAvailableIndicators = keyof typeof crypticRegion.indicators;
