import { createLevelBuilder } from "../../../levels/types";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import aztec from "./assets/L/aztec.png";
import caper from "./assets/L/caper.png";
import creek from "./assets/L/creek.png";
import ember from "./assets/L/ember.png";
import fjord from "./assets/L/fjord.png";
import flint from "./assets/L/flint.png";
import hazel from "./assets/L/hazel.png";
import loom from "./assets/L/loom.png";
