import nixie from "./assets/L/nixie.png";
import onyx from "./assets/L/onyx.png";
import polyp from "./assets/L/polyp.png";
import quill from "./assets/L/quill.png";
import rivet from "./assets/L/rivet.png";
import scarf from "./assets/L/scarf.png";
import solutionL from "./assets/L/solution.json";
import spear from "./assets/L/spear.png";
import tango from "./assets/L/tango.png";
import valor from "./assets/L/valor.png";
import vegan from "./assets/L/vegan.png";
import {
  type worthwhileSuitAvailableIndicators,
  type worthwhileSuitAvailableSlots,
  type worthwhileSuitAvailableTileGroups,
} from "./client";
import { REGION_FLAVORTEXT } from "./constants";

const allCoords = [
  "-13,-20",
  "-12,-20",
  "-11,-20",
  "-10,-20",
  "-14,-19",
  "-13,-19",
  "-12,-19",
  "-11,-19",
  "-10,-19",
  "-13,-18",
  "-12,-18",
  "-11,-18",
  "-10,-18",
  "-9,-18",
  "-12,-17",
  "-11,-17",
  "-10,-17",
  "-11,-16",
  "-10,-16",
] as const;

type LevelLCoord = (typeof allCoords)[number];

const prePlacedCoords = new Set<LevelLCoord>([
  "-13,-20",
  "-12,-20",
  "-10,-20",
  "-13,-19",
  "-11,-19",
  "-10,-19",
  "-13,-18",
  "-10,-18",
  "-12,-17",
  "-11,-17",
  "-11,-16",
  "-10,-16",
]);

const tileImages: Record<LevelLCoord, string> = {
  "-13,-20": mango,
  "-12,-20": quill,
  "-11,-20": spear,
  "-10,-20": ember,
  "-14,-19": nixie,
  "-13,-19": flint,
  "-12,-19": caper,
  "-11,-19": loom,
  "-10,-19": hazel,
  "-13,-18": rivet,
  "-12,-18": tango,
  "-11,-18": vegan,
  "-10,-18": polyp,
  "-9,-18": fjord,
  "-12,-17": scarf,
  "-11,-17": valor,
  "-10,-17": aztec,
  "-11,-16": creek,
  "-10,-16": onyx,
};

const tileKeyByCoord: Record<LevelLCoord, string> = {
  "-13,-20": "mango",
  "-12,-20": "quill",
  "-11,-20": "spear",
  "-10,-20": "ember",
  "-14,-19": "nixie",
  "-13,-19": "flint",
  "-12,-19": "caper",
  "-11,-19": "loom",
  "-10,-19": "hazel",
  "-13,-18": "rivet",
  "-12,-18": "tango",
  "-11,-18": "vegan",
  "-10,-18": "polyp",
  "-9,-18": "fjord",
  "-12,-17": "scarf",
  "-11,-17": "valor",
  "-10,-17": "aztec",
  "-11,-16": "creek",
  "-10,-16": "onyx",
};

const tileIdFromCoord = (coord: LevelLCoord) => `${tileKeyByCoord[coord]}-tile`;

const levelLBuilder = createLevelBuilder<
  worthwhileSuitAvailableSlots,
  AllAvailableTiles,
  worthwhileSuitAvailableIndicators,
  worthwhileSuitAvailableTileGroups
>()
  .setFlavorText(REGION_FLAVORTEXT)
  .setTitle("No Droids Allowed")
  .setLevelFlavorText(
    "To verify their humanity, these cultural exchange students must pass a more difficult test by making some adjustments, but the way they'll read it won't change. It'll help to count to 7, 6, 3, and 5, and discard everything else.",
  )
  .addSlot("-13,-20", "worthwhile-suit-empty-slot")
  .addSlot("-12,-20", "worthwhile-suit-empty-slot")
  .addSlot("-11,-20", "worthwhile-suit-empty-slot")
  .addSlot("-10,-20", "worthwhile-suit-empty-slot")
  .addSlot("-14,-19", "worthwhile-suit-empty-slot")
  .addSlot("-13,-19", "worthwhile-suit-empty-slot")
  .addSlot("-12,-19", "worthwhile-suit-empty-slot")
  .addSlot("-11,-19", "worthwhile-suit-empty-slot")
  .addSlot("-10,-19", "worthwhile-suit-empty-slot")
  .addSlot("-13,-18", "worthwhile-suit-empty-slot")
  .addSlot("-12,-18", "worthwhile-suit-empty-slot")
  .addSlot("-11,-18", "worthwhile-suit-empty-slot")
  .addSlot("-10,-18", "worthwhile-suit-empty-slot")
  .addSlot("-9,-18", "worthwhile-suit-empty-slot")
  .addSlot("-12,-17", "worthwhile-suit-empty-slot")
  .addSlot("-11,-17", "worthwhile-suit-empty-slot")
  .addSlot("-10,-17", "worthwhile-suit-empty-slot")
  .addSlot("-11,-16", "worthwhile-suit-empty-slot")
  .addSlot("-10,-16", "worthwhile-suit-empty-slot");

prePlacedCoords.forEach((coord) => {
  levelLBuilder.addGivenTile(coord, {
    renderer: "worthwhile-suit-image-tile",
    props: {
      image: tileImages[coord],
    },
  });
});

const imageTileGroup: worthwhileSuitAvailableTileGroups =
  "worthwhile-suit-L-image-group";

const movableCoords = allCoords
  .filter((coord) => !prePlacedCoords.has(coord))
  .sort((a, b) => tileKeyByCoord[a].localeCompare(tileKeyByCoord[b]));

movableCoords.forEach((coord) => {
  levelLBuilder.addTileToBank(
    tileIdFromCoord(coord),
    1,
    {
      renderer: "worthwhile-suit-image-tile",
      props: {
        image: tileImages[coord],
      },
    },
    imageTileGroup,
  );
});

levelLBuilder.setSolution(solutionL);

export const levelL = levelLBuilder.build();
