import { createLevelBuilder } from "../../../levels/types";
import { type AllAvailableTiles } from "../all-regions-tile-renderer-registry";
import solutionI from "./assets/I/solution.json";
import { type worthwhileSuitAvailableSlots } from "./client";
import { REGION_FLAVORTEXT } from "./constants";

const levelITiles: Record<string, string> = {
  ac: "AC",
  la: "LA",
  le: "LE",
  nm: "NM",
  lu: "LU",
  og: "OG",
  on: "ON",
  ot: "OT",
  ra: "RA",
  st: "ST",
  te: "TE",
  ul: "UL",
  vi: "VI",
};

const levelIBuilder = createLevelBuilder<
  worthwhileSuitAvailableSlots,
  AllAvailableTiles
>()
  .setFlavorText(REGION_FLAVORTEXT)
  .setTitle("Tomes")
  .setLevelFlavorText(
    "Dear Travel Log, while searching for true happiness I knocked over thick volumes about the Book of Genesis, lab science equipment, nonconformism, visual art, and papal regalia.",
  )
  .addSlot("-24,-23", "worthwhile-suit-empty-slot")
  .addSlot("-23,-23", "worthwhile-suit-empty-slot")
  .addSlot("-22,-23", "worthwhile-suit-empty-slot")
  .addSlot("-24,-22", "worthwhile-suit-empty-slot")
  .addSlot("-23,-22", "worthwhile-suit-empty-slot")
  .addSlot("-22,-22", "worthwhile-suit-empty-slot")
  .addSlot("-21,-22", "worthwhile-suit-empty-slot")
  .addSlot("-24,-21", "worthwhile-suit-empty-slot")
  .addSlot("-23,-21", "worthwhile-suit-empty-slot")
  .addSlot("-22,-21", "worthwhile-suit-empty-slot")
  .addSlot("-23,-20", "worthwhile-suit-empty-slot")
  .addSlot("-22,-20", "worthwhile-suit-empty-slot")
  .addSlot("-21,-20", "worthwhile-suit-empty-slot")
  .addSlot("-24,-19", "worthwhile-suit-empty-slot")
  .addSlot("-23,-19", "worthwhile-suit-empty-slot")
  .addSlot("-22,-19", "worthwhile-suit-empty-slot")
  .addSlot("-21,-19", "worthwhile-suit-empty-slot")
  // Preplaced tiles
  .addGivenTile("-23,-22", {
    renderer: "text-tile",
    props: {
      letter: "DI",
    },
  })
  .addGivenTile("-24,-21", {
    renderer: "text-tile",
    props: {
      letter: "BR",
    },
  })
  .addGivenTile("-21,-20", {
    renderer: "text-tile",
    props: {
      letter: "EY",
    },
  })
  .addGivenTile("-23,-19", {
    renderer: "text-tile",
    props: {
      letter: "OC",
    },
  })
  .setSolution(solutionI);

Object.entries(levelITiles).forEach(([key, text]) => {
  levelIBuilder.addTileToBank(key.replace(/ /g, "-") + "-tile", 1, {
    renderer: "text-tile",
    props: {
      letter: text,
    },
  });
});

export const levelI = levelIBuilder.build();
