// Stuff in this file will pretty likely be sent to the client, be aware
import { IconArrowRight } from "@tabler/icons-react";
import { SubmissionSlot } from "../../../levels/component-utilities";
import { createRegionBuilder } from "../../../levels/types";

type AncientChickGivenProps = {
  text: string;
};
export function AncientChickGiven({ text }: AncientChickGivenProps) {
  return (
    <div className="w-full h-full flex flex-col items-center justify-center text-5xl">
      {text}
    </div>
  );
}

export const AncientChickArrowIndicator = () => {
  return (
    <div className="h-full w-full flex items-center pl-1">
      <IconArrowRight className="text-black w-10 h-10" />
    </div>
  );
};

export const ancientChickRegion = createRegionBuilder()
  .addSlotType(
    "submission-slot",
    SubmissionSlot as React.FC<Record<string, unknown>>,
  )
  .addSlotType("empty-slot-ancient-chick", null)
  .addIndicatorType(
    "ancient-chick-arrow-indicator",
    AncientChickArrowIndicator as React.FC<Record<string, unknown>>,
  )
  .build();

export type AncientChickAvailableSlots = keyof typeof ancientChickRegion.slots;
export type AncientChickAvailableTiles = keyof typeof ancientChickRegion.tiles;
export type AncientChickAvailableIndicators =
  keyof typeof ancientChickRegion.indicators;
